window.ETSDATA=window.ETSDATA||{};window.ETSDATA[16]={"lc":{"p1":[{"n":1,"opts":["She's shoveling snow from a walkway.","She's using walking sticks.","She's removing her cap.","She's drinking from a water bottle."],"vi":["Cô ấy đang xúc tuyết khỏi lối đi.","Cô ấy đang dùng gậy chống đi bộ.","Cô ấy đang tháo mũ ra.","Cô ấy đang uống nước từ chai nước."],"ans":"B","xp":"Ảnh một người: người phụ nữ đang đi trên tuyết, hai tay cầm gậy chống → (B) đúng.\n(A) sai: cô ấy không xúc tuyết (shovel). (C) sai: cô ấy vẫn đội mũ, không tháo. (D) sai: không uống nước.","a":"E24-T06-01.mp3","img":"q1.jpg"},{"n":2,"opts":["A woman is carrying a tray.","A woman is pushing a food trolley.","Some people are leaving a restaurant.","Some diners are looking out a window."],"vi":["Một người phụ nữ đang bưng một cái khay.","Một người phụ nữ đang đẩy xe đẩy thức ăn.","Một số người đang rời khỏi nhà hàng.","Một số thực khách đang nhìn ra cửa sổ."],"ans":"A","xp":"Bên phải ảnh, người phụ nữ đang bưng khay (carrying a tray) → (A) đúng.\n(B) sai: không có xe đẩy thức ăn (trolley) trong ảnh. (C) sai: mọi người đang ngồi ăn, không rời đi. (D) sai: không thấy cửa sổ.","a":"E24-T06-02.mp3","img":"q2.jpg"},{"n":3,"opts":["The man is holding a bucket of water.","The man is replacing a tire.","The man is watering a tree.","The man is scrubbing the front of a car."],"vi":["Người đàn ông đang cầm một xô nước.","Người đàn ông đang thay lốp xe.","Người đàn ông đang tưới cây.","Người đàn ông đang chà rửa phía trước một chiếc xe hơi."],"ans":"D","xp":"Người đàn ông đang chà rửa (scrub) phần đầu xe hơi → (D) đúng.\n(A) sai: không thấy xô nước (bucket). (B) sai: không thay lốp. (C) sai: không tưới cây.","a":"E24-T06-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some tiles are being installed on a roof.","An outdoor dining area is unoccupied.","Flowers have been placed on tables.","Some chairs have been arranged around a fountain."],"vi":["Ngói đang được lắp lên mái nhà.","Một khu vực ăn uống ngoài trời đang trống (không có người).","Hoa đã được đặt trên các bàn.","Một số ghế đã được xếp quanh một đài phun nước."],"ans":"B","xp":"Ảnh chỉ có bàn ghế ngoài trời, không có ai ngồi → khu ăn uống ngoài trời đang trống (unoccupied) → (B) đúng.\n(A) sai: không ai đang lắp ngói (being installed cần có người làm). (C) sai: không có hoa trên bàn. (D) sai: không có đài phun nước (fountain).","a":"E24-T06-04.mp3","img":"q4.jpg"},{"n":5,"opts":["Some people are gathered on top of a building.","Some trees are blocking the entrance to a stairway.","A woman is taking some stairs to a lower level.","A woman is walking across a pedestrian bridge."],"vi":["Một số người đang tụ tập trên nóc một tòa nhà.","Một số cái cây đang chắn lối vào cầu thang.","Một người phụ nữ đang đi cầu thang xuống tầng dưới.","Một người phụ nữ đang đi bộ qua cầu dành cho người đi bộ."],"ans":"C","xp":"Người phụ nữ đang đi xuống cầu thang (taking some stairs to a lower level) → (C) đúng.\n(A) sai vị trí: mọi người không ở trên nóc tòa nhà. (B) sai: cây không chắn lối vào cầu thang. (D) sai: không có cầu đi bộ (pedestrian bridge).","a":"E24-T06-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some wooden planter boxes have been set next to each other.","Some wood logs have been piled in a corner.","The outside walls of a house are made of bricks.","Some windows are being installed."],"vi":["Một số chậu cây bằng gỗ đã được đặt cạnh nhau.","Một số khúc gỗ đã được chất đống ở một góc.","Tường bên ngoài của một ngôi nhà được làm bằng gạch.","Một số cửa sổ đang được lắp đặt."],"ans":"A","xp":"Ảnh có các thùng trồng cây bằng gỗ (wooden planter boxes) đặt cạnh nhau (next to each other) → (A) đúng.\n(B) sai: không có khúc gỗ (logs) chất đống. (C) sai: không thấy tường gạch (bricks). (D) sai: không ai đang lắp cửa sổ.","a":"E24-T06-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"Who's going to take home the leftover cake?","qvi":"Ai sẽ mang phần bánh kem còn thừa về nhà?","opts":["Marcel said he would.","A lovely selection of desserts.","No, I thought it started at noon."],"vi":["Marcel nói là anh ấy sẽ mang.","Một tuyển chọn món tráng miệng tuyệt vời.","Không, tôi tưởng nó bắt đầu lúc trưa."],"ans":"A","xp":"Câu hỏi Who (ai) → (A) trả lời bằng tên người: Marcel nói anh ấy sẽ mang về → đúng.\n(B) bẫy liên tưởng: cake → desserts. (C) sai: câu hỏi Who không trả lời Yes/No.","a":"E24-T06-07.mp3"},{"n":8,"q":"Can you tell me where the security office is?","qvi":"Bạn có thể cho tôi biết phòng bảo vệ ở đâu không?","opts":["Today's my first day here.","A photograph for the badge.","Because it's after lunch."],"vi":["Hôm nay là ngày đầu tiên tôi ở đây.","Một tấm ảnh cho thẻ nhân viên.","Vì bây giờ đã qua giờ ăn trưa."],"ans":"A","xp":"Hỏi vị trí phòng bảo vệ (câu hỏi gián tiếp). (A) trả lời gián tiếp: hôm nay là ngày đầu tôi ở đây → ý là tôi không biết → đúng.\n(B) bẫy liên tưởng: security office → badge (thẻ). (C) trả lời cho câu hỏi Why, không liên quan.","a":"E24-T06-08.mp3"},{"n":9,"q":"What's the best way to contact you?","qvi":"Cách tốt nhất để liên lạc với bạn là gì?","opts":["On my mobile phone.","No, I have to wear glasses.","This résumé is better."],"vi":["Qua điện thoại di động của tôi.","Không, tôi phải đeo kính.","Bản sơ yếu lý lịch này tốt hơn."],"ans":"A","xp":"Hỏi cách liên lạc → (A) nêu cách cụ thể: gọi điện thoại di động → đúng.\n(B) sai: câu hỏi What không trả lời Yes/No. (C) bẫy từ: best → better.","a":"E24-T06-09.mp3"},{"n":10,"q":"Who's joining us for the waterfront boat ride?","qvi":"Ai sẽ tham gia chuyến đi thuyền ven biển cùng chúng ta?","opts":["Conference room three.","The admission fee is reasonable.","Everybody on our team is coming."],"vi":["Phòng họp số ba.","Phí vào cửa hợp lý.","Mọi người trong nhóm chúng ta đều đến."],"ans":"C","xp":"Hỏi Who (ai đi cùng) → (C) mọi người trong nhóm đều đi → đúng.\n(A) nói về địa điểm, không liên quan. (B) bẫy liên tưởng: boat ride → admission fee (phí vào cửa).","a":"E24-T06-10.mp3"},{"n":11,"q":"Could you request a technician to repair the packaging machine?","qvi":"Bạn có thể yêu cầu một kỹ thuật viên đến sửa máy đóng gói không?","opts":["Three years of technical school.","Sure, I'll do that.","The blue one with gold trim."],"vi":["Ba năm học trường kỹ thuật.","Chắc chắn rồi, tôi sẽ làm việc đó.","Cái màu xanh có viền vàng."],"ans":"B","xp":"Câu nhờ vả (Could you...?) → (B) đồng ý: Sure, tôi sẽ làm → đúng.\n(A) bẫy từ cùng gốc: technician → technical. (C) trả lời cho câu hỏi Which, không liên quan.","a":"E24-T06-11.mp3"},{"n":12,"q":"How many copies of the proposal should I make?","qvi":"Tôi nên photo bao nhiêu bản đề xuất?","opts":["There's blue paper in the cabinet.","Yes, it was my idea.","Fifty should be enough for everyone."],"vi":["Có giấy màu xanh trong tủ.","Vâng, đó là ý tưởng của tôi.","Năm mươi bản chắc là đủ cho mọi người."],"ans":"C","xp":"Hỏi How many (bao nhiêu bản) → (C) nêu con số cụ thể: 50 bản là đủ → đúng.\n(A) bẫy liên tưởng: copies → paper. (B) sai: câu hỏi How many không trả lời Yes/No.","a":"E24-T06-12.mp3"},{"n":13,"q":"Why is Jonathan leaving early?","qvi":"Tại sao Jonathan về sớm vậy?","opts":["To catch the six o'clock train.","On the early morning news.","That's where he lives now."],"vi":["Để kịp chuyến tàu lúc 6 giờ.","Trên bản tin sáng sớm.","Đó là nơi anh ấy sống bây giờ."],"ans":"A","xp":"Hỏi Why (lý do) → (A) To + động từ chỉ mục đích: để kịp chuyến tàu 6 giờ → đúng.\n(B) lặp từ early. (C) bẫy âm gần giống: leaving – lives.","a":"E24-T06-13.mp3"},{"n":14,"q":"Where's the company party being held?","qvi":"Tiệc công ty được tổ chức ở đâu?","opts":["It's a publishing firm.","Party of five at the table in the corner.","At the Chesterville Hotel."],"vi":["Đó là một công ty xuất bản.","Nhóm năm người ở bàn trong góc.","Tại khách sạn Chesterville."],"ans":"C","xp":"Hỏi Where (ở đâu) → (C) nêu địa điểm cụ thể: khách sạn Chesterville → đúng.\n(A) bẫy liên tưởng: company → firm. (B) lặp từ party.","a":"E24-T06-14.mp3"},{"n":15,"q":"Did you want to sign up for a one-year magazine subscription?","qvi":"Bạn có muốn đăng ký đặt tạp chí một năm không?","opts":["How much will it cost?","Near the service center.","Akiko works at the front desk."],"vi":["Nó tốn bao nhiêu tiền?","Gần trung tâm dịch vụ.","Akiko làm việc ở quầy lễ tân."],"ans":"A","xp":"Hỏi có muốn đăng ký tạp chí không → (A) hỏi lại giá tiền để quyết định → đúng (trả lời bằng câu hỏi ngược lại).\n(B) không liên quan. (C) bẫy liên tưởng: sign up → front desk.","a":"E24-T06-15.mp3"},{"n":16,"q":"Does this pasta come with a side salad?","qvi":"Món mì Ý này có kèm salad ăn kèm không?","opts":["We do have a tablecloth.","No, I'm afraid not.","I like it too."],"vi":["Chúng tôi có khăn trải bàn đấy.","Không, tôi e là không.","Tôi cũng thích nó."],"ans":"B","xp":"Câu hỏi Yes/No (Does...?) → (B) No, I'm afraid not = không có kèm → đúng.\n(A) không liên quan. (C) bẫy liên tưởng: pasta, salad → like (thích món ăn).","a":"E24-T06-16.mp3"},{"n":17,"q":"When can we meet about the invoices?","qvi":"Khi nào chúng ta có thể gặp nhau để bàn về các hóa đơn?","opts":["Supplies for the office.","I'm free after two.","Probably on Harold's desk."],"vi":["Đồ dùng cho văn phòng.","Tôi rảnh sau 2 giờ.","Có lẽ ở trên bàn của Harold."],"ans":"B","xp":"Hỏi When (khi nào) → (B) nêu thời gian: tôi rảnh sau 2 giờ → đúng.\n(A) bẫy liên tưởng: invoices → supplies. (C) trả lời cho câu hỏi Where.","a":"E24-T06-17.mp3"},{"n":18,"q":"Would you like me to help you open a savings account?","qvi":"Bạn có muốn tôi giúp bạn mở tài khoản tiết kiệm không?","opts":["I've already counted them.","That'd be great.","50 euros each."],"vi":["Tôi đã đếm chúng rồi.","Vậy thì tốt quá.","Mỗi cái 50 euro."],"ans":"B","xp":"Lời đề nghị giúp đỡ (Would you like me to...?) → (B) That'd be great = đồng ý, cảm ơn → đúng.\n(A) bẫy âm gần giống: account – counted. (C) bẫy liên tưởng: savings → 50 euros.","a":"E24-T06-18.mp3"},{"n":19,"q":"When did you post the job opening?","qvi":"Bạn đã đăng tin tuyển dụng khi nào?","opts":["On the bulletin board in the hallway.","It's been on the Web site for a month.","Can you close the door?"],"vi":["Trên bảng thông báo ở hành lang.","Nó đã được đăng trên trang web được một tháng rồi.","Bạn đóng cửa giúp được không?"],"ans":"B","xp":"Hỏi When (khi nào đăng) → (B) đã đăng trên web được một tháng → cho biết thời điểm → đúng.\n(A) trả lời cho câu hỏi Where. (C) bẫy liên tưởng: opening (chỗ trống/mở) → close.","a":"E24-T06-19.mp3"},{"n":20,"q":"Are you applying for the manager position?","qvi":"Bạn có đang ứng tuyển vào vị trí quản lý không?","opts":["About sixteen more employees.","I'll check her schedule again.","Yes... I hope I get it."],"vi":["Thêm khoảng mười sáu nhân viên.","Tôi sẽ kiểm tra lại lịch của cô ấy.","Vâng... tôi hy vọng mình được nhận."],"ans":"C","xp":"Câu hỏi Yes/No → (C) Yes, và hy vọng được nhận → đúng.\n(A) trả lời cho câu hỏi How many. (B) sai: 'her' không chỉ ai trong câu hỏi.","a":"E24-T06-20.mp3"},{"n":21,"q":"Are you traveling in business class or economy?","qvi":"Bạn đi hạng thương gia hay hạng phổ thông?","opts":["My flight was just canceled.","My focus is history.","London, then New York."],"vi":["Chuyến bay của tôi vừa bị hủy.","Tôi tập trung vào môn lịch sử.","London, sau đó là New York."],"ans":"A","xp":"Câu hỏi lựa chọn (A or B) → (A) trả lời gián tiếp: chuyến bay vừa bị hủy → không đi hạng nào cả → đúng.\n(B) bẫy liên tưởng: economy (kinh tế học) → history. (C) bẫy liên tưởng: traveling → London, New York.","a":"E24-T06-21.mp3"},{"n":22,"q":"The number of subscribers for our magazine has decreased recently.","qvi":"Số người đặt mua tạp chí của chúng ta gần đây đã giảm.","opts":["There's room in the budget for more advertising.","An annual membership fee.","There are six folders on the table."],"vi":["Ngân sách vẫn còn dư để quảng cáo thêm.","Phí thành viên hằng năm.","Có sáu bìa hồ sơ trên bàn."],"ans":"A","xp":"Câu trần thuật nêu vấn đề (lượng độc giả giảm) → (A) đưa ra giải pháp: ngân sách còn chỗ để quảng cáo thêm → đúng.\n(B) bẫy liên tưởng: subscribers → membership fee. (C) bẫy liên tưởng: number → six.","a":"E24-T06-22.mp3"},{"n":23,"q":"How do you clean the solar panels without damaging them?","qvi":"Bạn làm sạch các tấm pin mặt trời thế nào mà không làm hỏng chúng?","opts":["The glass can be any color you want.","No, the sun isn't out today.","I pay a company to do all the maintenance."],"vi":["Kính có thể là bất kỳ màu nào bạn muốn.","Không, hôm nay không có nắng.","Tôi trả tiền cho một công ty làm toàn bộ việc bảo trì."],"ans":"C","xp":"Hỏi How (cách làm sạch) → (C) tôi thuê công ty làm hết việc bảo trì → ý là tôi không tự làm → đúng.\n(A) không liên quan. (B) sai: câu hỏi How không trả lời Yes/No; bẫy liên tưởng solar → sun.","a":"E24-T06-23.mp3"},{"n":24,"q":"When will I receive my certificate in the mail?","qvi":"Khi nào tôi sẽ nhận được chứng chỉ qua đường bưu điện?","opts":["I'll have to check with the office.","Turn left at the light.","No, thank you."],"vi":["Tôi sẽ phải hỏi lại văn phòng.","Rẽ trái ở chỗ đèn giao thông.","Không, cảm ơn."],"ans":"A","xp":"Hỏi When → (A) trả lời gián tiếp: tôi phải hỏi văn phòng (= tôi chưa biết) → đúng.\n(B) trả lời cho câu hỏi chỉ đường (How/Where). (C) sai: câu hỏi When không trả lời Yes/No.","a":"E24-T06-24.mp3"},{"n":25,"q":"Don't we sell Ramirez lawn mowers?","qvi":"Chẳng phải chúng ta có bán máy cắt cỏ Ramirez sao?","opts":["The plants need more water.","Sorry, refunds are not allowed.","I work in the home decor area."],"vi":["Mấy cái cây cần thêm nước.","Xin lỗi, không được hoàn tiền.","Tôi làm ở khu đồ trang trí nội thất."],"ans":"C","xp":"Câu hỏi phủ định (có bán máy cắt cỏ không) → (C) trả lời gián tiếp: tôi làm ở khu trang trí nội thất → ý là tôi không rõ → đúng.\n(A) bẫy liên tưởng: lawn mowers → plants. (B) bẫy liên tưởng: sell → refunds.","a":"E24-T06-25.mp3"},{"n":26,"q":"Should we meet to discuss our research project?","qvi":"Chúng ta có nên gặp nhau để bàn về dự án nghiên cứu không?","opts":["A publishing manual.","Put something on my calendar.","Alphabetical order is fine, I think."],"vi":["Một cuốn sách hướng dẫn xuất bản.","Bạn cứ đặt lịch vào lịch làm việc của tôi nhé.","Tôi nghĩ xếp theo thứ tự bảng chữ cái là được."],"ans":"B","xp":"Câu đề nghị (Should we meet...?) → (B) hãy đặt một buổi hẹn vào lịch của tôi = đồng ý gặp → đúng.\n(A) và (C) không liên quan đến câu hỏi.","a":"E24-T06-26.mp3"},{"n":27,"q":"When does the cleaning staff leave for the day?","qvi":"Khi nào nhân viên dọn dẹp tan làm?","opts":["A supply closet in the hall.","By six o'clock, usually.","The leaves come out in the spring."],"vi":["Một tủ chứa đồ ở hành lang.","Thường là trước 6 giờ.","Lá cây mọc ra vào mùa xuân."],"ans":"B","xp":"Hỏi When (khi nào tan làm) → (B) thường là trước 6 giờ → đúng.\n(A) bẫy liên tưởng: cleaning → supply closet. (C) lặp âm leave – leaves (lá cây).","a":"E24-T06-27.mp3"},{"n":28,"q":"How would you like to pay for these shoes today?","qvi":"Hôm nay bạn muốn thanh toán đôi giày này bằng cách nào?","opts":["With a store gift card.","I wear a size 38.","A friend recommended them."],"vi":["Bằng thẻ quà tặng của cửa hàng.","Tôi đi cỡ 38.","Một người bạn đã giới thiệu chúng."],"ans":"A","xp":"Hỏi cách thanh toán → (A) bằng thẻ quà tặng của cửa hàng → đúng.\n(B) bẫy liên tưởng: shoes → size 38. (C) không liên quan.","a":"E24-T06-28.mp3"},{"n":29,"q":"It's an effective advertisement, isn't it?","qvi":"Đó là một quảng cáo hiệu quả, phải không?","opts":["I've heard that sales have increased.","The next issue of the magazine.","Isn't the policy in effect already?"],"vi":["Tôi nghe nói doanh số đã tăng.","Số tạp chí kỳ tới.","Chẳng phải chính sách đó đã có hiệu lực rồi sao?"],"ans":"A","xp":"Câu hỏi đuôi (quảng cáo hiệu quả, đúng không?) → (A) nghe nói doanh số tăng → gián tiếp đồng ý là hiệu quả → đúng.\n(B) bẫy liên tưởng: advertisement → magazine. (C) bẫy từ cùng gốc: effective → effect.","a":"E24-T06-29.mp3"},{"n":30,"q":"Why don't we take a walk after lunch?","qvi":"Sao chúng ta không đi dạo sau bữa trưa nhỉ?","opts":["The sales report is due at one o'clock.","No, in parking area B.","I'll have spaghetti, please."],"vi":["Báo cáo doanh số phải nộp lúc 1 giờ.","Không, ở khu đỗ xe B.","Cho tôi món mì spaghetti."],"ans":"A","xp":"Why don't we...? là lời rủ rê, không phải hỏi lý do. (A) báo cáo phải nộp lúc 1 giờ → gián tiếp từ chối (không có thời gian) → đúng.\n(B) không liên quan. (C) bẫy liên tưởng: lunch → spaghetti.","a":"E24-T06-30.mp3"},{"n":31,"q":"I decided to move the seasonal merchandise to the front of the store.","qvi":"Tôi đã quyết định chuyển hàng theo mùa ra phía trước cửa hàng.","opts":["Did you put some of it in the window display?","For our summer clothing collection.","The moving van is coming tomorrow."],"vi":["Bạn có đặt một ít hàng ở tủ kính trưng bày không?","Cho bộ sưu tập quần áo mùa hè của chúng ta.","Xe tải chuyển nhà sẽ đến vào ngày mai."],"ans":"A","xp":"Câu trần thuật → (A) hỏi thêm thông tin liên quan: có bày một phần ở tủ kính không → đúng.\n(B) bẫy liên tưởng: seasonal → summer. (C) bẫy từ cùng gốc: move → moving.","a":"E24-T06-31.mp3"}],"p3":[{"ns":[32,34],"script":[["M","The renovations we're planning for the theater are long overdue.","Việc cải tạo nhà hát mà chúng ta đang lên kế hoạch lẽ ra phải làm từ lâu rồi."],["W","I'm glad we have time between productions so we can get the work done.","Tôi mừng là chúng ta có thời gian giữa các vở diễn để làm xong công việc."],["M","I agree—and even though it's great that our latest musical production has had such a successful run, we can all use the break.","Tôi đồng ý — và dù thật tuyệt khi vở nhạc kịch mới nhất của chúng ta được công diễn thành công như vậy, tất cả chúng ta đều cần nghỉ ngơi một chút."],["W","Plus, it gives us time to focus on next month's fund-raiser.","Thêm nữa, nó cho chúng ta thời gian để tập trung vào buổi gây quỹ vào tháng sau."],["M","Hopefully we'll raise enough money at that event to replace the old lighting system too.","Hy vọng là chúng ta sẽ quyên đủ tiền ở sự kiện đó để thay luôn hệ thống đèn cũ."]],"qs":[{"n":32,"q":"What are the speakers mainly discussing?","qvi":"Những người nói chủ yếu đang thảo luận về điều gì?","opts":["Theater renovations","Changes to a performance schedule","Selection of a new lighting director","A promotional gift"],"vi":["Việc cải tạo nhà hát","Thay đổi lịch biểu diễn","Việc chọn đạo diễn ánh sáng mới","Một món quà khuyến mãi"],"ans":"A","xp":"Câu hỏi chủ đề → nghe phần đầu. Người đàn ông mở đầu: \"The renovations we're planning for the theater are long overdue.\" và người phụ nữ tiếp lời về việc làm xong công việc cải tạo → chủ đề là cải tạo nhà hát (Theater renovations)."},{"n":33,"q":"What does the man say about a musical production?","qvi":"Người đàn ông nói gì về một vở nhạc kịch?","opts":["It was based on a book.","It has been successful.","It will be performed overseas.","Some casting changes were made."],"vi":["Nó dựa trên một cuốn sách.","Nó đã thành công.","Nó sẽ được biểu diễn ở nước ngoài.","Đã có một số thay đổi về diễn viên."],"ans":"B","xp":"Người đàn ông nói: \"it's great that our latest musical production has had such a successful run\" (vở nhạc kịch mới nhất được công diễn rất thành công) → (B) It has been successful."},{"n":34,"q":"What event are the speakers planning?","qvi":"Những người nói đang lên kế hoạch cho sự kiện gì?","opts":["A press conference","A fund-raiser","An audition","An autograph session"],"vi":["Một buổi họp báo","Một buổi gây quỹ","Một buổi thử vai","Một buổi ký tặng"],"ans":"B","xp":"Người phụ nữ: \"it gives us time to focus on next month's fund-raiser\"; người đàn ông: \"Hopefully we'll raise enough money at that event...\" → họ đang chuẩn bị buổi gây quỹ (fund-raiser)."}],"a":"E24-T06-32-34.mp3"},{"ns":[35,37],"script":[["M","Fernanda, I wanted to tell you that the top candidate we chose for the customer-care position just accepted our job offer. I'll send him a contract later today.","Fernanda, tôi muốn báo với chị là ứng viên hàng đầu mà chúng ta chọn cho vị trí chăm sóc khách hàng vừa nhận lời mời làm việc. Chiều nay tôi sẽ gửi hợp đồng cho anh ấy."],["W","Great! But now I think we need a bigger office space for our business. With the new hire, there'll be ten of us in the office.","Tuyệt quá! Nhưng giờ tôi nghĩ chúng ta cần một văn phòng rộng hơn. Có thêm nhân viên mới thì văn phòng sẽ có mười người."],["M","I agree. Our lease expires next month, so we should look at a different space. There's a new office building on Second Street. It has solar panels, so all of its energy comes from renewable sources.","Tôi đồng ý. Hợp đồng thuê của chúng ta hết hạn vào tháng sau, nên chúng ta nên xem chỗ khác. Có một tòa nhà văn phòng mới trên đường Second. Nó có tấm pin mặt trời, nên toàn bộ năng lượng đều từ nguồn tái tạo."],["W","I like that. But I'm worried we may not be able to afford the lease.","Tôi thích điều đó. Nhưng tôi lo là chúng ta có thể không đủ tiền thuê."],["M","We'll see. I'll contact the rental agency today.","Để xem đã. Hôm nay tôi sẽ liên hệ với công ty cho thuê."]],"qs":[{"n":35,"q":"What did the speakers recently do?","qvi":"Những người nói gần đây đã làm gì?","opts":["They launched a new product.","They chose a job candidate.","They moved to a different city.","They renovated a space."],"vi":["Họ ra mắt một sản phẩm mới.","Họ đã chọn một ứng viên.","Họ chuyển đến một thành phố khác.","Họ đã cải tạo một không gian."],"ans":"B","xp":"Người đàn ông: \"the top candidate we chose for the customer-care position just accepted our job offer\" → họ vừa chọn được ứng viên cho vị trí chăm sóc khách hàng → (B)."},{"n":36,"q":"What do the speakers like about a building?","qvi":"Những người nói thích điều gì ở một tòa nhà?","opts":["It provides 24-hour access.","It has an outdoor space.","It is near public transportation.","It uses renewable energy."],"vi":["Nó cho phép ra vào 24 giờ.","Nó có không gian ngoài trời.","Nó gần phương tiện giao thông công cộng.","Nó sử dụng năng lượng tái tạo."],"ans":"D","xp":"Người đàn ông: \"It has solar panels, so all of its energy comes from renewable sources.\" → người phụ nữ: \"I like that.\" → họ thích việc tòa nhà dùng năng lượng tái tạo. Paraphrase: energy comes from renewable sources → uses renewable energy."},{"n":37,"q":"What is the woman worried about?","qvi":"Người phụ nữ lo lắng về điều gì?","opts":["A new competitor","A longer commute","A high price","An upcoming deadline"],"vi":["Một đối thủ cạnh tranh mới","Quãng đường đi làm dài hơn","Giá cao","Một hạn chót sắp đến"],"ans":"C","xp":"Người phụ nữ: \"I'm worried we may not be able to afford the lease.\" (lo không đủ tiền thuê) → giá thuê cao → (C) A high price."}],"a":"E24-T06-35-37.mp3"},{"ns":[38,40],"script":[["M","How can I help you?","Tôi có thể giúp gì cho chị?"],["W","Hi, I'd like to order a cake for my son's birthday next week. He really likes dinosaurs.","Chào anh, tôi muốn đặt một chiếc bánh kem cho sinh nhật con trai tôi vào tuần sau. Cháu rất thích khủng long."],["M","I have several different dinosaur-shaped pans for you to choose from.","Tôi có vài loại khuôn hình khủng long khác nhau để chị chọn."],["W","Actually, I was hoping you could make a standing cake instead of a flat one.","Thật ra tôi mong anh có thể làm một chiếc bánh dựng đứng thay vì bánh phẳng."],["M","Oh, I see. I'm sorry. I do have someone on staff who can make those, but she's all booked up for the next few weeks. Try Carmen's Creations on Pine Street.","À, tôi hiểu rồi. Xin lỗi chị. Tôi có một nhân viên làm được loại đó, nhưng cô ấy đã kín lịch trong vài tuần tới. Chị thử đến tiệm Carmen's Creations trên đường Pine xem."]],"qs":[{"n":38,"q":"What event is the woman planning?","qvi":"Người phụ nữ đang lên kế hoạch cho sự kiện gì?","opts":["A retirement party","A birthday party","A science fair","A school festival"],"vi":["Tiệc nghỉ hưu","Tiệc sinh nhật","Hội chợ khoa học","Lễ hội trường học"],"ans":"B","xp":"Người phụ nữ: \"I'd like to order a cake for my son's birthday next week.\" → cô ấy đang chuẩn bị tiệc sinh nhật cho con trai → (B)."},{"n":39,"q":"Who most likely is the man?","qvi":"Người đàn ông nhiều khả năng là ai?","opts":["A baker","A musician","A gardener","A teacher"],"vi":["Thợ làm bánh","Nhạc sĩ","Người làm vườn","Giáo viên"],"ans":"A","xp":"Người phụ nữ đặt bánh kem, người đàn ông trả lời: \"I have several different dinosaur-shaped pans for you to choose from.\" (có nhiều khuôn bánh hình khủng long) → anh ấy là thợ làm bánh (baker)."},{"n":40,"q":"Why does the man apologize?","qvi":"Tại sao người đàn ông xin lỗi?","opts":["Some tools cannot be found.","Some invitations were sent late.","A store is closed for a holiday.","A request cannot be fulfilled."],"vi":["Không tìm thấy một số dụng cụ.","Một số thiệp mời đã được gửi trễ.","Cửa hàng đóng cửa nghỉ lễ.","Một yêu cầu không thể đáp ứng được."],"ans":"D","xp":"Người phụ nữ muốn bánh dựng đứng (standing cake); người đàn ông: \"I'm sorry. I do have someone on staff who can make those, but she's all booked up for the next few weeks.\" → anh ấy không thể đáp ứng yêu cầu của cô → (D)."}],"a":"E24-T06-38-40.mp3"},{"ns":[41,43],"script":[["W","Hello, you've reached Quick Phone Repair Service.","Xin chào, đây là Dịch vụ Sửa điện thoại Nhanh."],["M","Hi, I went online to schedule a repair for my mobile phone, but all appointments in your store were booked for today. Have you had any cancellations?","Chào chị, tôi đã lên mạng để đặt lịch sửa điện thoại di động, nhưng tất cả lịch hẹn ở cửa hàng hôm nay đều kín rồi. Có ai hủy lịch không ạ?"],["W","No, unfortunately not. What's the problem with your phone?","Rất tiếc là không. Điện thoại của anh bị làm sao vậy?"],["M","The phone only lasts about an hour before it has to be recharged.","Điện thoại chỉ dùng được khoảng một tiếng là phải sạc lại."],["W","It sounds like you need a new battery. If you come to the store now, we can try to fit you in as a walk-in appointment. You may have to wait around for a bit.","Có vẻ như anh cần thay pin mới. Nếu anh đến cửa hàng ngay bây giờ, chúng tôi có thể cố xếp cho anh như khách đến trực tiếp không hẹn trước. Anh có thể phải đợi một chút."],["M","I don't mind waiting.","Tôi không ngại đợi đâu."]],"qs":[{"n":41,"q":"What did the man try to do online?","qvi":"Người đàn ông đã cố làm gì trên mạng?","opts":["Purchase a new phone","Make an appointment","Order a part","Cancel a contract"],"vi":["Mua điện thoại mới","Đặt lịch hẹn","Đặt mua một linh kiện","Hủy hợp đồng"],"ans":"B","xp":"Người đàn ông: \"I went online to schedule a repair for my mobile phone\" → anh ấy lên mạng để đặt lịch sửa chữa. Paraphrase: schedule a repair → Make an appointment."},{"n":42,"q":"What does the man say is wrong with his mobile phone?","qvi":"Người đàn ông nói điện thoại của anh ấy có vấn đề gì?","opts":["It has a short battery life.","The screen is damaged.","A cable is missing.","It has limited storage space."],"vi":["Pin dùng được rất ngắn.","Màn hình bị hỏng.","Thiếu một sợi cáp.","Bộ nhớ có hạn."],"ans":"A","xp":"Người đàn ông: \"The phone only lasts about an hour before it has to be recharged.\" (chỉ dùng được khoảng 1 tiếng là phải sạc) → pin yếu, thời lượng ngắn → (A)."},{"n":43,"q":"What will the man most likely do next?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?","opts":["Speak with a manager","Call technical support","Visit a store","Restart a device"],"vi":["Nói chuyện với quản lý","Gọi bộ phận hỗ trợ kỹ thuật","Đến cửa hàng","Khởi động lại thiết bị"],"ans":"C","xp":"Người phụ nữ: \"If you come to the store now, we can try to fit you in...\"; người đàn ông: \"I don't mind waiting.\" → anh ấy sẽ đến cửa hàng. Paraphrase: come to the store → Visit a store."}],"a":"E24-T06-41-43.mp3"},{"ns":[44,46],"script":[["M","Asako, how far along are you on that news report about the bank merger? If you want it to be included in tomorrow morning's newspaper, it has to be on my desk by nine P.M.","Asako, bài tin về vụ sáp nhập ngân hàng chị làm đến đâu rồi? Nếu chị muốn nó được đăng trên số báo sáng mai thì nó phải có trên bàn tôi trước 9 giờ tối."],["W","Well, I'm still doing research for this article. I'm having trouble getting all the facts from the people involved. They haven't returned my phone calls.","À, tôi vẫn đang tìm hiểu thông tin cho bài này. Tôi đang gặp khó khăn trong việc lấy đủ thông tin từ những người liên quan. Họ chưa gọi lại cho tôi."],["M","Well, we can't print the story without confirming the details. But if you can have it finished by Wednesday night, I can put it in Thursday's paper.","Ừm, chúng ta không thể in bài khi chưa xác nhận các chi tiết. Nhưng nếu chị có thể hoàn thành trước tối thứ Tư, tôi có thể đăng nó trên số báo thứ Năm."]],"qs":[{"n":44,"q":"Where do the speakers most likely work?","qvi":"Những người nói nhiều khả năng làm việc ở đâu?","opts":["At a bank","At a research laboratory","At a newspaper company","At a legal firm"],"vi":["Ở ngân hàng","Ở phòng thí nghiệm nghiên cứu","Ở tòa soạn báo","Ở công ty luật"],"ans":"C","xp":"Người đàn ông hỏi về \"that news report about the bank merger\" và nói \"If you want it to be included in tomorrow morning's newspaper...\" → họ làm ở tòa soạn báo. (A) là bẫy: bank chỉ là chủ đề bài báo."},{"n":45,"q":"Why has the woman been unable to finish a task?","qvi":"Tại sao người phụ nữ chưa thể hoàn thành công việc?","opts":["She needs a manager's signature.","She cannot access her files.","She cannot get the necessary information.","Some data are incorrect."],"vi":["Cô ấy cần chữ ký của quản lý.","Cô ấy không truy cập được tệp của mình.","Cô ấy không lấy được thông tin cần thiết.","Một số dữ liệu bị sai."],"ans":"C","xp":"Người phụ nữ: \"I'm having trouble getting all the facts from the people involved. They haven't returned my phone calls.\" → cô ấy chưa lấy được thông tin cần thiết. Paraphrase: getting all the facts → get the necessary information."},{"n":46,"q":"What solution does the man propose?","qvi":"Người đàn ông đề xuất giải pháp gì?","opts":["Changing a deadline","Scheduling a meeting","Asking a colleague for help","Reviewing some documents"],"vi":["Thay đổi hạn chót","Sắp xếp một cuộc họp","Nhờ đồng nghiệp giúp đỡ","Xem lại một số tài liệu"],"ans":"A","xp":"Ban đầu hạn là 9 giờ tối nay; người đàn ông đề xuất: \"if you can have it finished by Wednesday night, I can put it in Thursday's paper.\" → lùi hạn chót sang tối thứ Tư → (A) Changing a deadline."}],"a":"E24-T06-44-46.mp3"},{"ns":[47,49],"script":[["M","We'll have to remove the soil from the garden bed and lay down drainpipes that'll take the water out through holes in the retaining wall.","Chúng tôi sẽ phải dọn đất khỏi luống vườn và đặt ống thoát nước để dẫn nước ra ngoài qua các lỗ trên tường chắn."],["W","Sounds like a lot of work, but it'll be worth it to be able to grow the garden that I want to.","Nghe có vẻ nhiều việc đấy, nhưng sẽ đáng công nếu tôi có thể trồng được khu vườn như tôi muốn."],["M","Do you think you'd like bricks or stones for the retaining wall? Many homeowners prefer brick because it creates a nice, uniform look. But stones will last longer. They are more expensive, though.","Chị muốn làm tường chắn bằng gạch hay bằng đá? Nhiều chủ nhà thích gạch vì nó tạo vẻ đẹp đồng đều. Nhưng đá sẽ bền lâu hơn. Tuy nhiên, đá đắt hơn."],["W","I don't want to have to make repairs.","Tôi không muốn phải sửa chữa đâu."],["M","You have several different kinds of stones to choose from. I have some pictures of projects I've completed in the past you can look at.","Có vài loại đá khác nhau để chị chọn. Tôi có vài tấm ảnh các công trình tôi đã làm trước đây để chị xem."]],"qs":[{"n":47,"q":"What kind of work does the man do?","qvi":"Người đàn ông làm loại công việc gì?","opts":["Appliance repair","Painting","Landscaping","Roofing"],"vi":["Sửa đồ gia dụng","Sơn","Làm cảnh quan sân vườn","Lợp mái"],"ans":"C","xp":"Người đàn ông: \"We'll have to remove the soil from the garden bed and lay down drainpipes...\" và nói về tường chắn trong vườn → anh ấy làm cảnh quan sân vườn (landscaping)."},{"n":48,"q":"What does the woman imply when she says, \"I don't want to have to make repairs\"?","qvi":"Người phụ nữ ngụ ý gì khi nói \"Tôi không muốn phải sửa chữa đâu\"?","opts":["She is not qualified for a task.","She prefers durable materials.","She will buy a new appliance.","She is not happy with a cost estimate."],"vi":["Cô ấy không đủ trình độ cho một công việc.","Cô ấy thích vật liệu bền.","Cô ấy sẽ mua một thiết bị mới.","Cô ấy không hài lòng với bảng báo giá."],"ans":"B","xp":"Câu hàm ý. Ngay trước đó người đàn ông nói: \"stones will last longer. They are more expensive, though.\" Cô ấy đáp không muốn phải sửa chữa → nghĩa là cô ấy chọn loại bền (đá) dù đắt hơn → (B) thích vật liệu bền."},{"n":49,"q":"What will the man show to the woman?","qvi":"Người đàn ông sẽ cho người phụ nữ xem gì?","opts":["A list of prices","A license","Some references","Some photographs"],"vi":["Bảng giá","Giấy phép","Thư giới thiệu/người tham chiếu","Một số bức ảnh"],"ans":"D","xp":"Người đàn ông: \"I have some pictures of projects I've completed in the past you can look at.\" → cho xem ảnh. Paraphrase: pictures → photographs."}],"a":"E24-T06-47-49.mp3"},{"ns":[50,52],"script":[["W","Good morning. You've reached Accounts Payable.","Chào buổi sáng. Đây là phòng Kế toán Phải trả."],["M","Hi. I'm calling from the editorial department. One of our freelance writers has not received payment yet, so I'm calling to inquire about it. Her contract number is 9356.","Chào chị. Tôi gọi từ phòng biên tập. Một người viết tự do của chúng tôi vẫn chưa nhận được tiền, nên tôi gọi để hỏi về việc này. Số hợp đồng của cô ấy là 9356."],["W","OK, let me check. Hmm. It looks like she should have been paid last week. But Adem handles those requests, and he was on vacation. He's just catching up today.","Vâng, để tôi kiểm tra. Hmm. Có vẻ như lẽ ra cô ấy đã được thanh toán từ tuần trước. Nhưng Adem là người xử lý các yêu cầu đó, và anh ấy đi nghỉ phép. Hôm nay anh ấy mới đang giải quyết các việc còn tồn đọng."],["M","Do you have an estimate of how long it will take to process the request?","Chị có ước tính được mất bao lâu để xử lý yêu cầu không?"],["W","I'm not sure, but I can speak to Adem.","Tôi không chắc, nhưng tôi có thể hỏi Adem."]],"qs":[{"n":50,"q":"Why is the man calling?","qvi":"Tại sao người đàn ông gọi điện?","opts":["To track a shipment","To ask about a payment","To close an account","To request computer help"],"vi":["Để theo dõi một lô hàng","Để hỏi về một khoản thanh toán","Để đóng một tài khoản","Để nhờ hỗ trợ máy tính"],"ans":"B","xp":"Người đàn ông: \"One of our freelance writers has not received payment yet, so I'm calling to inquire about it.\" → gọi để hỏi về khoản thanh toán. Paraphrase: inquire → ask."},{"n":51,"q":"According to the woman, what caused a delay?","qvi":"Theo người phụ nữ, điều gì đã gây ra sự chậm trễ?","opts":["An employee was out of the office.","A software program was updated.","A document was mislabeled.","A new policy was implemented."],"vi":["Một nhân viên vắng mặt ở văn phòng.","Một phần mềm được cập nhật.","Một tài liệu bị dán nhãn sai.","Một chính sách mới được áp dụng."],"ans":"A","xp":"Người phụ nữ: \"Adem handles those requests, and he was on vacation.\" → người phụ trách đi nghỉ phép nên bị chậm. Paraphrase: was on vacation → was out of the office."},{"n":52,"q":"What information will the woman most likely provide later?","qvi":"Người phụ nữ nhiều khả năng sẽ cung cấp thông tin gì sau đó?","opts":["A cost breakdown","An account number","A time estimate","A phone number"],"vi":["Bảng chi phí chi tiết","Số tài khoản","Thời gian ước tính","Số điện thoại"],"ans":"C","xp":"Người đàn ông hỏi: \"Do you have an estimate of how long it will take to process the request?\"; cô ấy đáp: \"I'm not sure, but I can speak to Adem.\" → sau khi hỏi Adem, cô ấy sẽ cho biết thời gian ước tính → (C)."}],"a":"E24-T06-50-52.mp3"},{"ns":[53,55],"script":[["M1","I'm the general manager here at Rev It Auto Repair, and this is Mr. Singh, our service manager. We're eager to hear how your product can benefit our shop.","Tôi là tổng quản lý ở tiệm sửa xe Rev It Auto Repair, còn đây là anh Singh, quản lý dịch vụ của chúng tôi. Chúng tôi rất muốn nghe sản phẩm của chị có thể mang lại lợi ích gì cho tiệm."],["W","Well, my product is called Video Room. It's a library of short videos that your business can offer in the waiting room. These videos will explain common auto repairs and educate your customers on the repair process.","Vâng, sản phẩm của tôi tên là Video Room. Đó là một thư viện video ngắn mà tiệm có thể chiếu trong phòng chờ. Các video này sẽ giải thích những công việc sửa xe thông thường và giúp khách hàng hiểu về quy trình sửa chữa."],["M2","Can we add our own customized content? I'd love to include a description of our exclusive lifetime warranty.","Chúng tôi có thể thêm nội dung riêng của mình không? Tôi rất muốn đưa vào phần giới thiệu về chế độ bảo hành trọn đời độc quyền của chúng tôi."],["M1","Yes. And can we also add at-home auto-care advice?","Đúng vậy. Và chúng tôi có thể thêm lời khuyên tự chăm sóc xe tại nhà không?"]],"qs":[{"n":53,"q":"Where does the conversation take place?","qvi":"Cuộc hội thoại diễn ra ở đâu?","opts":["At a game arcade","At a grocery store","At an auto repair shop","At a parking garage"],"vi":["Ở khu trò chơi điện tử","Ở cửa hàng tạp hóa","Ở tiệm sửa xe ô tô","Ở bãi đỗ xe"],"ans":"C","xp":"Người đàn ông thứ nhất: \"I'm the general manager here at Rev It Auto Repair\" → cuộc trò chuyện diễn ra ở tiệm sửa xe ô tô (auto repair shop)."},{"n":54,"q":"What type of product does the woman mention?","qvi":"Người phụ nữ nhắc đến loại sản phẩm nào?","opts":["Some videos","Some brochures","A price scanner","A mobile phone application"],"vi":["Các video","Các tờ quảng cáo","Một máy quét giá","Một ứng dụng điện thoại"],"ans":"A","xp":"Người phụ nữ: \"my product is called Video Room. It's a library of short videos that your business can offer in the waiting room.\" → sản phẩm là các video ngắn → (A)."},{"n":55,"q":"What do the men want to do?","qvi":"Hai người đàn ông muốn làm gì?","opts":["Extend business hours","Enter a local contest","Include customized content","Upgrade some equipment"],"vi":["Kéo dài giờ làm việc","Tham gia một cuộc thi ở địa phương","Đưa nội dung riêng (tùy chỉnh) vào","Nâng cấp một số thiết bị"],"ans":"C","xp":"Người đàn ông thứ hai hỏi: \"Can we add our own customized content?\" và người thứ nhất thêm: \"can we also add at-home auto-care advice?\" → cả hai muốn đưa nội dung riêng của tiệm vào video → (C)."}],"a":"E24-T06-53-55.mp3"},{"ns":[56,58],"script":[["M","Hi, Carmen. I've just reviewed the outline you gave me for the nature documentary we're making. I think it'll be a great film, but I'm a bit concerned. I want it to be less than an hour.","Chào Carmen. Tôi vừa xem bản đề cương chị đưa cho bộ phim tài liệu về thiên nhiên mà chúng ta đang làm. Tôi nghĩ nó sẽ là một bộ phim hay, nhưng tôi hơi lo. Tôi muốn nó dài dưới một tiếng."],["W","I understand. I'll take another look at it and see where I can take out some unnecessary scenes from the storyboard.","Tôi hiểu. Tôi sẽ xem lại và tìm chỗ có thể bỏ bớt vài cảnh không cần thiết trong kịch bản phân cảnh."],["M","Great. In the meantime, I need to follow up with our camera team to make sure they have all the equipment they need to begin filming.","Tốt quá. Trong lúc đó, tôi cần liên hệ với đội quay phim để chắc chắn họ có đủ thiết bị cần thiết để bắt đầu quay."]],"qs":[{"n":56,"q":"What industry do the speakers most likely work in?","qvi":"Những người nói nhiều khả năng làm việc trong ngành nào?","opts":["Fashion photography","Information technology","Filmmaking","Marketing"],"vi":["Chụp ảnh thời trang","Công nghệ thông tin","Làm phim","Tiếp thị"],"ans":"C","xp":"Người đàn ông: \"the nature documentary we're making. I think it'll be a great film\" → họ đang làm phim tài liệu → ngành làm phim (Filmmaking)."},{"n":57,"q":"What does the man imply when he says, \"I want it to be less than an hour\"?","qvi":"Người đàn ông ngụ ý gì khi nói \"Tôi muốn nó dài dưới một tiếng\"?","opts":["He is very busy.","He approves an itinerary.","A route has a lot of traffic.","Some revisions are needed."],"vi":["Anh ấy rất bận.","Anh ấy duyệt một lịch trình.","Một tuyến đường đông xe.","Cần chỉnh sửa một số chỗ."],"ans":"D","xp":"Câu hàm ý. Anh ấy vừa xem đề cương phim và nói \"I'm a bit concerned\" rồi muốn phim dưới một tiếng; người phụ nữ đáp sẽ \"take out some unnecessary scenes\" (cắt bớt cảnh) → ý anh ấy là cần sửa lại đề cương → (D)."},{"n":58,"q":"Why does the man need to contact a team?","qvi":"Tại sao người đàn ông cần liên hệ với một nhóm?","opts":["To explain a permit procedure","To confirm equipment availability","To introduce a colleague","To devise a safety plan"],"vi":["Để giải thích thủ tục xin giấy phép","Để xác nhận có sẵn thiết bị","Để giới thiệu một đồng nghiệp","Để lập kế hoạch an toàn"],"ans":"B","xp":"Người đàn ông: \"I need to follow up with our camera team to make sure they have all the equipment they need to begin filming.\" → liên hệ để chắc chắn đội có đủ thiết bị. Paraphrase: make sure they have all the equipment → confirm equipment availability."}],"a":"E24-T06-56-58.mp3"},{"ns":[59,61],"script":[["M","Kriti and Melissa, I reviewed the results of the soil tests yesterday, and most of the sports fields we manage have healthy soil. But unfortunately, the baseball field on Smith Drive has elevated levels of potassium.","Kriti và Melissa, hôm qua tôi đã xem kết quả kiểm tra đất, và hầu hết các sân thể thao chúng ta quản lý đều có đất tốt. Nhưng thật không may, sân bóng chày trên đường Smith có hàm lượng kali cao."],["W1","The grass on that field is so brown and weedy. Now we know why.","Cỏ trên sân đó rất úa và nhiều cỏ dại. Giờ thì chúng ta biết lý do rồi."],["W2","We'll need to order some special fertilizer to put on it. Do you think we need approval to do that?","Chúng ta sẽ cần đặt mua loại phân bón đặc biệt để bón cho sân. Anh có nghĩ chúng ta cần được duyệt mới làm được không?"],["M","Yes—since it's an unforeseen expense, it has to be approved by the acquisitions department. Melissa, do you have time to prepare a cost estimate?","Có — vì đây là khoản chi ngoài dự kiến nên phải được phòng thu mua phê duyệt. Melissa, chị có thời gian chuẩn bị bảng ước tính chi phí không?"],["W2","Sure. It won't take long. I'll send it by lunchtime, and I'll cc you both on the e-mail.","Được chứ. Sẽ không lâu đâu. Tôi sẽ gửi trước giờ trưa, và tôi sẽ cc cho cả hai người trong e-mail."]],"qs":[{"n":59,"q":"What did the man review yesterday?","qvi":"Hôm qua người đàn ông đã xem xét cái gì?","opts":["A budget","A weather report","Some test results","Some hiring plans"],"vi":["Ngân sách","Bản tin thời tiết","Một số kết quả kiểm tra","Một số kế hoạch tuyển dụng"],"ans":"C","xp":"Người đàn ông: \"I reviewed the results of the soil tests yesterday\" → anh ấy xem kết quả kiểm tra đất. Paraphrase: the results of the soil tests → Some test results."},{"n":60,"q":"What do the speakers hope to do?","qvi":"Những người nói hy vọng làm được điều gì?","opts":["Improve the condition of a sports field","Expand the city's athletic programs","Plan a fund-raising event","Acquire more public land"],"vi":["Cải thiện tình trạng của một sân thể thao","Mở rộng các chương trình thể thao của thành phố","Lên kế hoạch cho một sự kiện gây quỹ","Mua thêm đất công"],"ans":"A","xp":"Sân bóng chày trên đường Smith có \"elevated levels of potassium\", cỏ úa; người phụ nữ nói: \"We'll need to order some special fertilizer to put on it.\" → họ muốn cải thiện tình trạng sân thể thao đó → (A)."},{"n":61,"q":"What will Melissa send by e-mail?","qvi":"Melissa sẽ gửi gì qua e-mail?","opts":["A summary of work tasks","A letter of appreciation","A news article","A cost estimate"],"vi":["Bản tóm tắt công việc","Thư cảm ơn","Một bài báo","Bảng ước tính chi phí"],"ans":"D","xp":"Người đàn ông hỏi: \"Melissa, do you have time to prepare a cost estimate?\"; Melissa đáp: \"Sure... I'll send it by lunchtime, and I'll cc you both on the e-mail.\" → cô ấy sẽ gửi bảng ước tính chi phí."}],"a":"E24-T06-59-61.mp3"},{"ns":[62,64],"script":[["W","Rodrigo, you wanted to talk to me about the schedule for the bowling leagues at our alley?","Rodrigo, anh muốn nói chuyện với tôi về lịch thi đấu của các giải bowling ở sân của chúng ta phải không?"],["M","Yes. As you know, many of the members in the adult league have young children who participate in the junior league. And they explained to me that it would be really convenient if we moved the junior league to the same night that the adult league plays. That way they could all come together on the same night.","Vâng. Như chị biết đấy, nhiều thành viên ở giải người lớn có con nhỏ tham gia giải thiếu niên. Họ giải thích với tôi rằng sẽ rất tiện nếu chúng ta chuyển giải thiếu niên sang cùng tối mà giải người lớn thi đấu. Như vậy cả nhà có thể đến cùng nhau trong một tối."],["W","That's a great idea. We have a few available bowling lanes on that day that the junior league can use. I'll e-mail the parents of the junior bowlers and let them know the day will change starting next month.","Ý hay đấy. Hôm đó chúng ta còn vài đường bowling trống mà giải thiếu niên có thể dùng. Tôi sẽ gửi e-mail cho phụ huynh của các vận động viên nhí để báo rằng ngày thi đấu sẽ thay đổi bắt đầu từ tháng sau."]],"qs":[{"n":62,"q":"Where do the speakers work?","qvi":"Những người nói làm việc ở đâu?","opts":["At a bowling alley","At a swimming pool","At an ice-skating rink","At a baseball field"],"vi":["Ở sân chơi bowling","Ở hồ bơi","Ở sân trượt băng","Ở sân bóng chày"],"ans":"A","xp":"Người phụ nữ: \"the schedule for the bowling leagues at our alley\" (sân bowling của chúng ta) → họ làm ở sân bowling."},{"n":63,"q":"Look at the graphic. On which day will the Junior League meet starting next month?","qvi":"Hãy nhìn vào bảng. Bắt đầu từ tháng sau, giải Thiếu niên (Junior League) sẽ thi đấu vào ngày nào?","opts":["Monday","Tuesday","Wednesday","Thursday"],"vi":["Thứ Hai","Thứ Ba","Thứ Tư","Thứ Năm"],"ans":"D","xp":"Người đàn ông đề nghị: \"if we moved the junior league to the same night that the adult league plays\"; người phụ nữ đồng ý. Theo bảng, Adult League chơi vào Thursday → từ tháng sau Junior League sẽ chơi vào thứ Năm. (A) Monday là lịch cũ."},{"n":64,"q":"What does the woman say she will do?","qvi":"Người phụ nữ nói cô ấy sẽ làm gì?","opts":["Hang a poster","Send an e-mail","Deliver a package","Process a payment"],"vi":["Treo áp phích","Gửi e-mail","Giao một gói hàng","Xử lý một khoản thanh toán"],"ans":"B","xp":"Người phụ nữ: \"I'll e-mail the parents of the junior bowlers and let them know the day will change\" → cô ấy sẽ gửi e-mail → (B)."}],"a":"E24-T06-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Hi. Where can I find a schedule of library events?","Chào chị. Tôi có thể xem lịch các sự kiện của thư viện ở đâu?"],["W","Oh, I've got it right here. We usually have events almost every day, but we're closed this Friday. The library is being used for the district elections.","À, tôi có ngay đây. Chúng tôi thường có sự kiện gần như mỗi ngày, nhưng thứ Sáu này thư viện đóng cửa. Thư viện sẽ được dùng cho cuộc bầu cử của quận."],["M","I see. Are there any movies showing?","Tôi hiểu rồi. Có chiếu phim nào không?"],["W","Yes, there's one on Thursday evening.","Có, có một phim vào tối thứ Năm."],["M","Oh, too bad. I'm away for a client meeting on Thursday.","Ôi, tiếc quá. Thứ Năm tôi đi vắng để gặp khách hàng."],["W","Well, if you like Sumit Mehta's books, you might be interested in his book signing.","Vậy nếu anh thích sách của Sumit Mehta, có lẽ anh sẽ quan tâm đến buổi ký tặng sách của ông ấy."],["M","I do like his novels! Thanks, I'll come back for that.","Tôi rất thích tiểu thuyết của ông ấy! Cảm ơn chị, tôi sẽ quay lại dự buổi đó."]],"qs":[{"n":65,"q":"According to the woman, why will the library be closed on Friday?","qvi":"Theo người phụ nữ, tại sao thư viện sẽ đóng cửa vào thứ Sáu?","opts":["An election will be held there.","Some renovations will take place.","Bad weather is expected.","A national holiday will be observed."],"vi":["Một cuộc bầu cử sẽ được tổ chức ở đó.","Sẽ có việc cải tạo.","Dự báo thời tiết xấu.","Sẽ có một ngày lễ quốc gia."],"ans":"A","xp":"Người phụ nữ: \"we're closed this Friday. The library is being used for the district elections.\" → thư viện được dùng làm nơi bầu cử. Paraphrase: being used for the district elections → An election will be held there."},{"n":66,"q":"What schedule conflict does the man mention?","qvi":"Người đàn ông nhắc đến việc trùng lịch nào?","opts":["He has a family obligation.","His car will be at a mechanic's shop.","He will be attending a performance.","He has a business meeting."],"vi":["Anh ấy có việc gia đình.","Xe của anh ấy sẽ ở tiệm sửa xe.","Anh ấy sẽ đi xem một buổi biểu diễn.","Anh ấy có một cuộc họp công việc."],"ans":"D","xp":"Phim chiếu tối thứ Năm, nhưng người đàn ông nói: \"I'm away for a client meeting on Thursday.\" → trùng với cuộc họp với khách hàng. Paraphrase: a client meeting → a business meeting."},{"n":67,"q":"Look at the graphic. When will the man most likely attend a library event?","qvi":"Hãy nhìn vào bảng. Người đàn ông nhiều khả năng sẽ tham dự sự kiện của thư viện vào khi nào?","opts":["On Monday","On Tuesday","On Wednesday","On Thursday"],"vi":["Vào thứ Hai","Vào thứ Ba","Vào thứ Tư","Vào thứ Năm"],"ans":"C","xp":"Người phụ nữ gợi ý buổi ký tặng sách của Sumit Mehta; người đàn ông: \"Thanks, I'll come back for that.\" Theo bảng, \"Book Signing: Sumit Mehta\" diễn ra vào Wednesday (6 P.M.) → thứ Tư. (D) sai vì thứ Năm anh ấy bận gặp khách hàng."}],"a":"E24-T06-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["W","Good news, Tariq. We'll have enough money to make those repairs to the bridge over the fish pond that you mentioned. We've been awarded a grant to make some repairs to the park grounds.","Tin vui đây, Tariq. Chúng ta sẽ có đủ tiền để sửa cây cầu bắc qua ao cá mà anh đã nhắc đến. Chúng ta vừa được nhận một khoản tài trợ để sửa chữa khuôn viên công viên."],["M","That's great! That bridge needs a new coat of paint to protect it from the elements. I think I sent you a list of paint colors when I first talked to you about the project.","Tuyệt quá! Cây cầu đó cần sơn một lớp mới để bảo vệ nó khỏi mưa gió. Tôi nghĩ tôi đã gửi chị danh sách màu sơn khi lần đầu nói với chị về dự án này."],["W","You did. Because it's such an iconic symbol of the park, and it's in so many photographs, we want it to be as close to the original color as when it was first built, even though that's the most expensive option on the list.","Anh có gửi. Vì cây cầu là biểu tượng của công viên và xuất hiện trong rất nhiều bức ảnh, chúng ta muốn nó giống màu gốc nhất có thể như lúc mới xây, dù đó là lựa chọn đắt nhất trong danh sách."]],"qs":[{"n":68,"q":"What is the conversation about?","qvi":"Cuộc hội thoại nói về điều gì?","opts":["Extending a fence","Building a storage shed","Repairing a bridge","Updating an entrance area"],"vi":["Nối dài hàng rào","Xây nhà kho","Sửa một cây cầu","Nâng cấp khu vực lối vào"],"ans":"C","xp":"Người phụ nữ: \"We'll have enough money to make those repairs to the bridge over the fish pond\"; người đàn ông tiếp: \"That bridge needs a new coat of paint...\" → chủ đề là sửa cây cầu → (C)."},{"n":69,"q":"According to the woman, how is a project being funded?","qvi":"Theo người phụ nữ, dự án được cấp vốn bằng cách nào?","opts":["With donations from visitors","With money from a grant","With revenue from ticket sales","With proceeds from a charity auction"],"vi":["Bằng tiền quyên góp của du khách","Bằng tiền từ một khoản tài trợ","Bằng doanh thu bán vé","Bằng tiền thu được từ buổi đấu giá từ thiện"],"ans":"B","xp":"Người phụ nữ: \"We've been awarded a grant to make some repairs to the park grounds.\" → tiền đến từ khoản tài trợ (grant) → (B)."},{"n":70,"q":"Look at the graphic. Which color does the woman select?","qvi":"Hãy nhìn vào bảng. Người phụ nữ chọn màu nào?","opts":["Garden Green","Misty Blue","Sunrise Peach","Antique White"],"vi":["Garden Green (xanh lá vườn)","Misty Blue (xanh sương mù)","Sunrise Peach (hồng đào bình minh)","Antique White (trắng cổ điển)"],"ans":"B","xp":"Người phụ nữ muốn màu gốc \"even though that's the most expensive option on the list\" (dù đó là lựa chọn đắt nhất). Theo bảng, màu đắt nhất là Misty Blue ($27) → (B)."}],"a":"E24-T06-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Hi, everyone—big news. Our clinic is getting a check-in kiosk. What this means is that patients will be able to check themselves in to their medical appointments by clicking through some buttons in the kiosk. You will no longer have to do it for them. I know all of you have been very busy answering phones, scheduling appointments, and checking patients in, so hopefully, this helps to make your work easier. We'll have a very short training session next Tuesday on how the check-in kiosk works.","Chào mọi người — có tin lớn đây. Phòng khám của chúng ta sắp có một ki-ốt làm thủ tục tự động. Điều này có nghĩa là bệnh nhân sẽ có thể tự làm thủ tục cho cuộc hẹn khám bệnh bằng cách bấm vài nút trên ki-ốt. Các bạn sẽ không phải làm việc đó giúp họ nữa. Tôi biết mọi người đều rất bận rộn trả lời điện thoại, xếp lịch hẹn và làm thủ tục cho bệnh nhân, nên hy vọng điều này sẽ giúp công việc của các bạn nhẹ nhàng hơn. Thứ Ba tới chúng ta sẽ có một buổi đào tạo rất ngắn về cách hoạt động của ki-ốt làm thủ tục."]],"qs":[{"n":71,"q":"Where does the talk most likely take place?","qvi":"Bài nói nhiều khả năng diễn ra ở đâu?","opts":["At a medical clinic","At an airport","At a fitness center","At a bank"],"vi":["Ở phòng khám","Ở sân bay","Ở trung tâm thể hình","Ở ngân hàng"],"ans":"A","xp":"Người nói: \"Our clinic is getting a check-in kiosk\" và nhắc đến \"patients... medical appointments\" → nơi diễn ra là phòng khám. Paraphrase: clinic → medical clinic."},{"n":72,"q":"What is mainly being discussed?","qvi":"Nội dung chính đang được thảo luận là gì?","opts":["A hiring decision","A marketing campaign","A customer satisfaction survey","An electronic check-in system"],"vi":["Một quyết định tuyển dụng","Một chiến dịch tiếp thị","Một cuộc khảo sát mức độ hài lòng của khách hàng","Một hệ thống làm thủ tục điện tử"],"ans":"D","xp":"Người nói: \"Our clinic is getting a check-in kiosk. What this means is that patients will be able to check themselves in... by clicking through some buttons in the kiosk.\" → chủ đề là hệ thống làm thủ tục điện tử. Paraphrase: check-in kiosk → electronic check-in system."},{"n":73,"q":"What will happen next Tuesday?","qvi":"Điều gì sẽ diễn ra vào thứ Ba tới?","opts":["A new security system will be installed.","A branch location will open.","A training session will take place.","A product will be delivered."],"vi":["Một hệ thống an ninh mới sẽ được lắp đặt.","Một chi nhánh sẽ khai trương.","Một buổi đào tạo sẽ diễn ra.","Một sản phẩm sẽ được giao."],"ans":"C","xp":"Cuối bài: \"We'll have a very short training session next Tuesday on how the check-in kiosk works.\" → thứ Ba tới có buổi đào tạo → (C)."}],"a":"E24-T06-71-73.mp3"},{"ns":[74,76],"script":[["","Welcome to a new episode of Tomorrow's Technology. Today we'll be talking about drones. If you're planning to buy your first drone, here are a few things you need to know. To begin with, if you want to use the device for commercial purposes, such as photography or videography, then you'll need to apply for a license. I'll share some resources at the end of this podcast to guide your application process.","Chào mừng các bạn đến với tập mới của chương trình Tomorrow's Technology (Công nghệ Ngày mai). Hôm nay chúng ta sẽ nói về máy bay không người lái (drone). Nếu bạn đang định mua chiếc drone đầu tiên, đây là vài điều bạn cần biết. Trước hết, nếu bạn muốn dùng thiết bị này cho mục đích thương mại, như chụp ảnh hoặc quay phim, thì bạn sẽ cần xin giấy phép. Tôi sẽ chia sẻ một số tài liệu ở cuối podcast này để hướng dẫn bạn quy trình nộp đơn."]],"qs":[{"n":74,"q":"Who is the podcast intended for?","qvi":"Podcast này dành cho ai?","opts":["Party organizers","Travel agents","Technology enthusiasts","Carpenters"],"vi":["Người tổ chức tiệc","Nhân viên đại lý du lịch","Người đam mê công nghệ","Thợ mộc"],"ans":"C","xp":"Người nói: \"Welcome to a new episode of Tomorrow's Technology. Today we'll be talking about drones.\" → chương trình về công nghệ, nói về drone → dành cho người yêu thích công nghệ."},{"n":75,"q":"According to the speaker, what will some listeners need?","qvi":"Theo người nói, một số thính giả sẽ cần gì?","opts":["An insurance policy","A letter of recommendation","An event venue","A license"],"vi":["Một hợp đồng bảo hiểm","Một thư giới thiệu","Một địa điểm tổ chức sự kiện","Một giấy phép"],"ans":"D","xp":"Người nói: \"if you want to use the device for commercial purposes... then you'll need to apply for a license.\" → những ai dùng drone cho mục đích thương mại sẽ cần giấy phép → (D)."},{"n":76,"q":"What information will the speaker share?","qvi":"Người nói sẽ chia sẻ thông tin gì?","opts":["Application instructions","Retail locations","Names of instructors","User reviews"],"vi":["Hướng dẫn nộp đơn","Địa điểm cửa hàng bán lẻ","Tên của các giảng viên","Đánh giá của người dùng"],"ans":"A","xp":"Người nói: \"I'll share some resources at the end of this podcast to guide your application process.\" → tài liệu hướng dẫn quy trình nộp đơn → (A) Application instructions."}],"a":"E24-T06-74-76.mp3"},{"ns":[77,79],"script":[["","Attention, exhibitors. Welcome to the Digital Signage Expo, where representatives selling digital billboards and video displays can interact directly with buyers. The exhibit hall will open in fifteen minutes. To ensure everyone's safety, we request that you clear your exhibit area of boxes and debris and be sure cables and electrical cords are securely taped to the floor. And remember, the exhibit hall will close at five P.M. today so that exhibitors can attend this evening's reception. That will be held in the building's main lobby.","Xin các đơn vị trưng bày chú ý. Chào mừng đến với Triển lãm Biển hiệu Kỹ thuật số, nơi các đại diện bán biển quảng cáo kỹ thuật số và màn hình video có thể gặp gỡ trực tiếp người mua. Sảnh triển lãm sẽ mở cửa sau mười lăm phút nữa. Để đảm bảo an toàn cho mọi người, chúng tôi yêu cầu quý vị dọn sạch thùng hộp và rác khỏi khu trưng bày của mình, đồng thời đảm bảo cáp và dây điện được dán chắc xuống sàn. Và xin nhớ, hôm nay sảnh triển lãm sẽ đóng cửa lúc 5 giờ chiều để các đơn vị trưng bày có thể dự tiệc chiêu đãi tối nay. Tiệc sẽ được tổ chức tại sảnh chính của tòa nhà."]],"qs":[{"n":77,"q":"Who are the listeners?","qvi":"Người nghe là ai?","opts":["Mechanical engineers","Trade show participants","Government officials","Laboratory assistants"],"vi":["Kỹ sư cơ khí","Người tham gia hội chợ thương mại","Quan chức chính phủ","Trợ lý phòng thí nghiệm"],"ans":"B","xp":"Người nói: \"Attention, exhibitors. Welcome to the Digital Signage Expo...\" → người nghe là các đơn vị trưng bày tại triển lãm → người tham gia hội chợ thương mại (trade show participants)."},{"n":78,"q":"What does the speaker request that the listeners do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Take safety precautions","Sign a registration sheet","Wear name tags","Move their vehicles"],"vi":["Thực hiện các biện pháp an toàn","Ký vào phiếu đăng ký","Đeo thẻ tên","Di chuyển xe của họ"],"ans":"A","xp":"Người nói: \"To ensure everyone's safety, we request that you clear your exhibit area of boxes and debris and be sure cables and electrical cords are securely taped to the floor.\" → yêu cầu thực hiện các biện pháp đảm bảo an toàn → (A)."},{"n":79,"q":"What will take place in the evening?","qvi":"Điều gì sẽ diễn ra vào buổi tối?","opts":["A debate","An award ceremony","A film screening","A reception"],"vi":["Một cuộc tranh luận","Một lễ trao giải","Một buổi chiếu phim","Một buổi tiệc chiêu đãi"],"ans":"D","xp":"Người nói: \"the exhibit hall will close at five P.M. today so that exhibitors can attend this evening's reception.\" → tối nay có tiệc chiêu đãi (reception) → (D)."}],"a":"E24-T06-77-79.mp3"},{"ns":[80,82],"script":[["","Welcome to Money Reveals, the podcast for smart investors. This week, I'll be discussing the best tips for amateur investors, if you're just getting started. But first, this episode is brought to you by CodeWord. Don't search online for discount coupons any longer! CodeWord is a software application that scans the Internet for promotional codes and applies them to your online shopping cart. If CodeWord finds any discounts, an Apply Coupon button will automatically appear at checkout. What's more, the first 100 listeners to use the download link on my Web site will receive free music festival tickets.","Chào mừng đến với Money Reveals, podcast dành cho các nhà đầu tư thông thái. Tuần này, tôi sẽ bàn về những mẹo hay nhất cho nhà đầu tư nghiệp dư, nếu bạn mới bắt đầu. Nhưng trước tiên, tập này được tài trợ bởi CodeWord. Đừng mất công tìm phiếu giảm giá trên mạng nữa! CodeWord là một ứng dụng phần mềm quét Internet để tìm mã khuyến mãi và áp dụng chúng vào giỏ hàng trực tuyến của bạn. Nếu CodeWord tìm thấy ưu đãi nào, nút Áp dụng phiếu giảm giá sẽ tự động hiện ra khi thanh toán. Hơn nữa, 100 thính giả đầu tiên dùng đường link tải về trên trang web của tôi sẽ nhận được vé miễn phí tham dự lễ hội âm nhạc."]],"qs":[{"n":80,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A customer service representative","A software developer","A podcast host","An event coordinator"],"vi":["Nhân viên chăm sóc khách hàng","Nhà phát triển phần mềm","Người dẫn chương trình podcast","Điều phối viên sự kiện"],"ans":"C","xp":"Người nói mở đầu: \"Welcome to Money Reveals, the podcast for smart investors. This week, I'll be discussing...\" → người dẫn chương trình podcast → (C)."},{"n":81,"q":"According to the speaker, what can a software application be used for?","qvi":"Theo người nói, ứng dụng phần mềm có thể được dùng để làm gì?","opts":["Making travel reservations","Uploading documents","Managing subscriptions","Searching for discounts"],"vi":["Đặt chỗ du lịch","Tải tài liệu lên","Quản lý các gói đăng ký","Tìm kiếm ưu đãi giảm giá"],"ans":"D","xp":"\"Don't search online for discount coupons any longer! CodeWord is a software application that scans the Internet for promotional codes...\" → ứng dụng dùng để tìm mã giảm giá. Paraphrase: scans the Internet for promotional codes → Searching for discounts."},{"n":82,"q":"How can the listeners receive some free tickets?","qvi":"Người nghe có thể nhận vé miễn phí bằng cách nào?","opts":["By clicking on a link","By signing up for a newsletter","By buying a product in-store","By writing a review"],"vi":["Bằng cách bấm vào một đường link","Bằng cách đăng ký nhận bản tin","Bằng cách mua sản phẩm tại cửa hàng","Bằng cách viết đánh giá"],"ans":"A","xp":"\"the first 100 listeners to use the download link on my Web site will receive free music festival tickets\" → dùng đường link tải về trên web để nhận vé. Paraphrase: use the download link → clicking on a link."}],"a":"E24-T06-80-82.mp3"},{"ns":[83,85],"script":[["","Hi. This is So-Jin—in Apartment 2A. I just moved into the complex last month. I'm calling about a problem with my kitchen sink. The drain is completely clogged, so the water won't go down. I've tried a few different drain cleaning products, but they didn't help. I think I've done all I can do. I'm at work now, but I'll be home this afternoon. Could you call me back, so we can arrange a time to meet there? Thanks.","Xin chào. Tôi là So-Jin ở căn hộ 2A. Tôi vừa chuyển đến khu chung cư này tháng trước. Tôi gọi về vấn đề với bồn rửa trong bếp. Ống thoát nước bị tắc hoàn toàn nên nước không chảy xuống được. Tôi đã thử vài loại sản phẩm thông ống khác nhau nhưng không ăn thua. Tôi nghĩ mình đã làm hết những gì có thể rồi. Bây giờ tôi đang đi làm, nhưng chiều nay tôi sẽ ở nhà. Anh/chị có thể gọi lại cho tôi để chúng ta hẹn giờ gặp ở đó được không? Cảm ơn."]],"qs":[{"n":83,"q":"Who is the speaker most likely calling?","qvi":"Người nói nhiều khả năng đang gọi cho ai?","opts":["A store owner","A property manager","A delivery driver","A restaurant supplier"],"vi":["Chủ cửa hàng","Người quản lý tòa nhà","Tài xế giao hàng","Nhà cung cấp cho nhà hàng"],"ans":"B","xp":"Người nói: \"This is So-Jin—in Apartment 2A. I just moved into the complex last month. I'm calling about a problem with my kitchen sink.\" → cư dân căn hộ gọi báo hỏng hóc → người nghe là quản lý tòa nhà. Paraphrase: Apartment/complex → property."},{"n":84,"q":"What problem does the speaker have?","qvi":"Người nói gặp vấn đề gì?","opts":["Some appliances have not arrived.","Some boxes have been damaged.","A water cooler is not working.","A sink is not draining."],"vi":["Một số thiết bị gia dụng chưa được giao đến.","Một số thùng hàng bị hư hỏng.","Máy làm mát nước không hoạt động.","Bồn rửa không thoát nước."],"ans":"D","xp":"\"I'm calling about a problem with my kitchen sink. The drain is completely clogged, so the water won't go down.\" → bồn rửa bị tắc, không thoát nước → (D)."},{"n":85,"q":"Why does the speaker say, \"I think I've done all I can do\"?","qvi":"Tại sao người nói nói \"Tôi nghĩ mình đã làm hết những gì có thể rồi\"?","opts":["To request that the listener give her a refund","To indicate that she needs the listener's assistance","To explain why she enrolled in a training course","To confirm that a task has been completed"],"vi":["Để yêu cầu người nghe hoàn tiền cho cô ấy","Để cho biết cô ấy cần người nghe giúp đỡ","Để giải thích lý do cô ấy đăng ký một khóa đào tạo","Để xác nhận một công việc đã hoàn thành"],"ans":"B","xp":"Câu hàm ý. Trước đó cô ấy nói: \"I've tried a few different drain cleaning products, but they didn't help.\" và sau đó: \"Could you call me back, so we can arrange a time to meet there?\" → ý là tự mình không sửa được nữa, cần người nghe giúp → (B)."}],"a":"E24-T06-83-85.mp3"},{"ns":[86,88],"script":[["","Next Tuesday the eleventh is our office cleanup. We'll have bins stationed all around the office for you to put garbage and recycling in. Be sure to shred any documents that have private client information on them. Our office manager Rajeev has rented some extra document shredders for us to use. Thanks for taking care of that, Rajeev. Now, we've hired two new accountants who are supposed to start in a month, and we need to make space for their desks. Now that our work is mostly paperless, the south corner of the office has a lot of empty file cabinets.","Thứ Ba tới, ngày 11, là ngày dọn dẹp văn phòng của chúng ta. Chúng tôi sẽ đặt thùng khắp văn phòng để các bạn bỏ rác và đồ tái chế vào. Nhớ hủy (cắt vụn) mọi tài liệu có thông tin cá nhân của khách hàng. Quản lý văn phòng Rajeev đã thuê thêm vài máy hủy tài liệu cho chúng ta dùng. Cảm ơn anh đã lo việc đó, Rajeev. Còn nữa, chúng ta đã tuyển hai kế toán mới, dự kiến sẽ bắt đầu làm việc trong một tháng nữa, và chúng ta cần chỗ để đặt bàn cho họ. Giờ đây công việc của chúng ta hầu như không dùng giấy nữa, nên góc phía nam văn phòng có rất nhiều tủ hồ sơ trống."]],"qs":[{"n":86,"q":"What will the listeners do next Tuesday?","qvi":"Người nghe sẽ làm gì vào thứ Ba tới?","opts":["Renew their contracts","Clean their offices","Visit a recycling center","Greet new clients"],"vi":["Gia hạn hợp đồng","Dọn dẹp văn phòng","Đến thăm trung tâm tái chế","Chào đón khách hàng mới"],"ans":"B","xp":"Câu mở đầu: \"Next Tuesday the eleventh is our office cleanup.\" → thứ Ba tới là ngày dọn dẹp văn phòng. Paraphrase: office cleanup → Clean their offices."},{"n":87,"q":"What does the speaker thank Rajeev for doing?","qvi":"Người nói cảm ơn Rajeev vì đã làm gì?","opts":["Paying for refreshments","Reserving a meeting room","Arranging transportation","Renting some equipment"],"vi":["Trả tiền đồ ăn nhẹ","Đặt phòng họp","Sắp xếp phương tiện đi lại","Thuê một số thiết bị"],"ans":"D","xp":"\"Our office manager Rajeev has rented some extra document shredders for us to use. Thanks for taking care of that, Rajeev.\" → cảm ơn vì đã thuê máy hủy tài liệu. Paraphrase: document shredders → equipment."},{"n":88,"q":"Why does the speaker say, \"the south corner of the office has a lot of empty file cabinets\"?","qvi":"Tại sao người nói nói \"góc phía nam văn phòng có rất nhiều tủ hồ sơ trống\"?","opts":["To suggest a location for some desks","To indicate where some files should be stored","To explain that a task has already been completed","To ask for more office supplies to be ordered"],"vi":["Để gợi ý một vị trí đặt bàn làm việc","Để chỉ ra nơi nên cất hồ sơ","Để giải thích rằng một việc đã được hoàn thành","Để yêu cầu đặt thêm văn phòng phẩm"],"ans":"A","xp":"Câu hàm ý. Ngay trước đó: \"we've hired two new accountants... and we need to make space for their desks.\" Rồi người nói nhắc góc phía nam có nhiều tủ hồ sơ trống (không còn dùng vì làm việc không giấy) → ngụ ý dọn chỗ đó để đặt bàn cho nhân viên mới → (A)."}],"a":"E24-T06-86-88.mp3"},{"ns":[89,91],"script":[["","Hello, and thank you for calling Ziegler Incorporated, the area's top supplier of office paper. Due to bad weather conditions last week, roads around our warehouse were closed. As a result, customers may be experiencing delays in receiving their recent orders. Now that the roads are clear, we've resumed deliveries. However, we'll need a few days to catch up. To make up for this inconvenience, we're offering customers a twenty percent discount on their next purchase. To claim the discount, enter your invoice number on our Web site. Once you do, your discount code will arrive in an e-mail.","Xin chào, cảm ơn quý khách đã gọi đến Ziegler Incorporated, nhà cung cấp giấy văn phòng hàng đầu khu vực. Do thời tiết xấu tuần trước, các con đường quanh kho hàng của chúng tôi đã bị đóng. Vì vậy, quý khách có thể nhận các đơn hàng gần đây bị chậm. Giờ đường đã thông, chúng tôi đã giao hàng trở lại. Tuy nhiên, chúng tôi sẽ cần vài ngày để xử lý kịp. Để bù đắp cho sự bất tiện này, chúng tôi giảm giá 20% cho lần mua tiếp theo của quý khách. Để nhận ưu đãi, hãy nhập số hóa đơn của quý khách trên trang web của chúng tôi. Sau khi nhập, mã giảm giá sẽ được gửi đến quý khách qua e-mail."]],"qs":[{"n":89,"q":"What does Ziegler Incorporated sell?","qvi":"Ziegler Incorporated bán gì?","opts":["Office paper","Gardening tools","Computers","Car parts"],"vi":["Giấy văn phòng","Dụng cụ làm vườn","Máy tính","Phụ tùng ô tô"],"ans":"A","xp":"Câu mở đầu: \"thank you for calling Ziegler Incorporated, the area's top supplier of office paper\" → công ty bán giấy văn phòng → (A)."},{"n":90,"q":"According to the speaker, what problem is the company experiencing?","qvi":"Theo người nói, công ty đang gặp vấn đề gì?","opts":["Staffing shortages","Shipping delays","Limited warehouse space","Insufficient inventory"],"vi":["Thiếu nhân viên","Giao hàng chậm trễ","Kho hàng chật hẹp","Hàng tồn kho không đủ"],"ans":"B","xp":"\"customers may be experiencing delays in receiving their recent orders\" (khách nhận hàng bị chậm) → vấn đề là giao hàng chậm. Paraphrase: delays in receiving their recent orders → Shipping delays."},{"n":91,"q":"What will arrive in an e-mail?","qvi":"Cái gì sẽ được gửi đến qua e-mail?","opts":["Some contact information","An order form","A discount code","A price list"],"vi":["Thông tin liên lạc","Mẫu đơn đặt hàng","Mã giảm giá","Bảng giá"],"ans":"C","xp":"Câu cuối: \"Once you do, your discount code will arrive in an e-mail.\" → mã giảm giá được gửi qua e-mail → (C)."}],"a":"E24-T06-89-91.mp3"},{"ns":[92,94],"script":[["","As members of the city's Arts Commission, it's our responsibility to manage arts programs and initiatives. The mayor's decision to redevelop the Hoverton District is welcome news across the community. And for our commission, it's an opportunity to integrate sculptures into public spaces there. We'll need to determine what overall community themes should be addressed and prioritized. So I think it's important that we conduct a survey regarding the residents' preferences. It's a diverse community with a range of perspectives to consider. And, of course, in order for the artwork to be built, we'll need to hire a skilled artist for the task. I think Alvaro Gomez has won several awards.","Là thành viên của Ủy ban Nghệ thuật thành phố, chúng ta có trách nhiệm quản lý các chương trình và sáng kiến nghệ thuật. Quyết định tái phát triển quận Hoverton của thị trưởng là tin vui với toàn cộng đồng. Và với ủy ban chúng ta, đây là cơ hội để đưa các tác phẩm điêu khắc vào những không gian công cộng ở đó. Chúng ta sẽ cần xác định những chủ đề chung nào của cộng đồng nên được đề cập và ưu tiên. Vì vậy tôi nghĩ việc tiến hành khảo sát về sở thích của cư dân là rất quan trọng. Đây là một cộng đồng đa dạng với nhiều quan điểm cần cân nhắc. Và dĩ nhiên, để tác phẩm nghệ thuật được thực hiện, chúng ta sẽ cần thuê một nghệ sĩ có tay nghề. Tôi nghĩ Alvaro Gomez đã giành được nhiều giải thưởng đấy."]],"qs":[{"n":92,"q":"What has the mayor decided to do?","qvi":"Thị trưởng đã quyết định làm gì?","opts":["Run for election again","Redevelop an area of the city","Host an art festival","Provide public art classes"],"vi":["Ra tranh cử lần nữa","Tái phát triển một khu vực của thành phố","Tổ chức lễ hội nghệ thuật","Mở các lớp học nghệ thuật cho công chúng"],"ans":"B","xp":"\"The mayor's decision to redevelop the Hoverton District is welcome news across the community.\" → thị trưởng quyết định tái phát triển quận Hoverton. Paraphrase: the Hoverton District → an area of the city."},{"n":93,"q":"What is the goal of a survey?","qvi":"Mục tiêu của cuộc khảo sát là gì?","opts":["To decide on a theme","To raise money for a project","To educate the public about a problem","To recruit some volunteers"],"vi":["Để quyết định chủ đề","Để gây quỹ cho một dự án","Để giáo dục công chúng về một vấn đề","Để tuyển tình nguyện viên"],"ans":"A","xp":"\"We'll need to determine what overall community themes should be addressed and prioritized. So I think it's important that we conduct a survey regarding the residents' preferences.\" → khảo sát để xác định chủ đề. Paraphrase: determine what... themes → decide on a theme."},{"n":94,"q":"Why does the speaker say, \"I think Alvaro Gomez has won several awards\"?","qvi":"Tại sao người nói nói \"Tôi nghĩ Alvaro Gomez đã giành được nhiều giải thưởng đấy\"?","opts":["To correct some information","To praise a museum exhibit","To recommend a suitable candidate","To congratulate a colleague"],"vi":["Để đính chính một thông tin","Để khen ngợi một cuộc triển lãm ở bảo tàng","Để đề xuất một ứng viên phù hợp","Để chúc mừng một đồng nghiệp"],"ans":"C","xp":"Câu hàm ý. Ngay trước đó: \"we'll need to hire a skilled artist for the task.\" Sau đó nhắc Alvaro Gomez từng đoạt nhiều giải → ngụ ý đề cử người này là nghệ sĩ phù hợp → (C)."}],"a":"E24-T06-92-94.mp3"},{"ns":[95,97],"script":[["","Good afternoon, Mr. Kwon, this is Olga Popova from the Smith Theater. You're next on the wait list for theater tickets. On your preference form, you requested four tickets together in either the orchestra or the mid-balcony. Unfortunately, those sections are completely sold out on the date you requested. But I do have four tickets together in the lower balcony for that date. I'll be happy to set aside those tickets if you'd like. I can hold this request for 24 hours. Please call our box office as soon as possible to let me know if you're still interested.","Chào buổi chiều anh Kwon, tôi là Olga Popova từ Nhà hát Smith. Anh là người tiếp theo trong danh sách chờ mua vé. Trong phiếu nguyện vọng, anh yêu cầu bốn vé ngồi cạnh nhau ở khu orchestra (khu sát sân khấu) hoặc khu ban công giữa. Rất tiếc, các khu đó đã bán hết vé vào ngày anh yêu cầu. Nhưng tôi có bốn vé ngồi cạnh nhau ở khu ban công dưới vào ngày đó. Tôi rất sẵn lòng giữ những vé này cho anh nếu anh muốn. Tôi có thể giữ yêu cầu này trong 24 giờ. Vui lòng gọi cho phòng bán vé của chúng tôi càng sớm càng tốt để cho tôi biết anh còn quan tâm không."]],"qs":[{"n":95,"q":"Who most likely is the speaker?","qvi":"Người nói nhiều khả năng là ai?","opts":["A seating usher","A band director","A stage actor","A sales agent"],"vi":["Nhân viên dẫn chỗ ngồi","Chỉ huy ban nhạc","Diễn viên sân khấu","Nhân viên bán vé"],"ans":"D","xp":"\"this is Olga Popova from the Smith Theater. You're next on the wait list for theater tickets.\" và cô ấy đề nghị giữ vé cho khách → cô ấy là nhân viên bán vé (sales agent)."},{"n":96,"q":"Look at the graphic. How much do tickets in the available section cost?","qvi":"Hãy nhìn vào sơ đồ. Vé ở khu còn chỗ có giá bao nhiêu?","opts":["$75","$100","$125","$150"],"vi":["75 đô la","100 đô la","125 đô la","150 đô la"],"ans":"C","xp":"Khu Orchestra và Mid-balcony đã hết vé; người nói: \"But I do have four tickets together in the lower balcony for that date.\" Theo sơ đồ, Lower balcony có giá $125 → (C)."},{"n":97,"q":"What does the listener need to do within 24 hours?","qvi":"Người nghe cần làm gì trong vòng 24 giờ?","opts":["Make a phone call","Send in a payment","Pick up an item","Fill out a form"],"vi":["Gọi điện thoại","Gửi tiền thanh toán","Đến lấy một món đồ","Điền vào một mẫu đơn"],"ans":"A","xp":"\"I can hold this request for 24 hours. Please call our box office as soon as possible to let me know if you're still interested.\" → anh ấy cần gọi điện cho phòng bán vé. Paraphrase: call → Make a phone call."}],"a":"E24-T06-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Welcome to this bus tour of the Kensey Harbor. Unfortunately, one of the stops on our itinerary, the museum, is closed, and we won't be able to visit it. The museum had a water pipe burst overnight. It looks like repair and cleanup work will last this whole week. I apologize, since I know many of you were looking forward to seeing the museum's exhibit on local fish. To make up for this, we're providing complimentary meal vouchers so you can enjoy a free lunch, on us, when we get to the area around the cannery.","Chào mừng quý khách đến với chuyến tham quan bằng xe buýt quanh cảng Kensey. Rất tiếc, một trong các điểm dừng trong lịch trình của chúng ta là bảo tàng hiện đang đóng cửa, và chúng ta sẽ không thể tham quan nơi đó. Đêm qua bảo tàng bị vỡ một đường ống nước. Có vẻ như việc sửa chữa và dọn dẹp sẽ kéo dài suốt tuần này. Tôi xin lỗi, vì tôi biết nhiều quý khách đã mong được xem triển lãm về các loài cá địa phương của bảo tàng. Để bù lại, chúng tôi tặng phiếu ăn miễn phí để quý khách thưởng thức bữa trưa miễn phí do chúng tôi đãi khi đến khu vực quanh nhà máy đóng hộp."]],"qs":[{"n":98,"q":"Look at the graphic. Which stop has been canceled?","qvi":"Hãy nhìn vào bản đồ. Điểm dừng nào đã bị hủy?","opts":["Stop 1","Stop 2","Stop 3","Stop 4"],"vi":["Điểm dừng 1","Điểm dừng 2","Điểm dừng 3","Điểm dừng 4"],"ans":"C","xp":"\"one of the stops on our itinerary, the museum, is closed, and we won't be able to visit it.\" Theo bản đồ, Museum là Stop 3 → (C). (Stop 1: City Hall, Stop 2: Post Office, Stop 4: Cannery)"},{"n":99,"q":"Why has a stop been canceled?","qvi":"Tại sao một điểm dừng bị hủy?","opts":["A guest speaker is unavailable.","A building is undergoing maintenance.","An area has closed for a festival.","A private event has been scheduled."],"vi":["Một diễn giả khách mời không có mặt được.","Một tòa nhà đang được bảo trì sửa chữa.","Một khu vực đóng cửa để tổ chức lễ hội.","Đã có một sự kiện riêng được lên lịch."],"ans":"B","xp":"\"The museum had a water pipe burst overnight. It looks like repair and cleanup work will last this whole week.\" → tòa nhà đang được sửa chữa. Paraphrase: repair and cleanup work → maintenance."},{"n":100,"q":"What will the listeners receive?","qvi":"Người nghe sẽ nhận được gì?","opts":["A refund","A souvenir","A printed map","Meal vouchers"],"vi":["Tiền hoàn lại","Một món quà lưu niệm","Một bản đồ in","Phiếu ăn"],"ans":"D","xp":"\"To make up for this, we're providing complimentary meal vouchers so you can enjoy a free lunch\" → khách sẽ nhận phiếu ăn miễn phí → (D)."}],"a":"E24-T06-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"The new policy allows employees to set ------- own working hours under certain conditions.","opts":["they","their","theirs","themselves"],"ans":"B","xp":"Đại từ. Sau chỗ trống là 'own working hours' → cần tính từ sở hữu đứng trước 'own' (cấu trúc 'one's own + danh từ'). (B) their là tính từ sở hữu → chọn (B). (A) they là đại từ chủ ngữ, (C) theirs là đại từ sở hữu (không đứng trước danh từ), (D) themselves là đại từ phản thân.\nDịch: Chính sách mới cho phép nhân viên tự đặt giờ làm việc của riêng họ trong một số điều kiện nhất định."},{"n":102,"q":"Based on last year's data, Paik Company increased its sales projections ------- the current year.","opts":["when","for","if","or"],"ans":"B","xp":"Giới từ / liên từ. Sau chỗ trống là cụm danh từ 'the current year' (không có động từ) → cần giới từ. (B) for 'cho, dành cho' → 'sales projections for the current year' = dự báo doanh số cho năm nay → chọn (B). (A) when, (C) if là liên từ (cần mệnh đề), (D) or là liên từ đẳng lập, không hợp nghĩa.\nDịch: Dựa trên dữ liệu năm ngoái, Công ty Paik đã tăng dự báo doanh số cho năm nay."},{"n":103,"q":"Harbison's Department Store interviews applicants ------- standard business hours.","opts":["among","beside","during","onto"],"ans":"C","xp":"Giới từ. 'standard business hours' (giờ làm việc thông thường) là một khoảng thời gian → dùng (C) during 'trong suốt' → chọn (C). (A) among 'giữa (nhiều người/vật)', (B) beside 'bên cạnh', (D) onto 'lên trên' đều không chỉ thời gian.\nDịch: Cửa hàng bách hóa Harbison phỏng vấn ứng viên trong giờ làm việc thông thường."},{"n":104,"q":"Takealong Industries' commercial propane heaters deliver more warmth to ------- areas.","opts":["wideness","widen","wider","widely"],"ans":"C","xp":"Từ loại. Sau chỗ trống là danh từ 'areas' → cần tính từ. (C) wider là tính từ so sánh hơn 'rộng hơn' → 'wider areas' = những khu vực rộng hơn, hợp với 'more warmth' → chọn (C). (A) wideness là danh từ, (B) widen là động từ, (D) widely là trạng từ.\nDịch: Máy sưởi propane thương mại của Takealong Industries cung cấp nhiều hơi ấm hơn cho những khu vực rộng hơn."},{"n":105,"q":"By switching to new project-management software, the editorial team has ------- improved its publication processes.","opts":["great","greatly","greater","greatest"],"ans":"B","xp":"Từ loại. Chỗ trống nằm giữa trợ động từ 'has' và quá khứ phân từ 'improved' → cần trạng từ bổ nghĩa cho động từ. (B) greatly 'rất nhiều, đáng kể' là trạng từ → chọn (B). (A) great, (C) greater, (D) greatest đều là tính từ.\nDịch: Nhờ chuyển sang phần mềm quản lý dự án mới, nhóm biên tập đã cải thiện đáng kể quy trình xuất bản của mình."},{"n":106,"q":"The search committee ------- three candidates for the chief executive position.","opts":["nominating","nomination","has nominated","has been nominated"],"ans":"C","xp":"Dạng động từ (chủ động / bị động). Câu chưa có động từ chính → loại (A) nominating (V-ing không làm động từ chính một mình) và (B) nomination (danh từ). Sau chỗ trống có tân ngữ 'three candidates' → cần thể chủ động: (C) has nominated 'đã đề cử' → chọn (C). (D) has been nominated là bị động, không đi với tân ngữ.\nDịch: Ủy ban tuyển chọn đã đề cử ba ứng viên cho vị trí giám đốc điều hành."},{"n":107,"q":"------- a two-month delay, new carpeting was installed in the east conference room.","opts":["Additionally","Although","After","Furthermore"],"ans":"C","xp":"Giới từ / liên từ / trạng từ. Sau chỗ trống là cụm danh từ 'a two-month delay' → cần giới từ. (C) After 'sau' là giới từ → 'Sau hai tháng trì hoãn' → chọn (C). (B) Although là liên từ (cần mệnh đề có động từ); (A) Additionally 'ngoài ra' và (D) Furthermore 'hơn nữa' là trạng từ liên kết, không đứng trước cụm danh từ như vậy.\nDịch: Sau hai tháng trì hoãn, thảm mới đã được lắp đặt ở phòng hội nghị phía đông."},{"n":108,"q":"To boost -------, the Makeup Artist Academy is offering a free starter kit to new students.","opts":["enroll","enrolled","enrolling","enrollment"],"ans":"D","xp":"Từ loại. Sau động từ 'boost' (thúc đẩy, tăng) cần một danh từ làm tân ngữ. (D) enrollment 'số lượng đăng ký học / việc ghi danh' là danh từ → chọn (D). (A) enroll là động từ, (B) enrolled là quá khứ / phân từ, (C) enrolling là V-ing (không hợp nghĩa ở đây).\nDịch: Để tăng số lượng học viên đăng ký, Học viện Trang điểm Makeup Artist đang tặng bộ dụng cụ khởi đầu miễn phí cho học viên mới."},{"n":109,"q":"Because Lectula Furniture Company ------- its delivery times, we were able to set a firm opening date for the new hotel.","opts":["guarantees","advises","requires","delays"],"ans":"A","xp":"Từ vựng (động từ). Vế sau 'chúng tôi đã có thể ấn định ngày khai trương chắc chắn' → vì công ty nội thất bảo đảm thời gian giao hàng. (A) guarantees 'bảo đảm' → chọn (A). (B) advises 'khuyên', (C) requires 'yêu cầu', (D) delays 'trì hoãn' (ngược nghĩa — trì hoãn thì không thể ấn định ngày chắc chắn).\nDịch: Vì Công ty Nội thất Lectula bảo đảm thời gian giao hàng, chúng tôi đã có thể ấn định một ngày khai trương chắc chắn cho khách sạn mới."},{"n":110,"q":"The computer technician was very ------- but was not able to solve my problem.","opts":["friendly","neutral","possible","frequent"],"ans":"A","xp":"Từ vựng (tính từ). Liên từ 'but' cho thấy hai vế tương phản: kỹ thuật viên có điểm tốt NHƯNG không giải quyết được vấn đề. (A) friendly 'thân thiện' → chọn (A). (B) neutral 'trung lập', (C) possible 'có thể' (không dùng cho người), (D) frequent 'thường xuyên' đều không hợp.\nDịch: Kỹ thuật viên máy tính rất thân thiện nhưng không thể giải quyết được vấn đề của tôi."},{"n":111,"q":"To make room for conference attendees, ------- visitors to the office building should use the rear parking area tomorrow.","opts":["regular","regularly","regularize","regularity"],"ans":"A","xp":"Từ loại. Sau chỗ trống là danh từ 'visitors' → cần tính từ. (A) regular 'thường xuyên, quen thuộc' → 'regular visitors' = khách thường đến tòa nhà → chọn (A). (B) regularly là trạng từ, (C) regularize là động từ, (D) regularity là danh từ.\nDịch: Để nhường chỗ cho người tham dự hội nghị, ngày mai những khách thường xuyên đến tòa nhà văn phòng nên sử dụng bãi đỗ xe phía sau."},{"n":112,"q":"Employees must wear their security badge in a way that is ------- visible when in the building.","opts":["clearly","recently","evenly","secretly"],"ans":"A","xp":"Từ vựng (trạng từ). Cần trạng từ bổ nghĩa cho tính từ 'visible' (có thể nhìn thấy). (A) clearly visible 'nhìn thấy rõ ràng' là cụm kết hợp tự nhiên → chọn (A). (B) recently 'gần đây', (C) evenly 'đều nhau', (D) secretly 'bí mật' không hợp nghĩa.\nDịch: Nhân viên phải đeo thẻ an ninh sao cho có thể nhìn thấy rõ ràng khi ở trong tòa nhà."},{"n":113,"q":"Ms. Phon wanted to attend the gallery opening; -------, the inclement weather made that impossible.","opts":["therefore","following","however","for example"],"ans":"C","xp":"Trạng từ liên kết. Hai vế tương phản: cô ấy muốn tham dự buổi khai mạc triển lãm — nhưng thời tiết xấu khiến việc đó không thể. Cấu trúc '; ______,' → dùng (C) however 'tuy nhiên' → chọn (C). (A) therefore 'vì vậy' (chỉ kết quả), (B) following 'sau', (D) for example 'ví dụ' không hợp.\nDịch: Cô Phon muốn tham dự buổi khai mạc phòng tranh; tuy nhiên, thời tiết khắc nghiệt đã khiến điều đó không thể."},{"n":114,"q":"Giving leadership tasks to warehouse package handlers often ------- them to work more productively.","opts":["adopts","reinforces","motivates","attracts"],"ans":"C","xp":"Từ vựng (động từ). Cấu trúc 'động từ + them + to V'. (C) motivates sb to do sth 'thúc đẩy, tạo động lực cho ai làm gì' → chọn (C). (A) adopts 'áp dụng, nhận nuôi', (B) reinforces 'củng cố', (D) attracts 'thu hút' không dùng với cấu trúc 'sb to V' theo nghĩa này.\nDịch: Việc giao nhiệm vụ lãnh đạo cho nhân viên xử lý hàng trong kho thường thúc đẩy họ làm việc năng suất hơn."},{"n":115,"q":"Kaybing Construction works ------- on large commercial projects in the Newfoundland area.","opts":["exclusively","exclusive","exclusivity","exclusives"],"ans":"A","xp":"Từ loại. Sau động từ 'works' (nội động từ) cần trạng từ bổ nghĩa. (A) exclusively 'chỉ, độc quyền' là trạng từ → 'works exclusively on' = chỉ làm các dự án... → chọn (A). (B) exclusive là tính từ, (C) exclusivity và (D) exclusives là danh từ.\nDịch: Công ty Xây dựng Kaybing chỉ làm các dự án thương mại lớn ở khu vực Newfoundland."},{"n":116,"q":"Carly Logan plans -------, so Alan Zill has volunteered to be the stamp club's next treasurer.","opts":["resigning","to resign","resigns","to have resigned"],"ans":"B","xp":"Dạng động từ. Cấu trúc 'plan + to V' (dự định làm gì). (B) to resign 'từ chức' → chọn (B). (A) resigning sai cấu trúc, (C) resigns là động từ chia, (D) to have resigned là to V hoàn thành (chỉ việc đã xảy ra trước), không hợp với 'dự định' trong tương lai.\nDịch: Carly Logan dự định từ chức, vì vậy Alan Zill đã tình nguyện làm thủ quỹ tiếp theo của câu lạc bộ tem."},{"n":117,"q":"Although the housing market slowed ------- the summer months, sales began to pick up again in the autumn.","opts":["apart","even","only","over"],"ans":"D","xp":"Giới từ. Sau chỗ trống là cụm danh từ chỉ thời gian 'the summer months' → cần giới từ. (D) over 'trong suốt (một khoảng thời gian)' → 'over the summer months' = trong suốt mấy tháng hè → chọn (D). (A) apart 'tách rời', (B) even 'thậm chí', (C) only 'chỉ' là trạng từ.\nDịch: Mặc dù thị trường nhà ở chậm lại trong suốt những tháng mùa hè, doanh số đã bắt đầu tăng trở lại vào mùa thu."},{"n":118,"q":"To remain fully functional, the exercise machines need to be cleaned -------.","opts":["rather","almost","routinely","openly"],"ans":"C","xp":"Từ vựng (trạng từ). Để máy tập luôn hoạt động tốt thì cần được lau chùi định kỳ. (C) routinely 'thường xuyên, định kỳ' → chọn (C). (A) rather 'khá, đúng hơn', (B) almost 'gần như', (D) openly 'công khai' không hợp nghĩa.\nDịch: Để luôn hoạt động tốt, các máy tập thể dục cần được lau chùi định kỳ."},{"n":119,"q":"The extended warranty is good for ten years or 100,000 miles, ------- comes first.","opts":["whoever","either","whichever","another"],"ans":"C","xp":"Đại từ quan hệ phức. Chỗ trống làm chủ ngữ cho 'comes first', chọn giữa hai thứ (10 năm hoặc 100.000 dặm) → (C) whichever 'cái nào ... (thì)' → 'whichever comes first' = tùy điều kiện nào đến trước → chọn (C). (A) whoever dùng cho người, (B) either 'một trong hai' không nối được mệnh đề, (D) another 'cái khác'.\nDịch: Bảo hành mở rộng có hiệu lực trong mười năm hoặc 100.000 dặm, tùy điều kiện nào đến trước."},{"n":120,"q":"Atlantic Grocers must offer online shopping options or ------- losing customers to other supermarkets.","opts":["risk","protect","cancel","hold"],"ans":"A","xp":"Từ vựng (động từ). 'or' nối hai động từ nguyên mẫu sau 'must': phải cung cấp mua sắm trực tuyến, nếu không thì có nguy cơ mất khách. (A) risk + V-ing 'có nguy cơ, liều' → 'risk losing customers' → chọn (A). (B) protect 'bảo vệ', (C) cancel 'hủy', (D) hold 'giữ' không hợp nghĩa.\nDịch: Atlantic Grocers phải cung cấp các lựa chọn mua sắm trực tuyến, nếu không sẽ có nguy cơ mất khách hàng vào tay các siêu thị khác."},{"n":121,"q":"------- client is assigned to a personal financial adviser to whom inquiries should be addressed.","opts":["Each","All","Some","Most"],"ans":"A","xp":"Từ hạn định. Sau chỗ trống là danh từ đếm được số ít 'client' và động từ số ít 'is' → dùng (A) Each 'mỗi' → chọn (A). (B) All, (C) Some, (D) Most đi với danh từ số nhiều (hoặc không đếm được), không đi với 'client' số ít.\nDịch: Mỗi khách hàng được chỉ định một cố vấn tài chính riêng, người mà các thắc mắc nên được gửi đến."},{"n":122,"q":"Mr. Singh wants to form a ------- to explore some employee reward programs.","opts":["supervisor","suggestion","notification","committee"],"ans":"D","xp":"Từ vựng (danh từ). Động từ 'form' (thành lập) thường đi với một nhóm người: 'form a committee' = thành lập một ủy ban → chọn (D). (A) supervisor 'người giám sát', (B) suggestion 'đề xuất', (C) notification 'thông báo' không đi với 'form' theo nghĩa này.\nDịch: Ông Singh muốn thành lập một ủy ban để tìm hiểu một số chương trình khen thưởng nhân viên."},{"n":123,"q":"Please provide your phone number ------- the delivery driver needs to contact you.","opts":["whereas","despite","if not","in case"],"ans":"D","xp":"Liên từ. Sau chỗ trống là mệnh đề 'the delivery driver needs to contact you'. Nghĩa: cung cấp số điện thoại phòng khi tài xế cần liên lạc → (D) in case 'phòng khi' → chọn (D). (A) whereas 'trong khi (đối lập)', (B) despite là giới từ (không đi với mệnh đề), (C) if not 'nếu không' không hợp nghĩa.\nDịch: Vui lòng cung cấp số điện thoại của bạn phòng khi tài xế giao hàng cần liên lạc với bạn."},{"n":124,"q":"------- of Pondview Tower are required to make rent payments on or before the first day of every month.","opts":["Owners","Buyers","Tourists","Tenants"],"ans":"D","xp":"Từ vựng (danh từ). Người phải trả tiền thuê nhà ('rent payments') hằng tháng là người thuê. (D) Tenants 'người thuê nhà' → chọn (D). (A) Owners 'chủ sở hữu', (B) Buyers 'người mua', (C) Tourists 'khách du lịch' không trả tiền thuê hằng tháng.\nDịch: Người thuê nhà ở tòa Pondview Tower phải thanh toán tiền thuê vào hoặc trước ngày đầu tiên của mỗi tháng."},{"n":125,"q":"Likoni Hospitality Group, one of Mombasa's largest employers, has a ------- impact on the local economy.","opts":["considerably","considerable","considering","consideration"],"ans":"B","xp":"Từ loại. Giữa mạo từ 'a' và danh từ 'impact' cần tính từ. (B) considerable 'đáng kể, lớn' → chọn (B). (A) considerably là trạng từ, (C) considering là V-ing / giới từ 'xét đến', (D) consideration là danh từ.\nDịch: Tập đoàn Khách sạn Likoni, một trong những nhà tuyển dụng lớn nhất Mombasa, có tác động đáng kể đến nền kinh tế địa phương."},{"n":126,"q":"------- best sellers, Booksters offers a wide selection of classics and biographies.","opts":["Besides","Somewhat","Whose","Becoming"],"ans":"A","xp":"Giới từ. Sau chỗ trống là cụm danh từ 'best sellers', sau dấu phẩy là mệnh đề hoàn chỉnh → cần giới từ. (A) Besides 'ngoài ... ra' → 'Ngoài sách bán chạy, Booksters còn có...' → chọn (A). (B) Somewhat 'hơi, phần nào' là trạng từ, (C) Whose là đại từ quan hệ, (D) Becoming 'trở thành' không hợp nghĩa.\nDịch: Ngoài những cuốn sách bán chạy, Booksters còn cung cấp nhiều lựa chọn sách kinh điển và tiểu sử."},{"n":127,"q":"New food regulations require all Dean's Burgers packaging to contain the notice that ------- undercooked meat can be harmful.","opts":["consumer","consumption","consumes","consuming"],"ans":"D","xp":"Từ loại (danh động từ). Mệnh đề sau 'that' có động từ 'can be' nhưng thiếu chủ ngữ; chỗ trống đứng ngay trước cụm danh từ 'undercooked meat' (tân ngữ) → cần danh động từ (V-ing) vừa làm chủ ngữ vừa nhận tân ngữ: 'consuming undercooked meat' = việc ăn thịt chưa chín kỹ → chọn (D). (B) consumption là danh từ, không thể có tân ngữ trực tiếp (phải là 'consumption of undercooked meat'); (A) consumer 'người tiêu dùng' không hợp nghĩa và cũng không nối trực tiếp với danh từ phía sau; (C) consumes là động từ chia, câu sẽ thiếu chủ ngữ và thừa động từ.\nDịch: Quy định thực phẩm mới yêu cầu mọi bao bì của Dean's Burgers phải có thông báo rằng việc ăn thịt chưa chín kỹ có thể gây hại."},{"n":128,"q":"Each Genutria snack bar contains as much protein as two eggs, with none ------- the fat and cholesterol.","opts":["of","by","out","minus"],"ans":"A","xp":"Giới từ. Cấu trúc 'none of + the + danh từ' = không có chút nào trong số... → 'with none of the fat and cholesterol' = mà không có chút chất béo và cholesterol nào → chọn (A). (B) by 'bởi', (C) out 'ra ngoài', (D) minus 'trừ đi' không đi sau 'none' theo cách này.\nDịch: Mỗi thanh snack Genutria chứa lượng protein bằng hai quả trứng, mà không có chút chất béo và cholesterol nào."},{"n":129,"q":"Fisko eyeglass frames come in various -------, including round, square, and oval.","opts":["sights","methods","shapes","materials"],"ans":"C","xp":"Từ vựng (danh từ). 'round, square, and oval' (tròn, vuông, bầu dục) là các hình dạng → (C) shapes 'hình dạng' → chọn (C). (A) sights 'cảnh, tầm nhìn', (B) methods 'phương pháp', (D) materials 'chất liệu' không khớp với ví dụ.\nDịch: Gọng kính Fisko có nhiều hình dạng khác nhau, bao gồm tròn, vuông và bầu dục."},{"n":130,"q":"The CEO wants a greater portion of next year's budget ------- to research and development.","opts":["allocated","imprinted","economized","rationalized"],"ans":"A","xp":"Từ vựng (động từ – quá khứ phân từ). Cấu trúc 'want + tân ngữ + V3' (muốn cái gì được làm). 'allocate sth to sth' = phân bổ cái gì cho việc gì → 'budget allocated to research and development' → chọn (A). (B) imprinted 'in dấu', (C) economized 'tiết kiệm', (D) rationalized 'hợp lý hóa' không đi với 'to R&D'.\nDịch: Giám đốc điều hành muốn một phần lớn hơn của ngân sách năm tới được phân bổ cho nghiên cứu và phát triển."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following advertisement.","passage":"<h3>Estella Guitar Lessons: Play with the Best</h3><p>Whether you play acoustic guitar <span class=\"blank\" data-n=\"131\">-------</span> electric, taking lessons with an Estella Guitar teacher is the best way to improve your ability. With years of experience crafting playing techniques, <span class=\"blank\" data-n=\"132\">-------</span> qualified instructors can tailor lessons to focus on the skills you want to fine-tune. Receive a customized learning plan to set goals and overcome the challenges that cause many players to get discouraged. <span class=\"blank\" data-n=\"133\">-------</span>. An Estella Guitar teacher will help boost your confidence.</p><p>At Estella Guitar, we believe that playing music is a way of expressing yourself. <span class=\"blank\" data-n=\"134\">-------</span>, we will help you go beyond the familiar chords and riffs to develop your own identity as a musician. Ready to get started? Visit www.estellaguitar.com/lessons to get matched with the right instructor for you!</p>","vi":"Lớp học guitar Estella: Chơi cùng những người giỏi nhất\n\nDù bạn chơi guitar acoustic hay guitar điện, học với một giáo viên của Estella Guitar là cách tốt nhất để nâng cao khả năng của bạn. Với nhiều năm kinh nghiệm xây dựng các kỹ thuật chơi đàn, những giảng viên có trình độ của chúng tôi có thể điều chỉnh bài học để tập trung vào những kỹ năng bạn muốn trau chuốt. Hãy nhận một kế hoạch học tập riêng để đặt mục tiêu và vượt qua những thử thách khiến nhiều người chơi nản lòng. Nguồn hỗ trợ tốt nhất cho bạn với tư cách người học là một chuyên gia dẫn dắt sự tiến bộ của bạn. Một giáo viên của Estella Guitar sẽ giúp bạn tự tin hơn.\n\nTại Estella Guitar, chúng tôi tin rằng chơi nhạc là một cách thể hiện bản thân. Với suy nghĩ đó, chúng tôi sẽ giúp bạn vượt ra ngoài những hợp âm và đoạn riff quen thuộc để phát triển bản sắc riêng của mình với tư cách một nhạc sĩ. Sẵn sàng bắt đầu chưa? Hãy truy cập www.estellaguitar.com/lessons để được ghép với giảng viên phù hợp với bạn!","qs":[{"n":131,"opts":["is","or","likely","from"],"ans":"B","xp":"Liên từ. Cấu trúc 'whether A or B' = dù A hay B → 'Whether you play acoustic guitar or electric' → chọn (B). (A) is là động từ, (C) likely 'có lẽ', (D) from 'từ' không tạo thành cặp với 'whether'.\nDịch: Dù bạn chơi guitar acoustic hay guitar điện, ..."},{"n":132,"opts":["our","ourselves","ours","us"],"ans":"A","xp":"Đại từ. Sau chỗ trống là cụm danh từ 'qualified instructors' → cần tính từ sở hữu. (A) our 'của chúng tôi' → 'our qualified instructors' → chọn (A). (B) ourselves là đại từ phản thân, (C) ours là đại từ sở hữu (không đứng trước danh từ), (D) us là đại từ tân ngữ.\nDịch: ..., những giảng viên có trình độ của chúng tôi có thể điều chỉnh bài học để tập trung vào những kỹ năng bạn muốn trau chuốt."},{"n":133,"opts":["Contact a technician for questions about repairs.","A high-quality instrument will help you to perform at your best.","The best resource for you as a learner is an expert to guide your progress.","It took them several years to master their instruments."],"ans":"C","xp":"Điền câu. Câu trước nói về việc vượt qua những thử thách khiến người chơi nản lòng; câu sau nói 'An Estella Guitar teacher will help boost your confidence.' Câu (C) 'Nguồn hỗ trợ tốt nhất cho người học là một chuyên gia dẫn dắt sự tiến bộ của bạn' nối tự nhiên: chuyên gia (expert) chính là giáo viên Estella ở câu sau → chọn (C). (A) nói về kỹ thuật viên sửa chữa, (B) nói về nhạc cụ chất lượng cao — lạc chủ đề lớp học; (D) 'them' không có đối tượng rõ ràng để chỉ.\n(A) Hãy liên hệ kỹ thuật viên nếu có câu hỏi về sửa chữa.\n(B) Một nhạc cụ chất lượng cao sẽ giúp bạn biểu diễn tốt nhất.\n(C) Nguồn hỗ trợ tốt nhất cho bạn với tư cách người học là một chuyên gia dẫn dắt sự tiến bộ của bạn.\n(D) Họ đã mất vài năm để thành thạo nhạc cụ của mình."},{"n":134,"opts":["So far","With that in mind","On a different note","At that point"],"ans":"B","xp":"Trạng từ / cụm từ nối. Câu trước: 'chúng tôi tin rằng chơi nhạc là một cách thể hiện bản thân'; câu sau: 'chúng tôi sẽ giúp bạn phát triển bản sắc riêng như một nhạc sĩ' → câu sau là hành động xuất phát từ niềm tin ở câu trước. (B) With that in mind 'với suy nghĩ đó, vì thế' → chọn (B). (A) So far 'cho đến nay', (C) On a different note 'chuyển sang chuyện khác', (D) At that point 'vào lúc đó' không hợp.\nDịch: Với suy nghĩ đó, chúng tôi sẽ giúp bạn vượt ra ngoài những hợp âm và đoạn riff quen thuộc ..."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following policy.","passage":"<p>In-home delivery takes approximately one week after an order is shipped from our warehouse. The actual time may vary based on the location of your <span class=\"blank\" data-n=\"135\">-------</span> and your availability for accepting the item. Vernico Furniture will work with a carrier <span class=\"blank\" data-n=\"136\">-------</span> an appointment that is convenient for you. Typical hours are Monday through Friday between 8 A.M. and 5 P.M., <span class=\"blank\" data-n=\"137\">-------</span> evening appointments can often be arranged. Upon arrival at your home, the item will be placed in the location you desire. <span class=\"blank\" data-n=\"138\">-------</span>. Assembly is included as well.</p>","vi":"Việc giao hàng tận nhà mất khoảng một tuần sau khi đơn hàng được gửi đi từ kho của chúng tôi. Thời gian thực tế có thể thay đổi tùy theo vị trí nơi ở của bạn và thời gian bạn có thể nhận hàng. Nội thất Vernico sẽ phối hợp với đơn vị vận chuyển để sắp xếp một cuộc hẹn thuận tiện cho bạn. Giờ giao hàng thông thường là từ thứ Hai đến thứ Sáu, từ 8 giờ sáng đến 5 giờ chiều, tuy nhiên thường có thể sắp xếp các cuộc hẹn buổi tối. Khi đến nhà bạn, sản phẩm sẽ được đặt ở vị trí bạn mong muốn. Toàn bộ vật liệu đóng gói sẽ được dọn đi. Dịch vụ lắp ráp cũng đã bao gồm.","qs":[{"n":135,"opts":["garden","records","residence","organization"],"ans":"C","xp":"Từ vựng (danh từ). Đây là chính sách giao hàng tận nhà ('In-home delivery'); thời gian giao phụ thuộc vào vị trí nơi ở của khách. (C) residence 'nơi ở, nhà' → chọn (C). (A) garden 'khu vườn', (B) records 'hồ sơ', (D) organization 'tổ chức' không hợp.\nDịch: Thời gian thực tế có thể thay đổi tùy theo vị trí nơi ở của bạn và thời gian bạn có thể nhận hàng."},{"n":136,"opts":["to schedule","is scheduling","as a schedule","that scheduled"],"ans":"A","xp":"Dạng động từ. Câu đã có động từ chính 'will work' → chỗ trống cần to V chỉ mục đích: 'work with a carrier to schedule an appointment' = phối hợp với đơn vị vận chuyển để lên lịch hẹn → chọn (A). (B) is scheduling là động từ chia (thừa động từ chính), (C) as a schedule 'như một lịch trình' không có tân ngữ được, (D) that scheduled (thì quá khứ) không hợp với thời điểm tương lai.\nDịch: Nội thất Vernico sẽ phối hợp với đơn vị vận chuyển để sắp xếp một cuộc hẹn thuận tiện cho bạn."},{"n":137,"opts":["if so","when","though","in the meantime"],"ans":"C","xp":"Liên từ. Hai mệnh đề tương phản: giờ thông thường là 8 giờ sáng – 5 giờ chiều, thứ Hai đến thứ Sáu; tuy vậy vẫn có thể hẹn buổi tối. Cần liên từ nối hai mệnh đề sau dấu phẩy → (C) though 'mặc dù, tuy nhiên' → chọn (C). (A) if so 'nếu vậy' và (D) in the meantime 'trong lúc đó' là trạng từ, không nối mệnh đề; (B) when 'khi' không hợp nghĩa.\nDịch: Giờ thông thường là thứ Hai đến thứ Sáu, từ 8 giờ sáng đến 5 giờ chiều, tuy nhiên thường có thể sắp xếp các cuộc hẹn buổi tối."},{"n":138,"opts":["When buying a home, location is extremely important.","Refinishing furniture is a form of art.","Furnished apartments can be found online.","All packing materials will be removed."],"ans":"D","xp":"Điền câu. Câu trước: 'khi đến nhà bạn, sản phẩm sẽ được đặt ở vị trí bạn muốn'; câu sau: 'Assembly is included as well' (lắp ráp CŨNG được bao gồm). Chỗ trống cần thêm một dịch vụ khác khi giao hàng → (D) 'Toàn bộ vật liệu đóng gói sẽ được dọn đi' → chọn (D); 'as well' ở câu sau cho thấy câu trước đó cũng là một dịch vụ. (A), (B), (C) nói về mua nhà, sơn sửa đồ gỗ, căn hộ có nội thất — lạc chủ đề.\n(A) Khi mua nhà, vị trí là cực kỳ quan trọng.\n(B) Làm mới đồ nội thất là một loại hình nghệ thuật.\n(C) Có thể tìm căn hộ có sẵn nội thất trên mạng.\n(D) Toàn bộ vật liệu đóng gói sẽ được dọn đi."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Thao Pham &lt;thaopham@amail.com&gt;</p><p><b>From:</b> Leena Montoya &lt;lmontoya@academemedia.com&gt;</p><p><b>Date:</b> April 17</p><p><b>Subject:</b> Subscription</p></div><p>Dear Mr. Pham,</p><p><span class=\"blank\" data-n=\"139\">-------</span>. Your subscription to <i>Medical Innovations Quarterly</i> has been canceled. <span class=\"blank\" data-n=\"140\">-------</span> May 1, you will no longer receive the print edition.</p><p>We hope that you will consider once again becoming a <span class=\"blank\" data-n=\"141\">-------</span> of our publications. Academe Media publishes many high-quality scientific journals in addition to <i>Medical Innovations Quarterly</i>. Should you wish to subscribe to one by May 31, we can offer you a two-year subscription at the annual rate. Visit www.academemedia.com/shop and enter the code DOUBLE <span class=\"blank\" data-n=\"142\">-------</span> checkout.</p><p>If you have any feedback that could help us improve our products or services, please call me directly at 212-555-0122.</p><p>Sincerely,</p><p>Leena Montoya<br>Customer Service Manager, Academe Media</p>","vi":"Người nhận: Thao Pham <thaopham@amail.com>\nNgười gửi: Leena Montoya <lmontoya@academemedia.com>\nNgày: 17 tháng 4\nTiêu đề: Đăng ký dài hạn\n\nKính gửi ông Pham,\n\nChúng tôi đã xử lý yêu cầu của ông. Gói đăng ký tạp chí Medical Innovations Quarterly của ông đã được hủy. Bắt đầu từ ngày 1 tháng 5, ông sẽ không còn nhận được bản in nữa.\n\nChúng tôi hy vọng ông sẽ cân nhắc trở lại làm độc giả của các ấn phẩm của chúng tôi. Ngoài Medical Innovations Quarterly, Academe Media còn xuất bản nhiều tạp chí khoa học chất lượng cao khác. Nếu ông muốn đăng ký một tạp chí trước ngày 31 tháng 5, chúng tôi có thể dành cho ông gói đăng ký hai năm với giá của một năm. Hãy truy cập www.academemedia.com/shop và nhập mã DOUBLE khi thanh toán.\n\nNếu ông có bất kỳ góp ý nào có thể giúp chúng tôi cải thiện sản phẩm hoặc dịch vụ, vui lòng gọi trực tiếp cho tôi theo số 212-555-0122.\n\nTrân trọng,\n\nLeena Montoya\nQuản lý Dịch vụ Khách hàng, Academe Media","qs":[{"n":139,"opts":["Thank you for your timely order.","We have processed your request.","This is a payment reminder.","Please contact us to update your information."],"ans":"B","xp":"Điền câu. Câu ngay sau: 'Your subscription ... has been canceled' (gói đăng ký của ông đã được hủy) → khách đã yêu cầu hủy và công ty báo đã xử lý xong. (B) 'Chúng tôi đã xử lý yêu cầu của ông' → chọn (B). (A) cảm ơn vì đã đặt hàng, (C) nhắc thanh toán, (D) yêu cầu cập nhật thông tin đều không khớp với việc hủy đăng ký.\n(A) Cảm ơn ông đã đặt hàng kịp thời.\n(B) Chúng tôi đã xử lý yêu cầu của ông.\n(C) Đây là thư nhắc thanh toán.\n(D) Vui lòng liên hệ chúng tôi để cập nhật thông tin của ông."},{"n":140,"opts":["Starts","Started","Starter","Starting"],"ans":"D","xp":"Từ loại / cụm cố định. 'Starting + mốc thời gian' = bắt đầu từ (ngày...), dùng như giới từ → 'Starting May 1, you will no longer receive...' → chọn (D). (A) Starts và (B) Started là động từ chia, câu sẽ thừa động từ / thiếu chủ ngữ; (C) Starter là danh từ 'người/vật khởi đầu'.\nDịch: Bắt đầu từ ngày 1 tháng 5, ông sẽ không còn nhận được bản in nữa."},{"n":141,"opts":["distributor","producer","reader","teacher"],"ans":"C","xp":"Từ vựng (danh từ). Ông Pham vừa hủy đăng ký tạp chí; công ty hy vọng ông lại trở thành người đọc các ấn phẩm của họ. (C) reader 'độc giả' → chọn (C). (A) distributor 'nhà phân phối', (B) producer 'nhà sản xuất', (D) teacher 'giáo viên' không hợp với vai trò người đăng ký tạp chí.\nDịch: Chúng tôi hy vọng ông sẽ cân nhắc trở lại làm độc giả của các ấn phẩm của chúng tôi."},{"n":142,"opts":["until","upon","without","next"],"ans":"B","xp":"Giới từ. Nhập mã giảm giá khi thanh toán → (B) upon 'khi, vào lúc' → 'upon checkout' = khi thanh toán → chọn (B). (A) until 'cho đến khi', (C) without 'không có', (D) next 'kế tiếp' không hợp nghĩa.\nDịch: Hãy truy cập www.academemedia.com/shop và nhập mã DOUBLE khi thanh toán."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following information.","passage":"<p>In a commercial kitchen, all refrigerators are required to have a thermometer that <span class=\"blank\" data-n=\"143\">-------</span> from 0°F (-18°C) to 220°F (104°C). To prevent the growth of bacteria, refrigerated foods must be stored at 41°F (5°C) or below. The head chef is responsible for checking these thermometers throughout the day to ensure that the kitchen is in compliance at all times.</p><p>Also important to consider is <span class=\"blank\" data-n=\"144\">-------</span>. Thermometers should always be located in the warmest spot in the refrigerator. <span class=\"blank\" data-n=\"145\">-------</span>. This location is also appropriate because it allows the thermometer to be easily <span class=\"blank\" data-n=\"146\">-------</span> as soon as the door is opened.</p>","vi":"Trong một bếp ăn thương mại, tất cả tủ lạnh đều bắt buộc phải có nhiệt kế đo được trong khoảng từ 0°F (-18°C) đến 220°F (104°C). Để ngăn vi khuẩn phát triển, thực phẩm bảo quản lạnh phải được giữ ở nhiệt độ 41°F (5°C) hoặc thấp hơn. Bếp trưởng có trách nhiệm kiểm tra các nhiệt kế này suốt cả ngày để bảo đảm nhà bếp luôn tuân thủ quy định.\n\nMột điều quan trọng khác cần cân nhắc là vị trí đặt nhiệt kế. Nhiệt kế luôn phải được đặt ở chỗ ấm nhất trong tủ lạnh. Chỗ này thường là ở phía trong cửa tủ. Vị trí này cũng phù hợp vì nó giúp dễ dàng nhìn thấy nhiệt kế ngay khi mở cửa tủ.","qs":[{"n":143,"opts":["ranges","ranger","ranged","ranging"],"ans":"A","xp":"Dạng động từ. Sau đại từ quan hệ 'that' (thay cho 'a thermometer', số ít) cần động từ chia. 'range from A to B' = dao động / đo được trong khoảng từ A đến B. Câu nói về đặc điểm chung (thì hiện tại đơn), chủ ngữ số ít → (A) ranges → chọn (A). (B) ranger là danh từ 'kiểm lâm', (C) ranged là quá khứ (không hợp thì), (D) ranging là V-ing, không làm động từ chính của mệnh đề quan hệ.\nDịch: ... tất cả tủ lạnh đều bắt buộc phải có nhiệt kế đo được trong khoảng từ 0°F (-18°C) đến 220°F (104°C)."},{"n":144,"opts":["size","safety","reliability","placement"],"ans":"D","xp":"Từ vựng (danh từ). Câu ngay sau: 'Thermometers should always be located in the warmest spot in the refrigerator' (nhiệt kế phải được đặt ở chỗ ấm nhất) → điều cần cân nhắc là vị trí đặt. (D) placement 'việc đặt, vị trí đặt' → chọn (D). (A) size 'kích thước', (B) safety 'sự an toàn', (C) reliability 'độ tin cậy' không được giải thích ở các câu sau.\nDịch: Một điều quan trọng khác cần cân nhắc là vị trí đặt nhiệt kế."},{"n":145,"opts":["Remove them carefully.","This is typically inside the door.","It should be kept cool at all times.","They can also be purchased in bulk."],"ans":"B","xp":"Điền câu. Câu trước: nhiệt kế phải đặt ở 'the warmest spot in the refrigerator'; câu sau: 'This location is also appropriate because ... as soon as the door is opened' (vị trí này CŨNG phù hợp vì ... ngay khi mở cửa). Câu (B) 'Chỗ này thường là ở phía trong cửa tủ' cho biết chỗ ấm nhất là ở đâu, và 'This location' ở câu sau chỉ chính vị trí 'inside the door' → chọn (B). (A) 'tháo chúng ra cẩn thận', (C) 'luôn giữ lạnh', (D) 'có thể mua số lượng lớn' không nối được với 'This location'.\n(A) Hãy tháo chúng ra cẩn thận.\n(B) Chỗ này thường là ở phía trong cửa tủ.\n(C) Nó phải luôn được giữ lạnh.\n(D) Chúng cũng có thể được mua với số lượng lớn."},{"n":146,"opts":["sold","seen","repaired","removed"],"ans":"B","xp":"Từ vựng (quá khứ phân từ). Nhiệt kế đặt phía trong cửa tủ nên khi vừa mở cửa là thấy ngay → (B) seen 'được nhìn thấy' → 'allows the thermometer to be easily seen' → chọn (B). (A) sold 'được bán', (C) repaired 'được sửa', (D) removed 'được tháo ra' không hợp nghĩa.\nDịch: Vị trí này cũng phù hợp vì nó giúp dễ dàng nhìn thấy nhiệt kế ngay khi mở cửa tủ."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> &lt;m_castillo@rapidonet.com.ph&gt;</p><p><b>From:</b> &lt;no-reply@rapidonet.com.ph&gt;</p><p><b>Date:</b> 19 June</p><p><b>Subject:</b> Rapido Net</p></div><p>We have noticed some activity on your account. Your secret-question option for password recovery was updated at 3:16 P.M. today. If you initiated this update, no further action is necessary. If not, we can help you secure your account. Call 919-555-1066 to speak to an account representative.</p><p>If you would like to remove the secret-question password recovery option, you may use a verified e-mail address or phone number to access your account instead. Make the process even more secure by setting up two-step verification. Just ask our representative how.</p><p>Thank you for trusting Rapido Net as your Internet service provider.</p>"],"vi":"Đến: m_castillo@rapidonet.com.ph\nTừ: no-reply@rapidonet.com.ph\nNgày: 19 tháng 6\nTiêu đề: Rapido Net\n\nChúng tôi nhận thấy có hoạt động trên tài khoản của bạn. Tùy chọn câu hỏi bí mật để khôi phục mật khẩu của bạn đã được cập nhật lúc 3:16 chiều nay. Nếu chính bạn thực hiện cập nhật này thì bạn không cần làm gì thêm. Nếu không phải, chúng tôi có thể giúp bạn bảo vệ tài khoản. Hãy gọi 919-555-1066 để nói chuyện với nhân viên phụ trách tài khoản.\n\nNếu bạn muốn bỏ tùy chọn khôi phục mật khẩu bằng câu hỏi bí mật, bạn có thể dùng một địa chỉ e-mail hoặc số điện thoại đã xác minh để truy cập tài khoản. Hãy làm cho quy trình này an toàn hơn nữa bằng cách thiết lập xác minh hai bước. Chỉ cần hỏi nhân viên của chúng tôi cách làm.\n\nCảm ơn bạn đã tin tưởng Rapido Net làm nhà cung cấp dịch vụ Internet của mình.","qs":[{"n":147,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To welcome a new user to Rapido Net","To remind a user about a forgotten password","To confirm that a change was made to a user's account","To inform a user about new company policies"],"ans":"C","xp":"Dạng câu hỏi mục đích. Câu mở đầu: \"Your secret-question option for password recovery was updated at 3:16 P.M. today.\" → e-mail báo cho người dùng biết tài khoản vừa có thay đổi (cập nhật câu hỏi bí mật) → 'a change was made to a user's account'. Chọn (C).\n(B) sai: e-mail không nhắc về mật khẩu bị quên; (A), (D) không được nhắc đến.\n(A) Chào mừng người dùng mới đến với Rapido Net\n(B) Nhắc người dùng về mật khẩu đã quên\n(C) Xác nhận rằng tài khoản của người dùng vừa có thay đổi\n(D) Thông báo cho người dùng về chính sách mới của công ty"},{"n":148,"q":"What is indicated about Rapido Net?","qvi":"Điều gì được nêu về Rapido Net?","opts":["It provides faster Internet speeds than its competitors.","It offers extra security through two-step verification.","It automatically generates complex passwords for customers.","It has increased its monthly user fee."],"ans":"B","xp":"Dạng câu hỏi chi tiết. Đoạn 2: \"Make the process even more secure by setting up two-step verification. Just ask our representative how.\" → Rapido Net cung cấp bảo mật thêm bằng xác minh hai bước ('even more secure' = 'extra security'). Chọn (B).\nCác phương án khác (tốc độ, tạo mật khẩu tự động, tăng phí) không được nhắc đến.\n(A) Nó cung cấp tốc độ Internet nhanh hơn đối thủ.\n(B) Nó cung cấp thêm bảo mật qua xác minh hai bước.\n(C) Nó tự động tạo mật khẩu phức tạp cho khách hàng.\n(D) Nó đã tăng phí người dùng hàng tháng."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> &lt;lduberville@futuremail.co.uk&gt;</p><p><b>From:</b> &lt;support@globaltech.co.uk&gt;</p><p><b>Date:</b> 23 March</p><p><b>Subject:</b> Residential service</p></div><p>Dear Ms. Duberville,</p><p>Thanks for your order. We are very pleased to have you as a new customer and are contacting you to request that you set up an appointment for one of our representatives to install a Global Tech modem at your home. Please go online and select a 30-minute window out of the four we have posted to your account.</p><p>In preparation for our visit, please clear the area on the wall where you would like us to install the modem. Setting up the modem will take just a few minutes, after which you will be able to enjoy our service.</p><p>We will use the phone number listed on your account the morning of the appointment to confirm the visit. Let us know at this time if you have any questions for us.</p><p>Sincerely,</p><p>Gordon Mackey<br>Customer Service, Global Tech</p>"],"vi":"Đến: lduberville@futuremail.co.uk\nTừ: support@globaltech.co.uk\nNgày: 23 tháng 3\nTiêu đề: Dịch vụ cho hộ gia đình\n\nKính gửi chị Duberville,\n\nCảm ơn chị đã đặt hàng. Chúng tôi rất vui khi có chị là khách hàng mới và liên hệ để đề nghị chị đặt một cuộc hẹn để nhân viên của chúng tôi đến lắp đặt modem Global Tech tại nhà chị. Vui lòng lên mạng và chọn một khung giờ 30 phút trong số bốn khung giờ chúng tôi đã đăng trên tài khoản của chị.\n\nĐể chuẩn bị cho chuyến ghé thăm, vui lòng dọn trống khu vực trên tường nơi chị muốn chúng tôi lắp modem. Việc lắp đặt modem chỉ mất vài phút, sau đó chị có thể sử dụng dịch vụ của chúng tôi.\n\nVào buổi sáng ngày hẹn, chúng tôi sẽ gọi đến số điện thoại ghi trong tài khoản của chị để xác nhận chuyến ghé thăm. Hãy cho chúng tôi biết vào lúc đó nếu chị có câu hỏi nào.\n\nTrân trọng,\n\nGordon Mackey\nBộ phận Chăm sóc Khách hàng, Global Tech","qs":[{"n":149,"q":"What kind of service has Ms. Duberville most likely contracted?","qvi":"Chị Duberville nhiều khả năng đã đăng ký loại dịch vụ nào?","opts":["Window installation","House cleanup","Wall-to-wall carpeting","Internet access"],"ans":"D","xp":"Dạng câu hỏi suy luận. E-mail nói nhân viên sẽ đến \"install a Global Tech modem at your home\" và sau khi lắp modem \"you will be able to enjoy our service\". Modem dùng để kết nối mạng → dịch vụ chị đăng ký là truy cập Internet. Chọn (D).\n(C) gây nhiễu vì có từ 'wall' (bức tường để gắn modem), nhưng không liên quan đến thảm.\n(A) Lắp đặt cửa sổ\n(B) Dọn dẹp nhà cửa\n(C) Trải thảm kín sàn\n(D) Truy cập Internet"},{"n":150,"q":"What will happen at the time selected by Ms. Duberville?","qvi":"Điều gì sẽ xảy ra vào thời gian chị Duberville chọn?","opts":["She will pick up some equipment at an office.","She will receive a new Global Tech mobile phone.","She will be visited by a Global Tech representative.","She will be e-mailed a customer satisfaction survey."],"ans":"C","xp":"Dạng câu hỏi chi tiết. \"...set up an appointment for one of our representatives to install a Global Tech modem at your home. Please go online and select a 30-minute window...\" → khung giờ chị chọn là lúc nhân viên Global Tech đến nhà lắp modem ('In preparation for our visit'). Chọn (C).\n(A) Chị sẽ đến văn phòng lấy thiết bị.\n(B) Chị sẽ nhận một điện thoại di động Global Tech mới.\n(C) Chị sẽ được một nhân viên Global Tech đến thăm.\n(D) Chị sẽ được gửi e-mail một bản khảo sát mức độ hài lòng của khách hàng."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Katrina Finton (1:46 P.M.)</b></p><p>Hey, Steven. I am hoping to move into a new apartment soon, and the landlord requires a letter verifying my place of employment and my income. I have written up the letter. Would you be willing to sign it today as proof that I work here at Carrino Agency?</p></div><div class=\"msg\"><p><b>Steven Khen (1:48 P.M.)</b></p><p>Double-check with Ariana Seltzer first. The human resources department usually has a form they can provide for you.</p></div><div class=\"msg\"><p><b>Katrina Finton (1:49 P.M.)</b></p><p>I tried that. They don't have a set form.</p></div><div class=\"msg\"><p><b>Steven Khen (1:50 P.M.)</b></p><p>No problem then. Bring your document over.</p></div><div class=\"msg\"><p><b>Steven Khen (1:51 P.M.)</b></p><p>By the way, the meeting about the Zaine Company Web site was moved to 3:00 P.M. You already have all your designs for their Web site ready, right?</p></div><div class=\"msg\"><p><b>Katrina Finton (1:52 P.M.)</b></p><p>I'm all set.</p></div>"],"vi":"Katrina Finton (1:46 chiều): Chào Steven. Tôi đang định sớm chuyển đến một căn hộ mới, và chủ nhà yêu cầu một lá thư xác nhận nơi làm việc và thu nhập của tôi. Tôi đã viết sẵn lá thư rồi. Anh có sẵn lòng ký vào hôm nay để làm bằng chứng rằng tôi làm việc ở Carrino Agency không?\n\nSteven Khen (1:48 chiều): Trước tiên hãy kiểm tra lại với Ariana Seltzer. Phòng nhân sự thường có sẵn một mẫu đơn họ có thể cung cấp cho cô.\n\nKatrina Finton (1:49 chiều): Tôi thử rồi. Họ không có mẫu cố định nào.\n\nSteven Khen (1:50 chiều): Vậy thì không sao. Cô mang giấy tờ qua đây đi.\n\nSteven Khen (1:51 chiều): Nhân tiện, cuộc họp về trang web của Công ty Zaine đã dời sang 3 giờ chiều. Cô đã chuẩn bị xong tất cả bản thiết kế cho trang web của họ rồi phải không?\n\nKatrina Finton (1:52 chiều): Tôi sẵn sàng hết rồi.","qs":[{"n":151,"q":"At 1:49 P.M., what does Ms. Finton most likely mean when she writes, \"I tried that\"?","qvi":"Lúc 1:49 chiều, khi viết \"I tried that\" (Tôi thử rồi), chị Finton nhiều khả năng muốn nói gì?","opts":["She signed a rental agreement.","She submitted proof of income.","She contacted Ms. Seltzer.","She filled out a form."],"ans":"C","xp":"Dạng câu hỏi hàm ý. Ngay trước đó Steven nói: \"Double-check with Ariana Seltzer first. The human resources department usually has a form...\" Katrina đáp \"I tried that. They don't have a set form.\" → 'that' = việc kiểm tra với chị Seltzer (bên nhân sự), tức là chị đã liên hệ chị Seltzer rồi. Chọn (C).\n(D) sai: phòng nhân sự không có mẫu đơn nên chị không điền form nào.\n(A) Chị đã ký hợp đồng thuê nhà.\n(B) Chị đã nộp bằng chứng thu nhập.\n(C) Chị đã liên hệ với chị Seltzer.\n(D) Chị đã điền một mẫu đơn."},{"n":152,"q":"What most likely is Ms. Finton's position?","qvi":"Chị Finton nhiều khả năng giữ vị trí gì?","opts":["Apartment manager","Office administrator","Human resources director","Web designer"],"ans":"D","xp":"Dạng câu hỏi suy luận. Steven hỏi: \"You already have all your designs for their Web site ready, right?\" và Katrina trả lời \"I'm all set.\" → chị là người làm thiết kế trang web. Chọn (D).\n(A) gây nhiễu vì chị đang thuê căn hộ; (C) là bộ phận chị đã liên hệ, không phải chức vụ của chị.\n(A) Quản lý căn hộ\n(B) Nhân viên hành chính văn phòng\n(C) Giám đốc nhân sự\n(D) Nhà thiết kế web"}]},{"ns":[153,155],"head":"Questions 153-155 refer to the following Web page.","passages":["<p>http://www.marilisprofessionalcoaching.com</p><h3>Marilis Professional Coaching: January Events</h3><p><b>January 15 at 4:30 P.M.—Job Search Support</b><br>Learn about the latest tools and techniques to help you find a rewarding entry-level job. Topics include the best Web sites for job announcements and how to use professional organizations to get job leads.</p><p><b>January 16 at 4:30 P.M.—How to Market Yourself</b><br>To set yourself apart from other job candidates, you have to effectively communicate the value you'll bring to the company. This session will help you successfully promote yourself to potential employers, both in person and through social media.</p><p><b>January 17 at 4:30 P.M.—Interview Strategies</b><br>Get tips on interview rules, common questions, and the process for what you need to do before, during, and after a job interview. This session will be interactive, featuring mock interviews with attendees.</p><p>Go to www.marilisprofessionalcoaching.com/register to sign up for any of these low-cost events. Note that all January events are virtual.</p>"],"vi":"http://www.marilisprofessionalcoaching.com\n\nMarilis Professional Coaching: Các sự kiện tháng Một\n\nNgày 15 tháng 1 lúc 4:30 chiều — Hỗ trợ tìm việc\nTìm hiểu những công cụ và kỹ thuật mới nhất giúp bạn tìm được một công việc khởi đầu đáng giá. Các chủ đề gồm những trang web tốt nhất để xem thông báo tuyển dụng và cách tận dụng các tổ chức nghề nghiệp để có thông tin việc làm.\n\nNgày 16 tháng 1 lúc 4:30 chiều — Cách tiếp thị bản thân\nĐể nổi bật hơn những ứng viên khác, bạn phải truyền đạt hiệu quả giá trị mà bạn sẽ mang lại cho công ty. Buổi này sẽ giúp bạn quảng bá bản thân thành công với các nhà tuyển dụng tiềm năng, cả khi gặp trực tiếp lẫn qua mạng xã hội.\n\nNgày 17 tháng 1 lúc 4:30 chiều — Chiến lược phỏng vấn\nNhận các mẹo về quy tắc phỏng vấn, những câu hỏi thường gặp và quy trình những việc bạn cần làm trước, trong và sau buổi phỏng vấn xin việc. Buổi này sẽ mang tính tương tác, có các buổi phỏng vấn thử với người tham dự.\n\nTruy cập www.marilisprofessionalcoaching.com/register để đăng ký bất kỳ sự kiện chi phí thấp nào trong số này. Lưu ý rằng tất cả sự kiện tháng Một đều diễn ra trực tuyến.","qs":[{"n":153,"q":"What is the purpose of the Web page?","qvi":"Mục đích của trang web là gì?","opts":["To promote career-assistance services","To announce a local job fair for recent graduates","To advertise open positions at social media companies","To describe rewarding careers in Web design and creation"],"ans":"A","xp":"Dạng câu hỏi mục đích. Trang web của 'Marilis Professional Coaching' giới thiệu các buổi \"Job Search Support\", \"How to Market Yourself\", \"Interview Strategies\" và mời \"sign up for any of these low-cost events\" → quảng bá các dịch vụ hỗ trợ nghề nghiệp/tìm việc. Chọn (A).\n(B) sai: không phải hội chợ việc làm tại địa phương (các sự kiện đều online); (C) 'social media' chỉ được nhắc như một kênh tự quảng bá; (D) không nói về nghề thiết kế web.\n(A) Quảng bá các dịch vụ hỗ trợ nghề nghiệp\n(B) Thông báo một hội chợ việc làm địa phương cho sinh viên mới tốt nghiệp\n(C) Quảng cáo các vị trí đang tuyển ở công ty mạng xã hội\n(D) Mô tả các nghề nghiệp đáng giá trong lĩnh vực thiết kế và xây dựng web"},{"n":154,"q":"According to the Web page, what will happen on January 17?","qvi":"Theo trang web, điều gì sẽ diễn ra vào ngày 17 tháng 1?","opts":["Companies will post job opportunities.","Employers will make hiring decisions.","Job candidates will attend a group interview.","Participants will practice responding to interviewers."],"ans":"D","xp":"Dạng câu hỏi chi tiết. Buổi ngày 17/1 (Interview Strategies): \"This session will be interactive, featuring mock interviews with attendees.\" → 'mock interviews' (phỏng vấn thử) = người tham gia luyện tập trả lời người phỏng vấn. Chọn (D).\n(C) sai: đây là phỏng vấn thử để luyện tập, không phải buổi phỏng vấn nhóm thật.\n(A) Các công ty sẽ đăng tin tuyển dụng.\n(B) Nhà tuyển dụng sẽ ra quyết định tuyển người.\n(C) Ứng viên sẽ tham gia một buổi phỏng vấn nhóm.\n(D) Người tham gia sẽ luyện tập trả lời người phỏng vấn."},{"n":155,"q":"What is indicated about the events?","qvi":"Điều gì được nêu về các sự kiện?","opts":["They occur each month.","They take place online.","They are for senior professionals.","They are free of charge."],"ans":"B","xp":"Dạng câu hỏi chi tiết. Câu cuối: \"Note that all January events are virtual.\" → 'virtual' (trực tuyến) = 'take place online'. Chọn (B).\n(D) sai: các sự kiện là \"low-cost\" (chi phí thấp), không phải miễn phí; (C) sai: nội dung hướng đến việc làm \"entry-level\" (mới vào nghề); (A) không được nhắc đến.\n(A) Chúng diễn ra hàng tháng.\n(B) Chúng diễn ra trực tuyến.\n(C) Chúng dành cho chuyên gia cấp cao.\n(D) Chúng miễn phí."}]},{"ns":[156,158],"head":"Questions 156-158 refer to the following review.","passages":["<h3>Eston Development Worth a Look</h3><p><i>by Marcus Watanabe</i></p><p>“Ideal residential developments combine twenty-first-century convenience with small-town charm.” That is the philosophy found in the brochure of the Homestead at Eston, a recently completed housing development just outside the town of Eston. <span class=\"pos\">[1]</span></p><p>The community has wide streets, sidewalks, and three small parks surrounding a central square. The square features a café, a restaurant, and several shops. In the northeast corner of the development, there is an activity complex that includes a gym, theater, and swimming pool. <span class=\"pos\">[2]</span> “This means you never have to leave the community unless you want to,” said Marjorie Solomon, sales director. “Once you visit, you’ll realize why so many people are purchasing homes here.”</p><p>While never leaving your development struck me as an odd idea, the Homestead planners deserve praise for creating a very attractive place to live. <span class=\"pos\">[3]</span> The planners have obviously prioritized the environment. Natural habitats have been carefully preserved, and homes and other structures have been designed to conserve water and energy.</p><p>Model homes are currently available for tours. <span class=\"pos\">[4]</span> Open houses take place 12:30–4:00 P.M. Saturdays and Sundays. Alternatively, appointments can be made by calling 856-555-0129.</p>"],"vi":"Khu dân cư Eston đáng để xem qua\n\nbởi Marcus Watanabe\n\n\"Những khu dân cư lý tưởng kết hợp sự tiện nghi của thế kỷ 21 với nét quyến rũ của thị trấn nhỏ.\" Đó là triết lý được nêu trong tờ quảng cáo của Homestead at Eston, một khu nhà ở vừa hoàn thành ngay bên ngoài thị trấn Eston. [1]\n\nKhu dân cư có đường phố rộng, vỉa hè và ba công viên nhỏ bao quanh một quảng trường trung tâm. Quảng trường có một quán cà phê, một nhà hàng và vài cửa hàng. Ở góc đông bắc của khu có một khu phức hợp hoạt động gồm phòng tập thể dục, rạp hát và hồ bơi. [2] \"Điều này có nghĩa là bạn không bao giờ phải rời khỏi khu dân cư trừ khi bạn muốn,\" Marjorie Solomon, giám đốc kinh doanh, cho biết. \"Một khi đến thăm, bạn sẽ hiểu vì sao rất nhiều người đang mua nhà ở đây.\"\n\nDù ý tưởng không bao giờ rời khỏi khu nhà của mình khiến tôi thấy hơi lạ, các nhà quy hoạch Homestead đáng được khen ngợi vì đã tạo ra một nơi sống rất hấp dẫn. [3] Các nhà quy hoạch rõ ràng đã ưu tiên môi trường. Môi trường sống tự nhiên được bảo tồn cẩn thận, và nhà ở cùng các công trình khác được thiết kế để tiết kiệm nước và năng lượng.\n\nHiện có các căn nhà mẫu để tham quan. [4] Các buổi mở cửa tham quan diễn ra từ 12:30 đến 4:00 chiều thứ Bảy và Chủ nhật. Ngoài ra, có thể đặt lịch hẹn bằng cách gọi 856-555-0129.","qs":[{"n":156,"q":"What is indicated about the activity complex?","qvi":"Điều gì được nêu về khu phức hợp hoạt động?","opts":["It has a variety of desirable features.","It is currently under construction.","It has low membership fees.","It is located in the central square."],"ans":"A","xp":"Dạng câu hỏi chi tiết. \"...there is an activity complex that includes a gym, theater, and swimming pool.\" → khu phức hợp có nhiều tiện ích hấp dẫn (phòng gym, rạp hát, hồ bơi) = 'a variety of desirable features'. Chọn (A).\n(D) sai: khu phức hợp nằm ở \"the northeast corner\" (góc đông bắc), còn quảng trường trung tâm có quán cà phê, nhà hàng, cửa hàng; (B) sai: khu nhà \"recently completed\" (vừa hoàn thành); (C) không được nhắc.\n(A) Nó có nhiều tiện ích hấp dẫn.\n(B) Nó đang được xây dựng.\n(C) Nó có phí thành viên thấp.\n(D) Nó nằm ở quảng trường trung tâm."},{"n":157,"q":"How can a prospective resident learn more about Homestead at Eston?","qvi":"Một người muốn đến ở có thể tìm hiểu thêm về Homestead at Eston bằng cách nào?","opts":["By viewing a model home online","By requesting a brochure","By visiting the community","By calling a current homeowner"],"ans":"C","xp":"Dạng câu hỏi chi tiết. \"Once you visit, you'll realize why so many people are purchasing homes here.\" và \"Model homes are currently available for tours. Open houses take place 12:30–4:00 P.M. Saturdays and Sundays.\" → người quan tâm có thể đến tham quan khu dân cư. Chọn (C).\n(A) sai: nhà mẫu được tham quan trực tiếp, không nói là xem online; (D) sai: số điện thoại dùng để đặt lịch hẹn, không phải gọi cho chủ nhà hiện tại; (B) tờ quảng cáo chỉ được nhắc đến chứ không nói hãy yêu cầu nó.\n(A) Bằng cách xem nhà mẫu trực tuyến\n(B) Bằng cách yêu cầu một tờ quảng cáo\n(C) Bằng cách đến thăm khu dân cư\n(D) Bằng cách gọi cho một chủ nhà hiện tại"},{"n":158,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"Homestead, however, is more than just a pretty place.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong [1], [2], [3], [4]?\n\"Tuy nhiên, Homestead không chỉ là một nơi đẹp.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"Dạng câu hỏi điền câu. Trước [3]: \"...the Homestead planners deserve praise for creating a very attractive place to live.\" ('a very attractive place' ↔ 'a pretty place'). Sau [3]: \"The planners have obviously prioritized the environment.\" → câu chèn vào nối hai ý: Homestead không chỉ đẹp (ý trước) mà còn thân thiện với môi trường (ý sau); 'however' đánh dấu sự chuyển ý này. Chọn (C) [3].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[159,160],"head":"Questions 159-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>From:</b> Stefan Fonsman &lt;sfonsman@kaybunconstruction.ca&gt;</p><p><b>To:</b> Rita Palore &lt;rpalore@palorecement.ca&gt;</p><p><b>Subject:</b> Palore Cement</p><p><b>Date:</b> March 2</p></div><p>Dear Ms. Palore,</p><p>Thank you for sending your estimate for the cement work on our apartment project in Smithville. The narrative accompanying your bid answered all of our questions, and my team was impressed by your firm’s previous work and references. Your company is my first choice to take on the project.</p><p>Nonetheless, I still need budget approval from my director, Anita Cho. Your proposed price is a bit steeper than anticipated. I will be speaking with Ms. Cho about this tomorrow morning. Based on your company’s reputation for outstanding work, I am confident that she will sign off on your bid.</p><p>I expect to get back to you by March 4.</p><p>Regards,</p><p>Stefan Fonsman<br>Kaybun Construction</p>"],"vi":"Từ: Stefan Fonsman <sfonsman@kaybunconstruction.ca>\nĐến: Rita Palore <rpalore@palorecement.ca>\nTiêu đề: Palore Cement\nNgày: 2 tháng 3\n\nKính gửi chị Palore,\n\nCảm ơn chị đã gửi bản báo giá cho phần việc đổ xi măng của dự án căn hộ của chúng tôi ở Smithville. Phần mô tả đi kèm hồ sơ dự thầu của chị đã trả lời mọi câu hỏi của chúng tôi, và nhóm của tôi rất ấn tượng với các công trình trước đây cũng như thư giới thiệu của công ty chị. Công ty chị là lựa chọn hàng đầu của tôi để đảm nhận dự án.\n\nTuy vậy, tôi vẫn cần giám đốc của tôi, bà Anita Cho, phê duyệt ngân sách. Mức giá chị đề xuất hơi cao hơn dự kiến. Tôi sẽ trao đổi với bà Cho về việc này vào sáng mai. Dựa trên danh tiếng làm việc xuất sắc của công ty chị, tôi tin rằng bà ấy sẽ duyệt hồ sơ dự thầu của chị.\n\nTôi dự kiến sẽ phản hồi chị trước ngày 4 tháng 3.\n\nTrân trọng,\n\nStefan Fonsman\nKaybun Construction","qs":[{"n":159,"q":"What is one purpose of the e-mail?","qvi":"Một mục đích của e-mail là gì?","opts":["To introduce a new owner","To acknowledge receipt of an estimate","To invite team members to a presentation","To ask for additional work references"],"ans":"B","xp":"Dạng câu hỏi mục đích. Câu đầu: \"Thank you for sending your estimate for the cement work...\" → cảm ơn vì đã gửi báo giá = xác nhận đã nhận được bản báo giá ('acknowledge receipt of an estimate'). Chọn (B).\n(D) sai: nhóm đã hài lòng với \"previous work and references\", không xin thêm; (A), (C) không được nhắc.\n(A) Giới thiệu một chủ sở hữu mới\n(B) Xác nhận đã nhận được bản báo giá\n(C) Mời các thành viên nhóm đến một buổi thuyết trình\n(D) Yêu cầu thêm thư giới thiệu công việc"},{"n":160,"q":"When will Mr. Fonsman meet with Ms. Cho?","qvi":"Khi nào anh Fonsman sẽ gặp bà Cho?","opts":["On March 2","On March 3","On March 4","On March 5"],"ans":"B","xp":"Dạng câu hỏi chi tiết (suy ra từ ngày). E-mail gửi ngày \"March 2\" và viết: \"I will be speaking with Ms. Cho about this tomorrow morning.\" → 'tomorrow' = ngày 3 tháng 3. Chọn (B).\n(C) gây nhiễu: March 4 là hạn anh dự kiến phản hồi chị Palore (\"I expect to get back to you by March 4\").\n(A) Vào ngày 2 tháng 3\n(B) Vào ngày 3 tháng 3\n(C) Vào ngày 4 tháng 3\n(D) Vào ngày 5 tháng 3"}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following announcement.","passages":["<h3>City of Altamesa seeks election workers</h3><p><u>Who is qualified to be an election worker?</u> Almost anyone, including homemakers and professionals, as well as those who are unemployed, self-employed, or retired.</p><p><u>Requirements:</u></p><ul><li>Available 6 A.M. to 1 P.M. or 1 P.M. to 8 P.M. on March 5, June 7, and November 1</li><li>Is not a politician and does not live with or work for a politician</li><li>Is 18 years of age or older</li><li>Is comfortable interacting with the public</li><li>Is organized and detail-oriented</li></ul><p>Workers must attend a four-hour pre-election training workshop on March 4 and will be compensated based on their title:<br>Election Assistant, $18/hour<br>Election Clerk, $20/hour<br>Election Chief, $22/hour</p><p>For details or to apply, visit www.altamesaelections.gov/apply.</p>"],"vi":"Thành phố Altamesa tuyển nhân viên bầu cử\n\nAi đủ điều kiện làm nhân viên bầu cử? Hầu như bất kỳ ai, kể cả người nội trợ và người đi làm chuyên môn, cũng như những người thất nghiệp, tự kinh doanh hoặc đã nghỉ hưu.\n\nYêu cầu:\n• Có thể làm từ 6 giờ sáng đến 1 giờ chiều hoặc từ 1 giờ chiều đến 8 giờ tối vào các ngày 5 tháng 3, 7 tháng 6 và 1 tháng 11\n• Không phải là chính trị gia và không sống cùng hay làm việc cho chính trị gia\n• Từ 18 tuổi trở lên\n• Thoải mái khi giao tiếp với công chúng\n• Ngăn nắp và chú ý đến chi tiết\n\nNhân viên phải tham dự một buổi tập huấn trước bầu cử kéo dài bốn tiếng vào ngày 4 tháng 3 và sẽ được trả công theo chức danh:\nTrợ lý bầu cử: 18 đô la/giờ\nThư ký bầu cử: 20 đô la/giờ\nTrưởng ban bầu cử: 22 đô la/giờ\n\nĐể biết chi tiết hoặc nộp đơn, hãy truy cập www.altamesaelections.gov/apply.","qs":[{"n":161,"q":"What information is included in the announcement?","qvi":"Thông báo có bao gồm thông tin nào?","opts":["Rates of pay","Work site locations","The application deadline","The training workshop's start time"],"ans":"A","xp":"Dạng câu hỏi chi tiết. Thông báo ghi \"will be compensated based on their title: Election Assistant, $18/hour; Election Clerk, $20/hour; Election Chief, $22/hour\" → có thông tin mức lương theo giờ ('rates of pay'). Chọn (A).\n(B) địa điểm làm việc, (C) hạn nộp đơn không được nêu; (D) chỉ có ngày tập huấn (March 4) và thời lượng (four-hour), không có giờ bắt đầu.\n(A) Mức lương\n(B) Địa điểm làm việc\n(C) Hạn chót nộp đơn\n(D) Giờ bắt đầu buổi tập huấn"},{"n":162,"q":"What does the announcement suggest is a requirement for being hired?","qvi":"Thông báo cho thấy điều gì là một yêu cầu để được tuyển?","opts":["Interest in politics","A high school diploma","A voter registration card","Good communication skills"],"ans":"D","xp":"Dạng câu hỏi suy luận. Trong mục Requirements: \"Is comfortable interacting with the public\" → phải thoải mái giao tiếp với công chúng, tức là cần kỹ năng giao tiếp tốt. Chọn (D).\n(A) sai: ngược lại, ứng viên không được là chính trị gia hay làm việc cho chính trị gia; (B), (C) không được nhắc (chỉ yêu cầu từ 18 tuổi).\n(A) Quan tâm đến chính trị\n(B) Bằng tốt nghiệp trung học\n(C) Thẻ đăng ký cử tri\n(D) Kỹ năng giao tiếp tốt"},{"n":163,"q":"What is mentioned about the training workshop?","qvi":"Điều gì được nhắc đến về buổi tập huấn?","opts":["It is offered three times a year.","It is led by an experienced election official.","It is required for all election workers.","It is available both online and in person."],"ans":"C","xp":"Dạng câu hỏi chi tiết. \"Workers must attend a four-hour pre-election training workshop on March 4\" → 'must attend' = bắt buộc với tất cả nhân viên bầu cử. Chọn (C).\n(A) gây nhiễu: ba ngày (March 5, June 7, November 1) là các ngày bầu cử/làm việc, còn buổi tập huấn chỉ có một ngày March 4; (B), (D) không được nhắc.\n(A) Nó được tổ chức ba lần một năm.\n(B) Nó do một quan chức bầu cử giàu kinh nghiệm hướng dẫn.\n(C) Nó là bắt buộc đối với tất cả nhân viên bầu cử.\n(D) Nó có cả hình thức trực tuyến và trực tiếp."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following e-mail.","passages":["<h4>*E-mail*</h4><div class=\"hdr\"><p><b>To:</b> Jihyang Lee &lt;jlee@myemail.com&gt;</p><p><b>From:</b> Robert Wang &lt;rwang@frontstreetbank.com&gt;</p><p><b>Date:</b> April 7</p><p><b>Subject:</b> Is VIS for you?</p></div><p>Dear Ms. Lee:</p><p>You are now able to enroll in Front Street Bank’s new Voice Identification System (VIS). VIS is a fast, convenient, and secure way to access and control your bank accounts by phone. <span class=\"pos\">[1]</span> For example, you can make a payment on a Front Street Bank loan by saying “loan payment.” You can check your credit-card transactions by saying “recent transactions.” You can even transfer money between accounts by saying “transfer.” Discover all the ways VIS can simplify your banking life at www.frontstreetbank.com/VIS. <span class=\"pos\">[2]</span></p><p>Your voice identification is stored securely by Front Street Bank and can be used only with Front Street Bank. Call 615-555-0189 to set up VIS for your accounts. <span class=\"pos\">[3]</span> If in the future you no longer wish to use VIS to access your account, simply call to have one of our customer-service representatives delete your identification file.</p><p><span class=\"pos\">[4]</span> Thank you for being a valued Front Street Bank customer.</p><p>Sincerely,</p><p>Robert Wang, Branch Manager</p>"],"vi":"Đến: Jihyang Lee <jlee@myemail.com>\nTừ: Robert Wang <rwang@frontstreetbank.com>\nNgày: 7 tháng 4\nTiêu đề: VIS có phù hợp với bạn không?\n\nKính gửi chị Lee:\n\nGiờ đây chị có thể đăng ký Hệ thống Nhận dạng Giọng nói (VIS) mới của Ngân hàng Front Street. VIS là cách nhanh chóng, tiện lợi và an toàn để truy cập và quản lý tài khoản ngân hàng của chị qua điện thoại. [1] Ví dụ, chị có thể thanh toán khoản vay tại Ngân hàng Front Street bằng cách nói \"loan payment\" (thanh toán khoản vay). Chị có thể kiểm tra các giao dịch thẻ tín dụng bằng cách nói \"recent transactions\" (giao dịch gần đây). Chị thậm chí có thể chuyển tiền giữa các tài khoản bằng cách nói \"transfer\" (chuyển khoản). Hãy khám phá tất cả những cách VIS có thể đơn giản hóa việc giao dịch ngân hàng của chị tại www.frontstreetbank.com/VIS. [2]\n\nDữ liệu nhận dạng giọng nói của chị được Ngân hàng Front Street lưu trữ an toàn và chỉ có thể sử dụng với Ngân hàng Front Street. Hãy gọi 615-555-0189 để thiết lập VIS cho các tài khoản của chị. [3] Nếu sau này chị không muốn dùng VIS để truy cập tài khoản nữa, chỉ cần gọi điện để một nhân viên chăm sóc khách hàng của chúng tôi xóa hồ sơ nhận dạng của chị.\n\n[4] Cảm ơn chị đã là khách hàng quý giá của Ngân hàng Front Street.\n\nTrân trọng,\n\nRobert Wang, Giám đốc chi nhánh","qs":[{"n":164,"q":"What is the purpose of the e-mail?","qvi":"Mục đích của e-mail là gì?","opts":["To welcome a new customer","To report an account error","To confirm approval of a loan","To promote a new service"],"ans":"D","xp":"Dạng câu hỏi mục đích. \"You are now able to enroll in Front Street Bank's new Voice Identification System (VIS). VIS is a fast, convenient, and secure way...\" → e-mail giới thiệu và quảng bá dịch vụ mới VIS. Chọn (D).\n(A) sai: chị Lee đã là khách hàng (\"a valued Front Street Bank customer\"); (C) 'loan payment' chỉ là ví dụ lệnh giọng nói; (B) không được nhắc.\n(A) Chào mừng khách hàng mới\n(B) Báo cáo lỗi tài khoản\n(C) Xác nhận khoản vay đã được duyệt\n(D) Quảng bá một dịch vụ mới"},{"n":165,"q":"What is indicated about VIS?","qvi":"Điều gì được nêu về VIS?","opts":["It provides voice access to accounts.","It can be used at various financial institutions.","It requires customers to pay a fee.","It is available only during designated hours."],"ans":"A","xp":"Dạng câu hỏi chi tiết. \"VIS is a fast, convenient, and secure way to access and control your bank accounts by phone\" và các ví dụ ra lệnh bằng cách nói (\"by saying...\") → VIS cho phép truy cập tài khoản bằng giọng nói. Chọn (A).\n(B) sai: \"can be used only with Front Street Bank\"; (C), (D) không được nhắc.\n(A) Nó cho phép truy cập tài khoản bằng giọng nói.\n(B) Nó có thể dùng ở nhiều tổ chức tài chính khác nhau.\n(C) Nó yêu cầu khách hàng trả phí.\n(D) Nó chỉ dùng được trong những giờ quy định."},{"n":166,"q":"What should a customer do to cancel VIS?","qvi":"Khách hàng nên làm gì để hủy VIS?","opts":["Visit a local bank branch","Make a telephone call","Complete an online form","Send an e-mail to customer service"],"ans":"B","xp":"Dạng câu hỏi chi tiết. \"If in the future you no longer wish to use VIS to access your account, simply call to have one of our customer-service representatives delete your identification file.\" → 'no longer wish to use' = hủy dịch vụ; 'simply call' = gọi điện thoại. Chọn (B).\n(A) Đến chi nhánh ngân hàng gần nhà\n(B) Gọi điện thoại\n(C) Điền một mẫu đơn trực tuyến\n(D) Gửi e-mail đến bộ phận chăm sóc khách hàng"},{"n":167,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong?\n\"You can perform numerous specific tasks.\"","qvi":"Câu sau phù hợp nhất với vị trí nào trong [1], [2], [3], [4]?\n\"Chị có thể thực hiện nhiều tác vụ cụ thể.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"A","xp":"Dạng câu hỏi điền câu. Trước [1]: VIS là cách \"to access and control your bank accounts by phone\". Sau [1]: \"For example, you can make a payment... You can check... You can even transfer money...\" → câu chèn nói chung chung 'nhiều tác vụ cụ thể', rồi 'For example' liệt kê các tác vụ đó (thanh toán khoản vay, kiểm tra giao dịch, chuyển tiền). Chọn (A) [1].\n(A) [1]\n(B) [2]\n(C) [3]\n(D) [4]"}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following advertisement.","passages":["<h3>Thumbnail Publishing Ltd.</h3><p>Four new titles in the Enterprise series have just been released. Buy one, get one 50 percent off when you purchase from our Web site by November 30 (excludes shipping). Order your copies today!</p><p><i>Maestro</i> by Christine Menon<br>A biography of famous executive Haruto Yamada, with insight into how his career influenced business governance. Paperback €14.99</p><p><i>Working Under Moonbeams</i> by Chang-Ho Jin<br>Commerce in twentieth-century Korea as illuminated through interviews with former trade company employees. Hardcover €22.99, Audiobook €8.99</p><p><i>The Connections Unseen</i> by Mai Quang Vinh<br>A collection of transcribed lectures and archival photos from Gloria de Leon’s 40-year career as a professor of business administration. Hardcover €25.99</p><p><i>Flashback</i> by Jack Olivier<br>A former Australian trade commissioner recalls the highs and lows of his diplomatic career in this engaging memoir. Paperback €14.99, Downloadable e-book €9.99</p>"],"vi":"Thumbnail Publishing Ltd.\n\nBốn đầu sách mới trong bộ Enterprise vừa được phát hành. Mua một cuốn, cuốn thứ hai giảm 50% khi bạn mua trên trang web của chúng tôi trước ngày 30 tháng 11 (không bao gồm phí vận chuyển). Hãy đặt sách ngay hôm nay!\n\nMaestro – tác giả Christine Menon\nCuốn tiểu sử về giám đốc điều hành nổi tiếng Haruto Yamada, cùng những góc nhìn về cách sự nghiệp của ông đã ảnh hưởng đến quản trị doanh nghiệp. Bìa mềm 14,99 euro\n\nWorking Under Moonbeams – tác giả Chang-Ho Jin\nThương mại ở Hàn Quốc thế kỷ 20 được làm sáng tỏ qua các cuộc phỏng vấn với những cựu nhân viên công ty thương mại. Bìa cứng 22,99 euro, Sách nói 8,99 euro\n\nThe Connections Unseen – tác giả Mai Quang Vinh\nTuyển tập các bài giảng được chép lại và ảnh tư liệu lưu trữ từ 40 năm sự nghiệp giáo sư quản trị kinh doanh của Gloria de Leon. Bìa cứng 25,99 euro\n\nFlashback – tác giả Jack Olivier\nMột cựu ủy viên thương mại người Úc kể lại những thăng trầm trong sự nghiệp ngoại giao của mình trong cuốn hồi ký hấp dẫn này. Bìa mềm 14,99 euro, Sách điện tử tải về 9,99 euro","qs":[{"n":168,"q":"What is the company offering to customers?","qvi":"Công ty đang đưa ra ưu đãi gì cho khách hàng?","opts":["A coupon for a specific author's books","A discount for ordering two books online","A reduced price for shipping","A free copy of the publisher's catalog"],"ans":"B","xp":"Dạng câu hỏi chi tiết. \"Buy one, get one 50 percent off when you purchase from our Web site by November 30\" → mua hai cuốn trên trang web thì cuốn thứ hai giảm 50% = giảm giá khi đặt hai cuốn trực tuyến. Chọn (B).\n(C) sai: ưu đãi \"excludes shipping\" (không áp dụng cho phí vận chuyển); (A), (D) không được nhắc.\n(A) Phiếu giảm giá cho sách của một tác giả cụ thể\n(B) Giảm giá khi đặt mua hai cuốn sách trực tuyến\n(C) Giảm giá phí vận chuyển\n(D) Một bản catalogue miễn phí của nhà xuất bản"},{"n":169,"q":"Who is Mr. Yamada?","qvi":"Ông Yamada là ai?","opts":["A government agent","A career counselor","A biography writer","A company leader"],"ans":"D","xp":"Dạng câu hỏi chi tiết. \"A biography of famous executive Haruto Yamada\" → 'executive' (giám đốc điều hành) = 'a company leader'. Chọn (D).\n(C) sai: người viết tiểu sử là Christine Menon, ông Yamada là nhân vật được viết về; (A) gần với Jack Olivier (cựu ủy viên thương mại).\n(A) Một nhân viên chính phủ\n(B) Một chuyên gia tư vấn nghề nghiệp\n(C) Một người viết tiểu sử\n(D) Một lãnh đạo công ty"},{"n":170,"q":"What feature is shared by all of the books described in the advertisement?","qvi":"Đặc điểm nào là chung cho tất cả các cuốn sách trong quảng cáo?","opts":["They were written by the same author.","They can be read in digital formats.","They focus on business topics.","They were translated into several languages."],"ans":"C","xp":"Dạng câu hỏi suy luận. Cả bốn cuốn thuộc bộ 'Enterprise' và đều về kinh doanh: Maestro (\"business governance\"), Working Under Moonbeams (\"Commerce... trade company\"), The Connections Unseen (\"professor of business administration\"), Flashback (\"trade commissioner\"). Chọn (C).\n(A) sai: mỗi cuốn một tác giả khác nhau; (B) sai: chỉ Flashback có e-book (Working Under Moonbeams có sách nói), Maestro và The Connections Unseen chỉ có bản in; (D) không được nhắc.\n(A) Chúng được viết bởi cùng một tác giả.\n(B) Chúng có thể đọc ở định dạng điện tử.\n(C) Chúng tập trung vào chủ đề kinh doanh.\n(D) Chúng đã được dịch sang nhiều ngôn ngữ."},{"n":171,"q":"What book includes historic images?","qvi":"Cuốn sách nào có hình ảnh lịch sử?","opts":["Maestro","Working Under Moonbeams","The Connections Unseen","Flashback"],"ans":"C","xp":"Dạng câu hỏi chi tiết. The Connections Unseen là \"A collection of transcribed lectures and archival photos\" → 'archival photos' (ảnh tư liệu lưu trữ) = 'historic images'. Chọn (C).\n(B) gây nhiễu vì nói về thế kỷ 20, nhưng là qua các cuộc phỏng vấn, không nhắc đến hình ảnh.\n(A) Maestro\n(B) Working Under Moonbeams\n(C) The Connections Unseen\n(D) Flashback"}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Priyanka Kapoor (9:41 A.M.)</b></p><p>We need to talk about the upcoming family physicians conference in London. Where do we stand?</p></div><div class=\"msg\"><p><b>Alonso Gonzalez (9:44 A.M.)</b></p><p>I’ve already purchased airline tickets for all of us.</p></div><div class=\"msg\"><p><b>Priyanka Kapoor (9:47 A.M.)</b></p><p>Great. Scott Harris will arrange our shuttle from the London airport to the conference venue. Will our mobile phones be functional outside of the Wi-Fi zones?</p></div><div class=\"msg\"><p><b>Alonso Gonzalez (9:50 A.M.)</b></p><p>I’ve researched our mobile phone provider’s international plan. It offers the ability to call and text but provides limited data options with slow download speeds.</p></div><div class=\"msg\"><p><b>Brian Kim (9:53 A.M.)</b></p><p>Let’s buy international SIM cards before we leave. We can get the prepaid cards with high-speed data and unlimited calling and texting. We won’t have to worry about being connected to Wi-Fi.</p></div><div class=\"msg\"><p><b>Priyanka Kapoor (9:57 A.M.)</b></p><p>That will solve the problem.</p></div><div class=\"msg\"><p><b>Alonso Gonzalez (9:57 A.M.)</b></p><p>Good idea, Brian. Thanks. Now let’s discuss meeting up for our meals.</p></div><div class=\"msg\"><p><b>Priyanka Kapoor (9:59 A.M.)</b></p><p>Each day of the conference begins with a continental breakfast in the lobby. Let’s meet there in the morning. I know of a great place for dinner, so let’s plan on 6:00 P.M. the first evening. We’ll decide about the other meals later.</p></div>"],"vi":"Priyanka Kapoor (9:41 sáng): Chúng ta cần bàn về hội nghị bác sĩ gia đình sắp tới ở London. Mọi việc đến đâu rồi?\n\nAlonso Gonzalez (9:44 sáng): Tôi đã mua vé máy bay cho tất cả chúng ta rồi.\n\nPriyanka Kapoor (9:47 sáng): Tuyệt. Scott Harris sẽ sắp xếp xe đưa đón chúng ta từ sân bay London đến địa điểm hội nghị. Điện thoại di động của chúng ta có dùng được bên ngoài khu vực có Wi-Fi không?\n\nAlonso Gonzalez (9:50 sáng): Tôi đã tìm hiểu gói quốc tế của nhà mạng di động của chúng ta. Gói này cho phép gọi và nhắn tin nhưng chỉ có lựa chọn dữ liệu hạn chế với tốc độ tải chậm.\n\nBrian Kim (9:53 sáng): Hãy mua thẻ SIM quốc tế trước khi đi. Chúng ta có thể mua thẻ trả trước có dữ liệu tốc độ cao và gọi, nhắn tin không giới hạn. Chúng ta sẽ không phải lo về việc kết nối Wi-Fi.\n\nPriyanka Kapoor (9:57 sáng): Vậy là giải quyết được vấn đề.\n\nAlonso Gonzalez (9:57 sáng): Ý hay đấy, Brian. Cảm ơn nhé. Giờ hãy bàn về việc gặp nhau ăn uống.\n\nPriyanka Kapoor (9:59 sáng): Mỗi ngày của hội nghị đều bắt đầu với bữa sáng kiểu lục địa ở sảnh. Hãy gặp nhau ở đó vào buổi sáng. Tôi biết một chỗ ăn tối rất tuyệt, vậy hãy hẹn 6 giờ tối ngày đầu tiên. Các bữa khác chúng ta sẽ quyết định sau.","qs":[{"n":172,"q":"Where do the writers most likely work?","qvi":"Những người nhắn tin nhiều khả năng làm việc ở đâu?","opts":["At a travel agency","At a medical office","At a transportation company","At a telecommunications firm"],"ans":"B","xp":"Dạng câu hỏi suy luận. Tin nhắn đầu tiên: \"We need to talk about the upcoming family physicians conference in London.\" → họ cùng đi dự hội nghị dành cho bác sĩ gia đình ('physicians' = bác sĩ) → nhiều khả năng họ làm ở một phòng khám/cơ sở y tế. Chọn (B).\n(A), (C), (D) gây nhiễu bằng các chủ đề trong đoạn chat (vé máy bay, xe đưa đón, SIM điện thoại), nhưng đó chỉ là việc chuẩn bị chuyến đi.\n(A) Tại một công ty du lịch\n(B) Tại một phòng khám y tế\n(C) Tại một công ty vận tải\n(D) Tại một công ty viễn thông"},{"n":173,"q":"At 9:41 A.M., what does Ms. Kapoor most likely mean when she writes, \"Where do we stand?\"","qvi":"Lúc 9:41 sáng, khi viết \"Where do we stand?\", chị Kapoor nhiều khả năng muốn nói gì?","opts":["She is requesting an update on preparations for a trip.","She wants to assess her colleagues' interest in attending an event.","She is inquiring about her colleagues' weekend activities.","She is checking staff readiness to host a conference."],"ans":"A","xp":"Dạng câu hỏi hàm ý. 'Where do we stand?' nghĩa là 'Tình hình đến đâu rồi?'. Chị vừa nói cần bàn về hội nghị ở London, và Alonso trả lời ngay \"I've already purchased airline tickets for all of us.\" → chị đang hỏi cập nhật về việc chuẩn bị cho chuyến đi. Chọn (A).\n(D) sai: họ đi dự hội nghị, không phải tổ chức; (B) sai: mọi người đều đã quyết định đi (đã mua vé cho tất cả).\n(A) Chị đang yêu cầu cập nhật tình hình chuẩn bị cho một chuyến đi.\n(B) Chị muốn đánh giá mức độ quan tâm của đồng nghiệp đối với việc tham dự một sự kiện.\n(C) Chị đang hỏi về các hoạt động cuối tuần của đồng nghiệp.\n(D) Chị đang kiểm tra mức độ sẵn sàng của nhân viên để tổ chức một hội nghị."},{"n":174,"q":"What can be concluded about the writers?","qvi":"Có thể kết luận điều gì về những người nhắn tin?","opts":["They will be traveling together.","They are preparing a presentation.","They have new mobile phone service.","They are each attending a conference for the first time."],"ans":"A","xp":"Dạng câu hỏi suy luận. \"I've already purchased airline tickets for all of us.\", \"Scott Harris will arrange our shuttle from the London airport...\", \"Let's buy international SIM cards before we leave.\", \"Let's meet there in the morning\" → họ sẽ đi cùng nhau đến London. Chọn (A).\n(C) sai: họ chỉ đang định mua SIM quốc tế, chưa có dịch vụ mới; (B), (D) không được nhắc.\n(A) Họ sẽ đi cùng nhau.\n(B) Họ đang chuẩn bị một bài thuyết trình.\n(C) Họ có dịch vụ điện thoại di động mới.\n(D) Mỗi người đều tham dự hội nghị lần đầu."},{"n":175,"q":"Why does Mr. Kim suggest SIM cards?","qvi":"Vì sao anh Kim đề xuất dùng thẻ SIM?","opts":["They are less expensive than international plans.","They can be used on any device.","They are in stock at a nearby electronics store.","They do not require a Wi-Fi connection."],"ans":"D","xp":"Dạng câu hỏi chi tiết. Chị Kapoor hỏi điện thoại có dùng được \"outside of the Wi-Fi zones\" không; anh Kim đề xuất SIM quốc tế với \"high-speed data\" và nói \"We won't have to worry about being connected to Wi-Fi.\" → SIM giúp dùng điện thoại mà không cần Wi-Fi. Chọn (D).\n(A) giá cả không được so sánh; (B), (C) không được nhắc.\n(A) Chúng rẻ hơn các gói quốc tế.\n(B) Chúng có thể dùng trên mọi thiết bị.\n(C) Chúng có sẵn ở một cửa hàng điện tử gần đó.\n(D) Chúng không cần kết nối Wi-Fi."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following job advertisement and e-mail.","passages":["<h3>BLISSFUL HORSE STABLES</h3><p>Part-time worker needed to feed, wash, and groom horses. Must be able to work a minimum of eight hours a week, including occasional weekend hours. Although training is available, applicants who have experience working with horses are preferred. To apply, send an e-mail to Dorothy Lu, dlu@blissfulhorsestables.com.au, and attach your résumé.</p><p>Blissful Horse Stables is the region's largest horse-boarding facility. It has been owned and operated by one family since 1988. Our business offers both long- and short-term boarding contracts. We have state-of-the-art indoor and outdoor exercise rings and a five-acre grazing pasture for our equine friends. A veterinarian is always on call.</p>","<div class=\"hdr\"><p><b>From:</b> ota.kyle@opalmail.com.au</p><p><b>To:</b> dlu@blissfulhorsestables.com.au</p><p><b>Subject:</b> Part-time position</p><p><b>Date:</b> 1 August</p><p><b>Attachment:</b> ota.rfg</p></div><p>Dear Ms. Lu,</p><p>This e-mail is in response to the advertisement that appeared in yesterday's edition of the <i>Colby Today</i>. At this time, I work for Ness Large Animal Clinic as a technician's assistant, but only three days a week. The part-time position you are advertising would enable me to do something I enjoy while increasing my working hours. I am happy to provide references upon request.</p><p>All the best,</p><p>Kyle Ota</p>"],"vi":"TRẠI NGỰA BLISSFUL\n\nCần tuyển nhân viên bán thời gian để cho ngựa ăn, tắm và chải lông cho ngựa. Phải có khả năng làm việc tối thiểu tám giờ mỗi tuần, bao gồm thỉnh thoảng làm vào cuối tuần. Mặc dù có đào tạo, nhưng ưu tiên ứng viên có kinh nghiệm làm việc với ngựa. Để ứng tuyển, hãy gửi e-mail cho Dorothy Lu, dlu@blissfulhorsestables.com.au, và đính kèm sơ yếu lý lịch của bạn.\n\nTrại ngựa Blissful là cơ sở nuôi giữ ngựa lớn nhất khu vực. Trại được một gia đình sở hữu và điều hành từ năm 1988. Chúng tôi cung cấp cả hợp đồng gửi nuôi dài hạn và ngắn hạn. Chúng tôi có các sân tập trong nhà và ngoài trời hiện đại bậc nhất và một đồng cỏ chăn thả rộng năm mẫu Anh cho những người bạn ngựa của chúng ta. Luôn có bác sĩ thú y trực sẵn sàng.\n\nTừ: ota.kyle@opalmail.com.au\nĐến: dlu@blissfulhorsestables.com.au\nTiêu đề: Vị trí bán thời gian\nNgày: 1 tháng 8\nĐính kèm: ota.rfg\n\nKính gửi cô Lu,\n\nE-mail này nhằm phản hồi mẩu quảng cáo đăng trên số báo hôm qua của tờ Colby Today. Hiện tại, tôi làm trợ lý kỹ thuật viên cho Phòng khám Động vật lớn Ness, nhưng chỉ ba ngày mỗi tuần. Vị trí bán thời gian mà cô đang tuyển sẽ giúp tôi được làm việc mình yêu thích đồng thời tăng số giờ làm việc. Tôi sẵn lòng cung cấp thư giới thiệu khi được yêu cầu.\n\nThân chúc,\n\nKyle Ota","qs":[{"n":176,"q":"What is NOT indicated about Blissful Horse Stables?","qvi":"Điều gì KHÔNG được nêu về Trại ngựa Blissful?","opts":["It provides grooming services.","It requires a minimum stay of three days.","It has a large, grassy field for grazing.","It is a family-run business."],"ans":"B","xp":"Câu hỏi NOT. (A) có: \"feed, wash, and groom horses\" (chải lông ngựa). (C) có: \"a five-acre grazing pasture\" (đồng cỏ chăn thả rộng 5 mẫu Anh = cánh đồng cỏ lớn). (D) có: \"owned and operated by one family since 1988\" (doanh nghiệp gia đình). Quảng cáo chỉ nói có hợp đồng \"long- and short-term\", KHÔNG hề nói phải gửi tối thiểu ba ngày → chọn (B). (Con số \"three days\" trong e-mail là số ngày Kyle làm ở phòng khám, đây là bẫy.)\n(A) Trại có dịch vụ chải lông/chăm sóc ngựa.\n(B) Trại yêu cầu gửi nuôi tối thiểu ba ngày.\n(C) Trại có một cánh đồng cỏ lớn để chăn thả.\n(D) Đây là doanh nghiệp do gia đình điều hành."},{"n":177,"q":"In the job advertisement, the word \"facility\" in paragraph 2, line 1, is closest in meaning to","qvi":"Trong quảng cáo tuyển dụng, từ \"facility\" ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["simplicity","chance","openness","center"],"ans":"D","xp":"Câu hỏi đồng nghĩa. \"the region's largest horse-boarding facility\" = cơ sở nuôi giữ ngựa lớn nhất vùng. Ở đây \"facility\" là \"cơ sở, nơi chốn phục vụ một mục đích\" → gần nghĩa với \"center\" (trung tâm). Lưu ý \"facility\" còn có nghĩa \"sự dễ dàng/khéo léo\" nhưng không hợp ngữ cảnh này.\n(A) sự đơn giản\n(B) cơ hội\n(C) sự cởi mở\n(D) trung tâm, cơ sở"},{"n":178,"q":"What most likely is Colby Today?","qvi":"Colby Today nhiều khả năng là gì?","opts":["A regional newspaper","A newsletter for horse owners","A television program","A tourism brochure"],"ans":"A","xp":"Câu hỏi suy luận. E-mail viết: \"the advertisement that appeared in yesterday's edition of the Colby Today\" – \"edition\" (số báo) phát hành hằng ngày (\"yesterday's edition\") → đây là một tờ báo. Trại ngựa lại là cơ sở lớn nhất \"the region\" nên hợp lý nhất là báo địa phương/khu vực → (A).\n(A) Một tờ báo khu vực\n(B) Một bản tin cho chủ ngựa\n(C) Một chương trình truyền hình\n(D) Một tờ rơi du lịch"},{"n":179,"q":"What is implied about Mr. Ota?","qvi":"Điều gì được ngụ ý về anh Ota?","opts":["He has experience working with animals.","He graduated from a local school.","He would like to become a journalist.","He is not able to work on weekends."],"ans":"A","xp":"Câu hỏi suy luận. \"I work for Ness Large Animal Clinic as a technician's assistant\" – anh đang làm trợ lý kỹ thuật viên ở phòng khám động vật lớn → anh có kinh nghiệm làm việc với động vật → (A). Các ý (B), (C), (D) không được nhắc đến.\n(A) Anh ấy có kinh nghiệm làm việc với động vật.\n(B) Anh ấy tốt nghiệp từ một trường địa phương.\n(C) Anh ấy muốn trở thành nhà báo.\n(D) Anh ấy không thể làm việc vào cuối tuần."},{"n":180,"q":"What has Mr. Ota most likely attached to his e-mail?","qvi":"Anh Ota nhiều khả năng đã đính kèm gì vào e-mail?","opts":["A diploma","A résumé","A letter of reference","An article about horse care"],"ans":"B","xp":"Câu hỏi liên kết 2 văn bản. Quảng cáo yêu cầu: \"send an e-mail to Dorothy Lu ... and attach your résumé\". E-mail của anh Ota gửi đến dlu@... và có \"Attachment: ota.rfg\" → tệp đính kèm chính là sơ yếu lý lịch → (B). (C) sai vì anh nói \"I am happy to provide references upon request\" – chỉ gửi thư giới thiệu khi được yêu cầu.\n(A) Bằng tốt nghiệp\n(B) Sơ yếu lý lịch (CV)\n(C) Thư giới thiệu\n(D) Bài báo về chăm sóc ngựa"}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following online form and e-mail.","passages":["<p>https://www.pinkferngardens.co.nz/contact</p><table><tr><td>About</td><td>Shop Online</td><td>Locations</td><td><b>Contact Us</b></td></tr></table><p>Located in Picton, New Zealand, Pink Fern Gardens sells a wide variety of plants, both edible and decorative. Please use the form below to submit your questions and comments.</p><p><b>Name:</b> Mia Dixon</p><p><b>E-mail:</b> mdixon@sunmail.co.nz</p><p><b>Comment:</b></p><p>I saw the callout to local growers on your social media feed. A few years ago, I started a large community food garden with my neighbours here in Helensville for us to tend in our free time. This year, we have more plants than we can consume ourselves. Specifically, we have dozens of potted mint and cardamom seedlings as well as other uncommon herbs, and I wonder if you are interested in expanding your offerings of herbs. We also have a half dozen two-year-old lemon tree saplings that are between two and three feet tall.</p>","<div class=\"hdr\"><p><b>To:</b> mdixon@sunmail.co.nz</p><p><b>From:</b> purchasing@pinkferngardens.co.nz</p><p><b>Date:</b> 12 January</p><p><b>Subject:</b> Your comment</p></div><p>Dear Ms. Dixon,</p><p>Pink Fern Gardens is always seeking uncommon plants. As for your citrus saplings, we are currently purchasing those from licensed growers only. There is a disease affecting certain varieties, so we must be cautious. We learned our lesson regarding this last autumn!</p><p>We do buy other plants from independent growers, as long as the seedlings are potted and market ready. Here are the types of seedlings we buy and the wholesale price we pay for each plant: ferns ($8), vines ($6), annual flowers ($5), and herbs for cooking, especially oregano, mint, and rosemary ($2). Please stop by at your convenience with samples of your offerings, and we can discuss our needs further in person.</p><p>Kind regards,</p><p>Ken Yoneda</p><p>Purchaser, Pink Fern Gardens</p>"],"vi":"https://www.pinkferngardens.co.nz/contact\n\nGiới thiệu | Mua sắm trực tuyến | Địa điểm | Liên hệ\n\nTọa lạc tại Picton, New Zealand, Pink Fern Gardens bán rất nhiều loại cây, cả cây ăn được lẫn cây cảnh. Vui lòng dùng biểu mẫu bên dưới để gửi câu hỏi và góp ý của bạn.\n\nTên: Mia Dixon\nE-mail: mdixon@sunmail.co.nz\nGóp ý:\nTôi đã thấy lời kêu gọi gửi đến những người trồng cây địa phương trên trang mạng xã hội của quý cửa hàng. Vài năm trước, tôi đã lập một vườn rau cộng đồng lớn cùng hàng xóm ở Helensville để chúng tôi chăm sóc lúc rảnh rỗi. Năm nay, chúng tôi có nhiều cây hơn mức mình dùng hết. Cụ thể, chúng tôi có hàng chục chậu cây con bạc hà và bạch đậu khấu cùng những loại thảo mộc hiếm khác, và tôi tự hỏi liệu quý cửa hàng có muốn mở rộng các mặt hàng thảo mộc không. Chúng tôi cũng có nửa tá cây chanh non hai năm tuổi cao từ hai đến ba feet.\n\nĐến: mdixon@sunmail.co.nz\nTừ: purchasing@pinkferngardens.co.nz\nNgày: 12 tháng 1\nTiêu đề: Góp ý của bạn\n\nKính gửi cô Dixon,\n\nPink Fern Gardens luôn tìm kiếm những loại cây hiếm. Còn về các cây họ cam chanh non của cô, hiện tại chúng tôi chỉ mua loại này từ những người trồng có giấy phép. Có một loại bệnh đang ảnh hưởng đến một số giống cây, nên chúng tôi phải thận trọng. Chúng tôi đã rút ra bài học về việc này vào mùa thu năm ngoái!\n\nChúng tôi vẫn mua các loại cây khác từ những người trồng độc lập, miễn là cây con đã được trồng trong chậu và sẵn sàng để bán. Dưới đây là các loại cây con chúng tôi mua và giá sỉ chúng tôi trả cho mỗi cây: dương xỉ (8 đô), cây leo (6 đô), hoa một năm (5 đô), và thảo mộc dùng nấu ăn, đặc biệt là kinh giới, bạc hà và hương thảo (2 đô). Mời cô ghé qua bất cứ khi nào tiện, mang theo mẫu cây của mình, và chúng ta có thể bàn thêm trực tiếp về nhu cầu của chúng tôi.\n\nTrân trọng,\n\nKen Yoneda\nNhân viên thu mua, Pink Fern Gardens","qs":[{"n":181,"q":"What motivated Ms. Dixon to contact Pink Fern Gardens?","qvi":"Điều gì khiến cô Dixon liên hệ với Pink Fern Gardens?","opts":["A positive review from a customer","An online post from Pink Fern Gardens","An article about Pink Fern Gardens","A phone message from Mr. Yoneda"],"ans":"B","xp":"Câu hỏi chi tiết. Cô Dixon viết: \"I saw the callout to local growers on your social media feed\" – cô thấy lời kêu gọi trên mạng xã hội của cửa hàng. \"social media feed\" được diễn đạt lại thành \"An online post\" (bài đăng trực tuyến) → (B).\n(A) Một đánh giá tích cực từ khách hàng\n(B) Một bài đăng trực tuyến của Pink Fern Gardens\n(C) Một bài báo về Pink Fern Gardens\n(D) Một tin nhắn điện thoại từ anh Yoneda"},{"n":182,"q":"What is indicated about Ms. Dixon?","qvi":"Điều gì được nêu về cô Dixon?","opts":["She wants to turn her hobby into a full-time business.","She would like a part-time job at Pink Fern Gardens.","She founded a community garden with her neighbors.","She is president of a gardening club in Helensville."],"ans":"C","xp":"Câu hỏi chi tiết. \"A few years ago, I started a large community food garden with my neighbours here in Helensville\" – \"started\" = \"founded\" (thành lập) → (C). Các ý còn lại không được nhắc đến (cô chỉ muốn bán số cây dư, không nói muốn kinh doanh toàn thời gian hay xin việc).\n(A) Cô ấy muốn biến sở thích thành công việc kinh doanh toàn thời gian.\n(B) Cô ấy muốn một công việc bán thời gian ở Pink Fern Gardens.\n(C) Cô ấy đã lập một khu vườn cộng đồng cùng hàng xóm.\n(D) Cô ấy là chủ tịch một câu lạc bộ làm vườn ở Helensville."},{"n":183,"q":"According to Mr. Yoneda, what happened last year?","qvi":"Theo anh Yoneda, chuyện gì đã xảy ra vào năm ngoái?","opts":["Some of his employees resigned.","Some trees his company purchased were unhealthy.","His company obtained a license to export citrus trees.","His company ran out of fruit trees to sell."],"ans":"B","xp":"Câu hỏi suy luận. Anh Yoneda viết về cây họ cam chanh: \"There is a disease affecting certain varieties, so we must be cautious. We learned our lesson regarding this last autumn!\" – họ đã \"rút ra bài học\" về dịch bệnh vào mùa thu năm ngoái, tức là năm ngoái công ty đã mua phải cây bị bệnh → (B) \"một số cây công ty mua bị bệnh\". (C) sai: chỉ nói họ mua từ người trồng có giấy phép, không nói công ty xin giấy phép xuất khẩu.\n(A) Một số nhân viên của anh ấy đã nghỉ việc.\n(B) Một số cây mà công ty anh ấy mua bị bệnh.\n(C) Công ty anh ấy được cấp phép xuất khẩu cây họ cam chanh.\n(D) Công ty anh ấy hết cây ăn quả để bán."},{"n":184,"q":"What does Mr. Yoneda ask Ms. Dixon to do?","qvi":"Anh Yoneda đề nghị cô Dixon làm gì?","opts":["Send him a list of supplies","Contact an independent grower","Buy seeds from Pink Fern Gardens","Bring some plants to Pink Fern Gardens"],"ans":"D","xp":"Câu hỏi chi tiết (yêu cầu). \"Please stop by at your convenience with samples of your offerings\" – mời cô ghé qua và mang theo mẫu cây của mình → tức là mang một số cây đến Pink Fern Gardens → (D).\n(A) Gửi cho anh ấy danh sách vật tư\n(B) Liên hệ một người trồng độc lập\n(C) Mua hạt giống từ Pink Fern Gardens\n(D) Mang một số cây đến Pink Fern Gardens"},{"n":185,"q":"How much would Mr. Yoneda pay Ms. Dixon for one of her potted seedlings?","qvi":"Anh Yoneda sẽ trả cô Dixon bao nhiêu cho một chậu cây con của cô?","opts":["$8.00","$6.00","$5.00","$2.00"],"ans":"D","xp":"Câu hỏi liên kết 2 văn bản. Cô Dixon có \"dozens of potted mint and cardamom seedlings as well as other uncommon herbs\" (cây con thảo mộc trong chậu, ví dụ bạc hà). E-mail của anh Yoneda: \"herbs for cooking, especially oregano, mint, and rosemary ($2)\" → mỗi cây thảo mộc được trả 2 đô → (D). (Cây chanh của cô thì không được mua vì họ chỉ mua cây họ cam chanh từ người trồng có giấy phép.)\n(A) 8 đô la\n(B) 6 đô la\n(C) 5 đô la\n(D) 2 đô la"}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following Web page, e-mail, and review.","passages":["<p>https://www.elektroproofrepair.com/about</p><h3>Trust Elektroproof Repair to get your computer running right again!</h3><p>Elektroproof Repair's no-surprises policy offers flat fees for labor at three price points: $145, $200, and $350. These fees do not include the cost of software or replacement parts. The majority of our repairs incur the $200 fee.</p><p>NOTE: Because of a dramatic increase in demand, we now require appointments for all services. For an initial consultation with one of our highly qualified technicians, simply select from the available time slots on our schedule page. When you schedule your appointment, we require a $60 nonrefundable deposit which will be credited toward the cost of services rendered.</p><p>If you have any questions, please e-mail us at inquiries@elektroproofrepair.com. Whenever possible, we will contact you the same day or on the following business day. Most repairs are completed within three to five business days.</p>","<div class=\"hdr\"><p><b>To:</b> Jessica Nelson &lt;jnelson17@saffronmail.com&gt;</p><p><b>From:</b> Arthur Jacquet &lt;ajacquet@elektroproofrepair.com&gt;</p><p><b>Date:</b> January 14</p><p><b>Subject:</b> Re: Tea spill, please help!</p></div><p>Dear Ms. Nelson,</p><p>Thank you for contacting Elektroproof Repair. You asked if you could bring in your laptop for inspection tomorrow, January 15. Unfortunately, we are currently booked solid through January 18. The earliest available time slot is 8:00 A.M. on January 19. Please let me know if you would like to book that slot or if you have any questions.</p><p>Sincerely,</p><p>Arthur Jacquet, Elektroproof Repair</p>","<p>https://www.buyertobuyerintel.com/repair_services/electronics/computer_devices</p><p>★★★★★</p><p>Elektroproof Repair</p><p>I spilled tea on the keyboard of my faithful old laptop, and while I dried the exterior rather quickly, I was afraid the internal components might have been ruined. Luckily for me, Elektroproof Repair came to the rescue! After booking my consultation on the Web site, I waited anxiously for a reply. Within an hour, I got an e-mail directly from the owner. Although the time slot I had requested was not available, when I responded to his e-mail to express how urgently I needed my laptop, the owner said they had an unexpected cancellation and asked if I could bring it in that very morning, which I did. Since my computer was not turned on at the time of the accident, an Elektroproof Repair technician was able to dry the computer's insides and prevent damage to the hard drive or internal circuits. Other than a new battery, no other part was needed, and Elektroproof Repair had my laptop fully functional and back in my hands within 24 hours.</p><p>—Jessica Nelson</p>"],"vi":"https://www.elektroproofrepair.com/about\n\nHãy tin tưởng Elektroproof Repair để máy tính của bạn chạy tốt trở lại!\n\nChính sách \"không bất ngờ\" của Elektroproof Repair đưa ra mức phí nhân công cố định ở ba mức giá: 145 đô, 200 đô và 350 đô. Các mức phí này không bao gồm chi phí phần mềm hoặc linh kiện thay thế. Phần lớn các ca sửa chữa của chúng tôi có mức phí 200 đô.\n\nLƯU Ý: Do nhu cầu tăng mạnh, hiện chúng tôi yêu cầu đặt lịch hẹn cho mọi dịch vụ. Để được tư vấn ban đầu với một trong những kỹ thuật viên trình độ cao của chúng tôi, bạn chỉ cần chọn khung giờ còn trống trên trang lịch hẹn. Khi đặt lịch, chúng tôi yêu cầu khoản đặt cọc 60 đô không hoàn lại, khoản này sẽ được trừ vào chi phí dịch vụ.\n\nNếu bạn có thắc mắc, vui lòng e-mail cho chúng tôi theo địa chỉ inquiries@elektroproofrepair.com. Bất cứ khi nào có thể, chúng tôi sẽ liên hệ với bạn ngay trong ngày hoặc vào ngày làm việc kế tiếp. Hầu hết các ca sửa chữa được hoàn thành trong vòng ba đến năm ngày làm việc.\n\nĐến: Jessica Nelson <jnelson17@saffronmail.com>\nTừ: Arthur Jacquet <ajacquet@elektroproofrepair.com>\nNgày: 14 tháng 1\nTiêu đề: Re: Đổ trà, xin giúp với!\n\nKính gửi cô Nelson,\n\nCảm ơn cô đã liên hệ với Elektroproof Repair. Cô hỏi liệu có thể mang máy tính xách tay đến kiểm tra vào ngày mai, 15 tháng 1 không. Rất tiếc, hiện chúng tôi đã kín lịch cho đến hết ngày 18 tháng 1. Khung giờ trống sớm nhất là 8 giờ sáng ngày 19 tháng 1. Vui lòng cho tôi biết nếu cô muốn đặt khung giờ đó hoặc nếu cô có thắc mắc gì.\n\nTrân trọng,\n\nArthur Jacquet, Elektroproof Repair\n\nhttps://www.buyertobuyerintel.com/repair_services/electronics/computer_devices\n\n★★★★★\nElektroproof Repair\n\nTôi làm đổ trà lên bàn phím chiếc laptop cũ thân thuộc của mình, và dù đã lau khô bên ngoài khá nhanh, tôi vẫn sợ các linh kiện bên trong đã bị hỏng. May mắn thay, Elektroproof Repair đã đến cứu nguy! Sau khi đặt lịch tư vấn trên trang web, tôi hồi hộp chờ phản hồi. Chưa đầy một giờ sau, tôi nhận được e-mail trực tiếp từ chủ cửa hàng. Mặc dù khung giờ tôi yêu cầu không còn trống, khi tôi trả lời e-mail để nói rằng tôi cần laptop gấp thế nào, ông chủ cho biết họ vừa có một lịch hẹn bị hủy bất ngờ và hỏi tôi có thể mang máy đến ngay sáng hôm đó không, và tôi đã mang đến. Vì máy tính không bật lúc xảy ra sự cố, một kỹ thuật viên của Elektroproof Repair đã có thể làm khô bên trong máy và ngăn ổ cứng hoặc mạch điện bên trong bị hư hại. Ngoài một viên pin mới, không cần thay linh kiện nào khác, và Elektroproof Repair đã trả lại laptop hoạt động hoàn hảo cho tôi trong vòng 24 giờ.\n\n—Jessica Nelson","qs":[{"n":186,"q":"According to the Web page, what is true about Elektroproof Repair?","qvi":"Theo trang web, điều gì đúng về Elektroproof Repair?","opts":["It recently raised its prices.","It is hiring more repair technicians.","It has experienced a sudden increase in business.","It requires full payment before work can begin."],"ans":"C","xp":"Câu hỏi chi tiết. \"Because of a dramatic increase in demand, we now require appointments for all services\" – \"dramatic increase in demand\" (nhu cầu tăng mạnh) = \"a sudden increase in business\" → (C). (D) sai vì chỉ cần đặt cọc 60 đô, không phải trả toàn bộ.\n(A) Gần đây cửa hàng đã tăng giá.\n(B) Cửa hàng đang tuyển thêm kỹ thuật viên sửa chữa.\n(C) Cửa hàng có lượng khách tăng đột ngột.\n(D) Cửa hàng yêu cầu thanh toán toàn bộ trước khi bắt đầu sửa."},{"n":187,"q":"According to the e-mail, what is the earliest date when Ms. Nelson could bring in her laptop for service?","qvi":"Theo e-mail, ngày sớm nhất cô Nelson có thể mang laptop đến sửa là ngày nào?","opts":["On January 14","On January 15","On January 18","On January 19"],"ans":"D","xp":"Câu hỏi chi tiết. \"we are currently booked solid through January 18. The earliest available time slot is 8:00 A.M. on January 19\" → (D). Ngày 15 là ngày cô muốn nhưng không còn chỗ; ngày 18 là ngày cuối cùng đã kín lịch.\n(A) Ngày 14 tháng 1\n(B) Ngày 15 tháng 1\n(C) Ngày 18 tháng 1\n(D) Ngày 19 tháng 1"},{"n":188,"q":"What is most likely true about Mr. Jacquet?","qvi":"Điều gì nhiều khả năng đúng về anh Jacquet?","opts":["He owns the business.","He is a technician.","He is a receptionist.","He delivers repaired equipment."],"ans":"A","xp":"Câu hỏi liên kết. Ông Arthur Jacquet là người viết e-mail trả lời cô Nelson. Trong bài đánh giá, cô Nelson viết: \"Within an hour, I got an e-mail directly from the owner\" → người gửi e-mail cho cô là chủ cửa hàng, vậy ông Jacquet là chủ doanh nghiệp → (A).\n(A) Ông ấy là chủ doanh nghiệp.\n(B) Ông ấy là kỹ thuật viên.\n(C) Ông ấy là nhân viên lễ tân.\n(D) Ông ấy giao thiết bị đã sửa xong."},{"n":189,"q":"According to the review, what was Ms. Nelson's main concern about her laptop?","qvi":"Theo bài đánh giá, mối lo chính của cô Nelson về chiếc laptop là gì?","opts":["That the parts inside it might be damaged","That it was too old to be repaired","That it was responding too slowly","That its operating system had a virus"],"ans":"A","xp":"Câu hỏi chi tiết. \"I was afraid the internal components might have been ruined\" – \"internal components\" = \"the parts inside it\", \"ruined\" = \"damaged\" → (A).\n(A) Các bộ phận bên trong có thể bị hỏng\n(B) Máy quá cũ để sửa\n(C) Máy phản hồi quá chậm\n(D) Hệ điều hành bị nhiễm vi-rút"},{"n":190,"q":"What is suggested about the repair of Ms. Nelson's computer?","qvi":"Điều gì được gợi ý về việc sửa máy tính của cô Nelson?","opts":["It included installing new operating software.","It was completed more quickly than advertised.","It involved the replacement of internal circuits.","It required an upgrade to the hard drive."],"ans":"B","xp":"Câu hỏi liên kết. Trang web nói: \"Most repairs are completed within three to five business days\". Bài đánh giá: \"Elektroproof Repair had my laptop fully functional and back in my hands within 24 hours\" → máy được sửa xong nhanh hơn thời gian quảng cáo → (B). (C), (D) sai vì kỹ thuật viên đã \"prevent damage to the hard drive or internal circuits\" và chỉ thay \"a new battery\".\n(A) Có cài đặt phần mềm hệ điều hành mới.\n(B) Việc sửa chữa hoàn thành nhanh hơn quảng cáo.\n(C) Phải thay mạch điện bên trong.\n(D) Phải nâng cấp ổ cứng."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following advertisement, e-mail, and receipt.","passages":["<h3>Learn to play guitar at Alexis Instruments!</h3><p>Alexis Instruments will offer group and individual guitar instruction beginning April 2. Each of our locations has been updated with newly constructed classrooms and practice rooms. Our instructors have years of experience teaching and playing as professional musicians. Call an Alexis Instruments store today for availability and pricing.</p>","<div class=\"hdr\"><p><b>To:</b> Lucia Rivera &lt;luciarivera@rapidonet.com&gt;</p><p><b>From:</b> Krista Towers &lt;ktowers@alexisinstruments.com&gt;</p><p><b>Date:</b> April 26, 8:30 A.M.</p><p><b>Subject:</b> Order TS1058293</p></div><p>Dear Ms. Rivera,</p><p>I am following up on the order you placed with us on April 23. We have only one guitar of the model you want in stock. It was used as a display sample on the floor of our salesroom here in Santa Barbara. This means it is out of the box and has been played by customers browsing the store. Our in-house luthier has thoroughly inspected the guitar, and it is still in excellent condition. There are no scratches, scuffs, or dents on it whatsoever. Because you purchased the instrument on the understanding that it was brand new, we want to offer you two options:</p><ol><li>If you do not want the floor model, you may cancel the order and receive an immediate full refund.</li><li>If you would like the floor model, we will ship it immediately and offer you a 10 percent discount off the original retail price.</li></ol><p>If you choose the latter, we will make sure the guitar is delivered to your local store in time for your first lesson there tomorrow. We apologize for the inconvenience.</p><p>Sincerely,<br>Krista Towers<br>Alexis Instruments</p>","<p><b>Alexis Instruments</b><br><b>Order number:</b> TS1058293<br><b>Date:</b> April 26</p><table><tr><th>Description</th><th>Price</th></tr><tr><td>Domingo 313 full-body acoustic guitar</td><td>$450.00</td></tr><tr><td>10% discount on guitar</td><td>-$45.00</td></tr><tr><td>Three-year repair and maintenance plan, good at any Alexis Instruments location</td><td>$75.00</td></tr><tr><td>Sales tax</td><td>$34.80</td></tr><tr><td>Total</td><td>$514.80</td></tr></table><table><tr><th>Ship To</th><th>Bill To</th></tr><tr><td>Alexis Instruments, store #23<br>3914 Joseph Drive<br>Chico, CA 95926</td><td>Lucia Rivera<br>11437 Shady Grove Lane<br>Chico, CA 95926</td></tr></table>"],"vi":"Học chơi guitar tại Alexis Instruments!\n\nAlexis Instruments sẽ mở các lớp dạy guitar theo nhóm và cá nhân bắt đầu từ ngày 2 tháng 4. Tất cả các chi nhánh của chúng tôi đều đã được nâng cấp với phòng học và phòng tập mới xây. Các giảng viên của chúng tôi có nhiều năm kinh nghiệm giảng dạy và biểu diễn với tư cách nhạc công chuyên nghiệp. Hãy gọi cho một cửa hàng Alexis Instruments ngay hôm nay để biết lịch trống và học phí.\n\nĐến: Lucia Rivera <luciarivera@rapidonet.com>\nTừ: Krista Towers <ktowers@alexisinstruments.com>\nNgày: 26 tháng 4, 8:30 sáng\nTiêu đề: Đơn hàng TS1058293\n\nKính gửi cô Rivera,\n\nTôi xin phản hồi về đơn hàng cô đã đặt với chúng tôi vào ngày 23 tháng 4. Chúng tôi chỉ còn một cây đàn guitar thuộc mẫu cô muốn trong kho. Cây đàn này từng được dùng làm mẫu trưng bày trong phòng bán hàng của chúng tôi ở Santa Barbara. Điều này có nghĩa là đàn đã được lấy ra khỏi hộp và đã được những khách hàng đến xem cửa hàng chơi thử. Thợ làm đàn của cửa hàng đã kiểm tra kỹ cây đàn, và đàn vẫn còn trong tình trạng tuyệt vời. Không hề có vết xước, vết trầy hay vết lõm nào. Vì cô mua cây đàn với hiểu biết rằng đó là hàng mới hoàn toàn, chúng tôi muốn đưa ra cho cô hai lựa chọn:\n\n1. Nếu cô không muốn cây đàn trưng bày, cô có thể hủy đơn và được hoàn tiền đầy đủ ngay lập tức.\n2. Nếu cô muốn cây đàn trưng bày, chúng tôi sẽ gửi hàng ngay và giảm cho cô 10% so với giá bán lẻ ban đầu.\n\nNếu cô chọn phương án sau, chúng tôi sẽ đảm bảo cây đàn được giao đến cửa hàng gần nhà cô kịp cho buổi học đầu tiên của cô ở đó vào ngày mai. Chúng tôi xin lỗi vì sự bất tiện này.\n\nTrân trọng,\nKrista Towers\nAlexis Instruments\n\nAlexis Instruments\nSố đơn hàng: TS1058293\nNgày: 26 tháng 4\n\nMô tả – Giá\nĐàn guitar acoustic thân đầy đủ Domingo 313 – 450,00 đô\nGiảm 10% cho đàn guitar – -45,00 đô\nGói sửa chữa và bảo dưỡng ba năm, áp dụng tại bất kỳ chi nhánh Alexis Instruments nào – 75,00 đô\nThuế bán hàng – 34,80 đô\nTổng cộng – 514,80 đô\n\nGiao đến: Alexis Instruments, cửa hàng số 23, 3914 Joseph Drive, Chico, CA 95926\nGửi hóa đơn cho: Lucia Rivera, 11437 Shady Grove Lane, Chico, CA 95926","qs":[{"n":191,"q":"What is the purpose of the advertisement?","qvi":"Mục đích của mẩu quảng cáo là gì?","opts":["To sell guitars","To promote lessons","To attract music teachers","To announce a new location"],"ans":"B","xp":"Câu hỏi mục đích. Tiêu đề \"Learn to play guitar at Alexis Instruments!\" và câu \"Alexis Instruments will offer group and individual guitar instruction beginning April 2\" → quảng cáo các lớp dạy guitar (\"instruction\" = \"lessons\") → (B). (D) sai: các chi nhánh chỉ được nâng cấp, không phải mở chi nhánh mới.\n(A) Để bán đàn guitar\n(B) Để quảng bá các lớp học\n(C) Để thu hút giáo viên âm nhạc\n(D) Để thông báo một chi nhánh mới"},{"n":192,"q":"What is most likely true about the store where Ms. Towers works?","qvi":"Điều gì nhiều khả năng đúng về cửa hàng nơi cô Towers làm việc?","opts":["It has been renovated.","It is hiring new employees.","It has more inventory than other locations.","It has extended its hours of operation."],"ans":"A","xp":"Câu hỏi liên kết. Cô Towers làm ở cửa hàng tại Santa Barbara (\"our salesroom here in Santa Barbara\") – một chi nhánh của Alexis Instruments. Quảng cáo nói: \"Each of our locations has been updated with newly constructed classrooms and practice rooms\" – mọi chi nhánh đều đã được nâng cấp, xây thêm phòng học → cửa hàng của cô cũng đã được cải tạo → (A).\n(A) Cửa hàng đã được cải tạo.\n(B) Cửa hàng đang tuyển nhân viên mới.\n(C) Cửa hàng có nhiều hàng tồn kho hơn các chi nhánh khác.\n(D) Cửa hàng đã kéo dài giờ hoạt động."},{"n":193,"q":"What does the e-mail indicate about the guitar?","qvi":"E-mail cho biết điều gì về cây đàn guitar?","opts":["It is in need of repairs.","It has been on a shelf at the store in Chico.","It was previously owned by an Alexis Instruments customer.","It is the only one of its model currently available."],"ans":"D","xp":"Câu hỏi chi tiết. \"We have only one guitar of the model you want in stock\" → đây là cây duy nhất của mẫu đó hiện còn → (D). (A) sai: \"still in excellent condition\". (B) sai: đàn trưng bày ở Santa Barbara, không phải Chico. (C) sai: khách chỉ chơi thử ở cửa hàng, không ai sở hữu nó.\n(A) Cây đàn cần được sửa.\n(B) Cây đàn đã được bày trên kệ ở cửa hàng tại Chico.\n(C) Cây đàn trước đây thuộc về một khách hàng của Alexis Instruments.\n(D) Đây là cây đàn duy nhất của mẫu này hiện còn hàng."},{"n":194,"q":"What can be inferred about Ms. Rivera?","qvi":"Có thể suy ra điều gì về cô Rivera?","opts":["She damaged her guitar.","She requested a refund.","She was previously enrolled in an online class.","She purchased the floor model."],"ans":"D","xp":"Câu hỏi liên kết. E-mail đưa ra 2 lựa chọn; nếu nhận đàn trưng bày thì được \"a 10 percent discount off the original retail price\" và đàn sẽ được giao đến cửa hàng gần nhà cô. Hóa đơn ghi \"10% discount on guitar -$45.00\" và \"Ship To: Alexis Instruments, store #23\" → cô đã chọn mua cây đàn trưng bày → (D). (B) sai vì cô không hủy đơn để hoàn tiền.\n(A) Cô ấy đã làm hỏng cây đàn.\n(B) Cô ấy đã yêu cầu hoàn tiền.\n(C) Trước đây cô ấy đã đăng ký một lớp học trực tuyến.\n(D) Cô ấy đã mua cây đàn trưng bày."},{"n":195,"q":"According to the receipt, what is true about Alexis Instruments?","qvi":"Theo hóa đơn, điều gì đúng về Alexis Instruments?","opts":["It repairs instruments in its stores.","It has two stores in Santa Barbara.","It is holding an annual sale.","It was founded by a professional musician."],"ans":"A","xp":"Câu hỏi chi tiết. Hóa đơn có dòng \"Three-year repair and maintenance plan, good at any Alexis Instruments location\" – gói sửa chữa, bảo dưỡng dùng được ở mọi chi nhánh → cửa hàng có sửa nhạc cụ → (A). Các ý còn lại không có trong hóa đơn.\n(A) Cửa hàng có sửa chữa nhạc cụ tại các chi nhánh.\n(B) Cửa hàng có hai chi nhánh ở Santa Barbara.\n(C) Cửa hàng đang tổ chức đợt giảm giá thường niên.\n(D) Cửa hàng được một nhạc công chuyên nghiệp thành lập."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following e-mails and invoice.","passages":["<div class=\"hdr\"><p><b>To:</b> All Instructors</p><p><b>From:</b> Jee-Young Choi</p><p><b>Subject:</b> New fee schedule</p><p><b>Date:</b> August 15</p></div><p>Dear Teachers,</p><p>Thank you for lending your skills as artists and educators to the Mirabel Museum of Art. Please use the updated fee schedule below when creating your monthly invoices.</p><table><tr><th>Category</th><th>Description</th><th>Duration</th><th>Fee</th></tr><tr><td>Tour</td><td>Lead group tour</td><td>60 minutes</td><td>$50</td></tr><tr><td>Tour</td><td>Lead group tour</td><td>90 minutes</td><td>$75</td></tr><tr><td>Class</td><td>Teach art class</td><td>75 minutes</td><td>$65</td></tr><tr><td>Class</td><td>Teach art class</td><td>120 minutes</td><td>$110</td></tr><tr><td>Development</td><td>Plan new course content</td><td>Varies</td><td>$200</td></tr><tr><td>Training</td><td>Instruct museum staff on a specialized topic</td><td>Varies</td><td>$25/hour</td></tr></table><p>Electronic payments should be available ten business days after invoice submission.</p><p>Jee-Young Choi, Education Coordinator</p>","<h4>Devonte Merriweather</h4><p>d.merriweather@camail.ca</p><p><b>Invoice #00278</b><br><b>For:</b> Services at the Mirabel Museum of Art<br><b>Sent:</b> September 30</p><table><tr><th>Date</th><th>Description</th><th>Fee</th></tr><tr><td>September 22</td><td>Tour: Special exhibit</td><td>$50</td></tr><tr><td>September 22</td><td>Class: Drawing for Beginners</td><td>$65</td></tr><tr><td>September 25</td><td>Class: Sculpting with Clay</td><td>$110</td></tr><tr><td></td><td><b>Total</b></td><td>$225</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Devonte Merriweather &lt;d.merriweather@camail.ca&gt;</p><p><b>From:</b> Jee-Young Choi &lt;jy.choi@mirabelmuseumofart.ca&gt;</p><p><b>Subject:</b> Payment</p><p><b>Date:</b> October 6</p></div><p>Dear Mr. Merriweather,</p><p>Thank you for submitting your September invoice. I noticed that you neglected to charge us for developing the curriculum for your sculpting class, which you taught for the first time on September 25. I checked with Carol Swann, and she said that because invoice #00278 has already been paid, it would be best if you submitted a second invoice for the development. I will ask her to process it quickly when I receive it.</p><p>You will be happy to know that the feedback from your students was very positive. I will e-mail scans of their feedback forms later today.</p><p>Best,</p><p>Jee-Young Choi, Education Coordinator</p>"],"vi":"Đến: Tất cả giảng viên\nTừ: Jee-Young Choi\nTiêu đề: Bảng phí mới\nNgày: 15 tháng 8\n\nCác thầy cô thân mến,\n\nCảm ơn quý thầy cô đã đóng góp tài năng với tư cách nghệ sĩ và nhà giáo dục cho Bảo tàng Nghệ thuật Mirabel. Vui lòng sử dụng bảng phí cập nhật dưới đây khi lập hóa đơn hằng tháng.\n\nHạng mục – Mô tả – Thời lượng – Phí\nTham quan – Dẫn đoàn tham quan – 60 phút – 50 đô\nTham quan – Dẫn đoàn tham quan – 90 phút – 75 đô\nLớp học – Dạy lớp mỹ thuật – 75 phút – 65 đô\nLớp học – Dạy lớp mỹ thuật – 120 phút – 110 đô\nPhát triển – Soạn nội dung khóa học mới – Tùy trường hợp – 200 đô\nĐào tạo – Hướng dẫn nhân viên bảo tàng về một chủ đề chuyên môn – Tùy trường hợp – 25 đô/giờ\n\nKhoản thanh toán điện tử sẽ có sau mười ngày làm việc kể từ khi nộp hóa đơn.\n\nJee-Young Choi, Điều phối viên Giáo dục\n\nDevonte Merriweather\nd.merriweather@camail.ca\n\nHóa đơn số 00278\nCho: Các dịch vụ tại Bảo tàng Nghệ thuật Mirabel\nGửi ngày: 30 tháng 9\n\nNgày – Mô tả – Phí\n22 tháng 9 – Tham quan: Triển lãm đặc biệt – 50 đô\n22 tháng 9 – Lớp học: Vẽ cho người mới bắt đầu – 65 đô\n25 tháng 9 – Lớp học: Điêu khắc bằng đất sét – 110 đô\nTổng cộng – 225 đô\n\nĐến: Devonte Merriweather <d.merriweather@camail.ca>\nTừ: Jee-Young Choi <jy.choi@mirabelmuseumofart.ca>\nTiêu đề: Thanh toán\nNgày: 6 tháng 10\n\nKính gửi anh Merriweather,\n\nCảm ơn anh đã nộp hóa đơn tháng 9. Tôi nhận thấy anh đã quên tính phí soạn giáo trình cho lớp điêu khắc mà anh dạy lần đầu vào ngày 25 tháng 9. Tôi đã hỏi lại Carol Swann, và cô ấy nói rằng vì hóa đơn số 00278 đã được thanh toán rồi, tốt nhất anh nên nộp một hóa đơn thứ hai cho phần soạn bài. Tôi sẽ nhờ cô ấy xử lý nhanh khi tôi nhận được hóa đơn.\n\nAnh sẽ vui khi biết rằng phản hồi từ học viên của anh rất tích cực. Tôi sẽ e-mail bản scan các phiếu phản hồi của họ trong hôm nay.\n\nThân mến,\n\nJee-Young Choi, Điều phối viên Giáo dục","qs":[{"n":196,"q":"What is suggested in the first e-mail about the Mirabel Museum of Art?","qvi":"E-mail thứ nhất gợi ý điều gì về Bảo tàng Nghệ thuật Mirabel?","opts":["It hires art teachers to lead tours.","It offers private tours to museum members.","Its art classes are free to the public.","Its next staff training will take place in ten days."],"ans":"A","xp":"Câu hỏi suy luận. E-mail gửi \"All Instructors\" / \"Dear Teachers\", cảm ơn họ vì \"lending your skills as artists and educators\", và bảng phí có hạng mục \"Tour – Lead group tour\" → bảo tàng thuê giáo viên mỹ thuật để dẫn đoàn tham quan → (A). (B) sai vì là \"group tour\", không phải tour riêng. (D) sai: \"ten business days\" là thời gian nhận tiền sau khi nộp hóa đơn.\n(A) Bảo tàng thuê giáo viên mỹ thuật để dẫn tour tham quan.\n(B) Bảo tàng có tour riêng cho hội viên.\n(C) Các lớp mỹ thuật của bảo tàng miễn phí cho công chúng.\n(D) Buổi đào tạo nhân viên tiếp theo sẽ diễn ra sau mười ngày."},{"n":197,"q":"What does the invoice suggest about Mr. Merriweather?","qvi":"Hóa đơn gợi ý điều gì về anh Merriweather?","opts":["He worked at the museum on September 30.","He has expertise in more than one art form.","One of his art classes was canceled.","Some of his artwork was exhibited in September."],"ans":"B","xp":"Câu hỏi suy luận. Hóa đơn cho thấy anh dạy \"Class: Drawing for Beginners\" (vẽ) và \"Class: Sculpting with Clay\" (điêu khắc) → anh thành thạo hơn một loại hình nghệ thuật → (B). (A) sai: 30/9 là ngày gửi hóa đơn (\"Sent\"). (D) sai: \"Special exhibit\" là tour anh dẫn, không phải tác phẩm của anh được trưng bày.\n(A) Anh ấy làm việc ở bảo tàng vào ngày 30 tháng 9.\n(B) Anh ấy thành thạo nhiều hơn một loại hình nghệ thuật.\n(C) Một lớp mỹ thuật của anh ấy đã bị hủy.\n(D) Một số tác phẩm của anh ấy được trưng bày vào tháng 9."},{"n":198,"q":"How long was the sculpting class that Mr. Merriweather taught?","qvi":"Lớp điêu khắc anh Merriweather dạy kéo dài bao lâu?","opts":["60 minutes","75 minutes","90 minutes","120 minutes"],"ans":"D","xp":"Câu hỏi liên kết. Hóa đơn: \"Class: Sculpting with Clay – $110\". Bảng phí trong e-mail thứ nhất: \"Class – Teach art class – 120 minutes – $110\" → lớp điêu khắc dài 120 phút → (D).\n(A) 60 phút\n(B) 75 phút\n(C) 90 phút\n(D) 120 phút"},{"n":199,"q":"According to the second e-mail, who most likely is Ms. Swann?","qvi":"Theo e-mail thứ hai, cô Swann nhiều khả năng là ai?","opts":["A bookkeeper","An art teacher","Mr. Merriweather's assistant","Director of the Mirabel Museum of Art"],"ans":"A","xp":"Câu hỏi suy luận. \"I checked with Carol Swann, and she said that because invoice #00278 has already been paid ... I will ask her to process it quickly when I receive it\" – cô Swann biết hóa đơn nào đã được thanh toán và là người xử lý hóa đơn → cô là nhân viên kế toán/sổ sách → (A).\n(A) Nhân viên kế toán (giữ sổ sách)\n(B) Một giáo viên mỹ thuật\n(C) Trợ lý của anh Merriweather\n(D) Giám đốc Bảo tàng Nghệ thuật Mirabel"},{"n":200,"q":"What can be concluded about Ms. Choi?","qvi":"Có thể kết luận điều gì về cô Choi?","opts":["She forgot to read some student feedback forms.","She believes that Mr. Merriweather is owed $200.","She meets once a month with teachers.","She rejected Mr. Merriweather's October invoice."],"ans":"B","xp":"Câu hỏi liên kết. Cô Choi viết: \"you neglected to charge us for developing the curriculum for your sculpting class\" và đề nghị anh nộp hóa đơn thứ hai \"for the development\". Bảng phí: \"Development – Plan new course content – $200\" → cô cho rằng bảo tàng còn nợ anh 200 đô → (B). (A) sai: cô sẽ gửi bản scan phiếu phản hồi, không phải quên đọc. (D) sai: hóa đơn là của tháng 9 và đã được thanh toán.\n(A) Cô ấy quên đọc một số phiếu phản hồi của học viên.\n(B) Cô ấy cho rằng anh Merriweather còn được nợ 200 đô.\n(C) Cô ấy họp với giáo viên mỗi tháng một lần.\n(D) Cô ấy đã từ chối hóa đơn tháng 10 của anh Merriweather."}]}]}};
